INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık seni sevmiyorum...', 'artik-seni-sevmiyorum-suat-aydin-gv3sc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Giderken uzaklara,

Bir elveda bile demedin.

Elini yüreğine koyup; 

Düşünmedin ki hiç.

Ne yapar, ne eder...

Artık seni sevmiyorum,

Gözlerin güzel değil artık.

Sesini duymak istemiyorum,

Ellerin bana yabancı bir ten.

Sen var ya sen; 

Öldün benim için...

Mazide kaldı o güzel günlerimiz.

Seninle değil ki sevgilimle ikimiz.

Tanımıyorum sizi, söyleyin siz kimdiniz.

Hatırlanacak birimi,

Yoksa...

Artık seni sevmiyorum...', 'Giderken uzaklara, Bir elveda bile demedin. Elini yüreğine koyup;  Düşünmedin ki hiç. Ne yapar, ne eder... Artık seni sevmiyorum, Gözlerin g...', ARRAY['Türk Edebiyatı','Şiir','Suat Aydın']::text[], 8.5, '{"poet":"Suat Aydın","poet_slug":"suat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/artik-seni-sevmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-suat-aydin-1rjya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte gidiyorum...

İstemese de gönlüm,

Yüreğimin kanı durmasa da  gidiyorum işte.

Kim bilir belki çok uzaklara; belki de çok yakınlara.

Dönmek yada dönmemek bilmiyorum.

Dedim ya zeytin gözlüm her şey kader kısmet...

Olmadı; 

Olmadı biliyorum.

Ama yüreğimde seni hep saklıyorum.

O bakışlarını,sesini unutamıyorum.

Konduramıyorum yüzüne aldatmanın kötülüğünü; kalleşliği sana yakıştıramıyorum.

İnan kahroluyorum.

Sabahlar olmuyor; ne de güneş batıyor zamanında sensiz.

Paylaşamıyorum seni bir başkasıyla; bir başkasının kollarında hayal bile edemiyorum...

Sen! 

Sen ki Allah’tan sonra gelen...

Yapmamalıydın.

Asla ve asla yapmamalıydın bunu bana...

Seni affetmiyorum! 

Ve senden hesap sormuyorum.

Bugün de,yarın da seni sevdiğimi bildiğini biliyorum.

Ama bitti, sattın beni.

Aldattın.

Ve aklınca ulaşılmazsın. 

Uzaklar da olabilirsin belki? Ama yüreğime sevdanı eken Allah her yerde.

Ve o yürek hala ben de.

Beni gören Allah’ım seni de görsün.

Yüreğin senden hesap sorsun.

Ben sevgimden o kadar eminim ki,

Ve sende bunu o kadar iyi biliyorsun ki.

Şu an görmesen de yakın da hem de çok yakında! 

Göreceksin.

Ve cezan; 

Ömrün boyunca, seni benim kadar  hiç kimsenin sevmeyeceğini bilerek yaşamak.', 'İşte gidiyorum... İstemese de gönlüm, Yüreğimin kanı durmasa da  gidiyorum işte. Kim bilir belki çok uzaklara; belki de çok yakınlara. Dönme...', ARRAY['Türk Edebiyatı','Şiir','Suat Aydın']::text[], 8.5, '{"poet":"Suat Aydın","poet_slug":"suat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gidiyorum-127-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senceben', 'senceben-suat-aydin-vtijy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatırladın mı sevgilim 

Beni bıraktığın o günü.

Terk edip de giderken 

Gözlerimdeki hüznü

Yabancıydın artık bana 

Ellerin tutmadı ellerimi

Gözlerin hiç böyle bakmadı bana

El gibi,

Dudakların konuşmadı

Bir veda busesi  bile çoktu bana...

Kader değil di bizimki.

Haykırsam neye yarar; 

İsyan etmek boşuna.

Senin için Allah’a.

Dön desem ne olur ki

Çoktan unutmuşsun beni.

Kim bilir nerelerde aklın şimdi.

Lanet olsun sana; 

Sevgine ve aşkına

Yüreğim sızlasa da 

Gözlerim kan ağlasa da 

Affetmeyeceğim seni

Sonsuza dek hatırla  beni....', 'Hatırladın mı sevgilim  Beni bıraktığın o günü. Terk edip de giderken  Gözlerimdeki hüznü Yabancıydın artık bana  Ellerin tutmadı ellerimi G...', ARRAY['Türk Edebiyatı','Şiir','Suat Aydın']::text[], 8.5, '{"poet":"Suat Aydın","poet_slug":"suat-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/senceben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
