INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeyi Kurtuluş Bilenler', 'olmeyi-kurtulus-bilenler-hasan-can-5zdqz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgiyi nefret kılan ihanettir,

Aşkı heves bilen çocuksu duygulardır,

Yaşamayı seven dertlere eyvallah çekendir,

Ölümü bilen yaşamayı sevmeyendir...

Ölmeyi kurtuluş zannedenler,

Öldükten sonra kurtuluşlarını kutlarlar,

Ama kutladıkları, sadece ölmeyi başarmalarıdır.

Öldükten sonra yeni bir dünya olduğu için sevinecekler,

Ama ölmek, sadece geri dönüşü olmayan bir dünyadır...', 'Sevgiyi nefret kılan ihanettir, Aşkı heves bilen çocuksu duygulardır, Yaşamayı seven dertlere eyvallah çekendir, Ölümü bilen yaşamayı sevmey...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmeyi-kurtulus-bilenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dünya istiyorum', 'bir-dunya-istiyorum-meryem-i-sler-u6aok', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dünya istiyorum 

Gözyaşları akmayan 

Üzerinde savaş olmayan

Çocuk ğüleşleriyle dolan

Bir dünya istiyorum 

Bulutları mutluluk saçan

Yıldızları aşkı anlatan

Güneşi insanları sıcacık saran

Bir dünya istiyorum

İnsanı insan gibi yaşatan

Yarınların korkusuyla uyandırmayan

Kardeşliğe dostluğa sevgiye kucak açan

Bir dünya istiyorum 

 Hiç bir  ülkesinde terörü olmayan

Hakkın  verdiği canı yalnız Hak alan

anaların babaların ciğerlerini yakmayan

Bir dünya istiyorum kimsenin aç kalmadığı

Yaşlıların acımadan sokağa atılmadığı

Çoculkarın iş yerine okullara yollandığı

Yaşamak için yaşanacak dünya istiyorum

İstediğim çok zor değil biliyorum', 'Bir dünya istiyorum  Gözyaşları akmayan  Üzerinde savaş olmayan Çocuk ğüleşleriyle dolan Bir dünya istiyorum  Bulutları mutluluk saçan Yıldı...', ARRAY['Türk Edebiyatı','Şiir','Meryem İşler']::text[], 8.5, '{"poet":"Meryem İşler","poet_slug":"meryem-i-sler","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-dunya-istiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çevrim', 'cevrim-zerrin-tamer-qv3tp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir döngü var içimizde

Durmadan devinen dönen,

Nasıl bir çevrimdir bu

Deliye döndüren..', 'Bir döngü var içimizde Durmadan devinen dönen, Nasıl bir çevrimdir bu Deliye döndüren.....', ARRAY['Türk Edebiyatı','Şiir','Zerrin Tamer']::text[], 8.5, '{"poet":"Zerrin Tamer","poet_slug":"zerrin-tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cevrim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınamayın Dostlar', 'kinamayin-dostlar-i-shak-ozlu-9zhea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşımda Bogaz Köprüsü.

Teybimde Merik Türküsü.

Düşen bir yagmur damlası,

Canlandı geçmişin öyküsü.

O''nunda gözünde bir damla,

Güler damlar,aglar damlardı.

Gözüm sulandı,yüregim doldu.

Görmeyeli koca beş yıl oldu.

Dolan gözlerime dur diyorum,

Taşan yüregime söz geçmiyor.

Yıllar geçsede,sevda bitmiyor.

Yagmur gözlüm aklımdan gitmiyor.

Kınamayın dostlarım,aglıyorum diye.

Demeyin erkekler aglamaz diye,

Sevmesem aglarmıyım,seviyorum.

Seven aglar,kınamayın dostlar.', 'Karşımda Bogaz Köprüsü. Teybimde Merik Türküsü. Düşen bir yagmur damlası, Canlandı geçmişin öyküsü. O''nunda gözünde bir damla, Güler damlar,...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kinamayin-dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesleri Dinle', 'sesleri-dinle-erdogan-ergin-wnbum', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesleri dinle,

Her çeşidini dinle

Kuş sesini duy, dal ormana

Koş koşabildiğin kadar

Ama bil, ne diyorlar

Kime sesleniyorlar

Sesleri dinle,

Rüzgarın sesini dinle

Tak uçurtmayı peşine

Kaldır gökyüzüne

Ama bil ne diyor

Kime sesleniyor

Arıyı dinle, 

Karıncanın ayak seslerini

Dalganın kayalara vuruşunu dinle

Düşen yaprakların sesini dinle

Ama bil, ne diyorlar

Kime sesleniyorlar

Ve şimdi düşün,

Kendini dinle

Ama bil, ne diyor

Kime sesleniyor', 'Sesleri dinle, Her çeşidini dinle Kuş sesini duy, dal ormana Koş koşabildiğin kadar Ama bil, ne diyorlar Kime sesleniyorlar Sesleri dinle, R...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sesleri-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskidendi', 'eskidendi-erdogan-ergin-47gvy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep eskiden diyorlar

Ayakkabı eskidendi eskiden

Elbise eskiden…

Dostluk eskidendi,

Bayramlar eskiden

Eskidendi 23 Nisanlar

Çocuklar eskidendi eskiden

Eller öpülürdü, ayaklar yıkanır

Peşgurler ellerde,

Büyükler yerdi önce

Sonra sıra küçüklerde

Eskidendi yaşam,

Eskidendi sevda

Şimdi e-hayat zamanı

e-aşk

e-sevda

e-saygı

e-etik

e-bayram

e-insan

eeee, yeter be…

*Peşgur : El havlusu', 'Hep eskiden diyorlar Ayakkabı eskidendi eskiden Elbise eskiden… Dostluk eskidendi, Bayramlar eskiden Eskidendi 23 Nisanlar Çocuklar eskidend...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eskidendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burada', 'burada-ahmet-etik-wjmq7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biraktigin yerde bekliyorum seni

Tek basina, sabirlan

Bugün, yarin ve hersaman

Sensiz ayrilamam ben burdan

Zaman calsada gencligimi

Aklar düsede saclarima

Yorgunluk cöksede omuslarima

Direnecegim ve bekleyecegim burada

Burdayim, ben hersaman burda

Souk ve sicak havada

Ac ve tok karina

Bekleyecegim ben hep burda

Elbette döneceksin bir gün geri

Geleceksin sende buraya

Göreceksin hic ayrilmamisim burdan

Bekliyorum halen seni

Geldiginde taniyamasam seni

Söyledigin halde cikaramasam 

Deliyimdir belki deli

Bekleyecegim demeki bir ömür boyu burada seni

Görüyorsun zaman ne hale koymus beni

Yinede unutmamisim beklemeyi

Kaderde varmis demek

Sonsusa kadar burada seni beklemek', 'Biraktigin yerde bekliyorum seni Tek basina, sabirlan Bugün, yarin ve hersaman Sensiz ayrilamam ben burdan Zaman calsada gencligimi Aklar dü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Etik']::text[], 8.5, '{"poet":"Ahmet Etik","poet_slug":"ahmet-etik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/burada-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklar', 'isiklar-orhan-mahir-kizilboga-0f0my', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birazdan bütün yıldızlar,

Bana seni getirecek.

Bütün gökyüzü,

Seni sevdiğimi haykıracak

Eskisi kadar zevkli değil buralar

Değişikliğe ihtiyacım var.

Sanırım gitme zamanı.

Ufak bir mola

Bir sürü karmaşa duvarlar.

Yazılar şiirler ve oyunlar.

Yine yalan söylüyor aynalar.

Bir yoldan başka bir yola

Karşı dağlar dolunayla aydınlık.

Dolunay noktalarla gülümsüyor.

İnci inci dökülüyor yalancı ışıklar yola,

Taaa… bir koldan bir kola.

Yaşam çekip gitmeyi istiyor benden.

Bir benden diğer bene koşuşlar var sonsuza 

Yağmurlar yağar ağır ağır….', 'Birazdan bütün yıldızlar, Bana seni getirecek. Bütün gökyüzü, Seni sevdiğimi haykıracak Eskisi kadar zevkli değil buralar Değişikliğe ihtiya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/isiklar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dualar', 'dualar-orhan-mahir-kizilboga-xgw18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durdum bugün durmak istedim

Baktım arkama yağmurlar var.

Susmalıyım kendime dedim

Buğulu camlarda yazılar.

SENİ SEVİYORUM…

Seni sevmek istiyorum.

Bu güne kadar tek bildiğim 

Yalan söyleyemez sırlı camlar

Kaybediyorum heyecanımı.

Yaşamı bilmek yada düşünmek.

Kafayı neden nasıl yediğim.

Ve bilmeyi istediğim o çok gizemli sırlar.

Durmak yok artık,

Koşmak özgürlüğe doğru.

İstesem de  artık dönemeyeceğim,

O karmaşık yaşanmış dualar.

Şiirler yazıp durur zaman

Yoksa şiirlerden mi ibaret yaşam.

Ne kadar önemli ki 

Sizin için ne söylediğim

Yine o sıkıcı 

Birbirine benzeyen hayatlar.

Tanrının krallığı her yerdedir,

Tahta yada betonlar arasında değil

Gerçekten İsa(a.s.) ’nın mı bu düşlediğim.

Taşı kaldırdığımda bulacak mıyım

Sahi mi bu yazıtlar?', 'Durdum bugün durmak istedim Baktım arkama yağmurlar var. Susmalıyım kendime dedim Buğulu camlarda yazılar. SENİ SEVİYORUM… Seni sevmek istiy...', ARRAY['Türk Edebiyatı','Şiir','Orhan Mahir Kızılboğa']::text[], 8.5, '{"poet":"Orhan Mahir Kızılboğa","poet_slug":"orhan-mahir-kizilboga","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dualar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler', 'golgeler-mehmet-lutfu-aydin-o4xkl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hayal perdesinde nice gölgeler

Dalaşmakta hayalcinin dilinden

Hayat sahnesinde nice bilgeler

Dolaşmakta, uzaklaşmış bilimden

Bir ağacın gölgesinde oturmuş

Dilenmekte hastalıklı bir adam

Bir kalantor Mercedes’e kurulmuş

İlenmekte, “Nerde kaldı bu madam? ” 

Gölgeleri mesken kılan kodaman

Pislik saçar, geceleri içerken

Ona buna posta atan kahraman 

Islık çalar mezarlıktan geçerken 

Başkasının gölgesinde serinler

Boncuk boncuk ter dökerken sıcakta

Sesi çıkmaz, dayak yer de söz dinler

Keyif çatar, fır dönerken kucakta 

“Gölge etme, başka ihsan istemem”

Demişsen de bir fıçıdan Diyojen 

Deli miydin, divane mi, bilemem

Çıkmalıydın aydınlığa önceden', 'Hayal perdesinde nice gölgeler Dalaşmakta hayalcinin dilinden Hayat sahnesinde nice bilgeler Dolaşmakta, uzaklaşmış bilimden Bir ağacın gölg...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/golgeler-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben beyazı severim.', 'ben-beyazi-severim-i-shak-ozlu-szhym', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben beyazı severim.

Sevdigimin beyaz giymesinden.

Ben beyazı severim.

Anamın ak sütü olmasından.

Dudagın hapsinde dişler beyaz.

Yanmış yürege,ayran beyaz.

Dagın yücesinde,kar beyaz.

Ben beyazı severim.

Sevdanın bakir rengidir beyaz.

Bayrağımın bir rengidir beyaz.

Sevdigimin giydigi gelinlik beyaz.

Ben severim beyazı.

Açılan dostluk sayfası beyaz.

Yazılan destan sayfası beyaz.

Aşkı ölümsüzleştiren kağıt beyaz.

Ben beyazı severim.', 'Ben beyazı severim. Sevdigimin beyaz giymesinden. Ben beyazı severim. Anamın ak sütü olmasından. Dudagın hapsinde dişler beyaz. Yanmış yüreg...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-beyazi-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekim Düşünceleri', 'ekim-dusunceleri-yalcin-ulker-t9kzl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin esmer boynuna yalınkılıç savrulan

Günün ilk ışıkları ve kanın rengi erguvan

Çalar saatlerin saatçideki sesi değil bu

Sen işçi sen memur sen öğrenci uyanan

Mavi göğe adanmış bir melodi değil hiç

Maddeciliğin çanlarıdır çalınan

Ölüm yellerinin estiği mevsimin giyotin sabahında

Aralanır modern şato kapıları ve ardından

Tiz sesli şeffaf bir borazan gibi uzanır göğe

Zor zahmet alıp verdiğimiz her nefes

Mekanik bir çığlığa dönüşür sonra her ses

İçindeyiz işte bildik kavgaların içinde

Vanası açılmış bir itfaiye hortumu gibi şişer

Bir yangın yeri telaşıyla ardımızdan caddeler

Otobüs,teslim alınmış kalabalıklar biniti

Direksiyon,kiminin ellerinde kelepçe

Bekleyenler var insafsız alacaklılar gibi

Fabrikalar işhanları daireler birde', 'Gecenin esmer boynuna yalınkılıç savrulan Günün ilk ışıkları ve kanın rengi erguvan Çalar saatlerin saatçideki sesi değil bu Sen işçi sen me...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ülker']::text[], 8.5, '{"poet":"Yalçın Ülker","poet_slug":"yalcin-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ekim-dusunceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çadır ve Taze Acı', 'cadir-ve-taze-aci-yalcin-ulker-kfvvk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin için öldü diyorlar hefle

Yokluğun ter döküyor

Kandırmaya beni

Bu acıyada alışırmışım güya

Hatta yaşama telaşıyla

Günler geçer

Hatırlarmışım seni 

Şöyle bir

Apaktı yüzün

Söylenceye göre

İyiye işaretmiş bu

Öteki yaşamında

Ve toprağın gül gibi...

Dört hastalığa birden gülümsedin sen

Mezarın diye gösterdikleri

Olsa olsa bir çadır

Bir büyük savaştan

Amansız çarpışmalardan sonra

Göğsünde dört madalya

Dineliyorsun şimdi

Toprağın gölgesinde

Hayır,sen ölmedin baba

Ölüm mutlu yaşamlar içindir

Tanrının hoyrat kullarının

Böyle yazar

OI kitabında', 'Senin için öldü diyorlar hefle Yokluğun ter döküyor Kandırmaya beni Bu acıyada alışırmışım güya Hatta yaşama telaşıyla Günler geçer Hatırlar...', ARRAY['Türk Edebiyatı','Şiir','Yalçın Ülker']::text[], 8.5, '{"poet":"Yalçın Ülker","poet_slug":"yalcin-ulker","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cadir-ve-taze-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazereti Vardır Hep Aşkın', 'mazereti-vardir-hep-askin-tevfik-karinca-sz8c1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mazereti vardır hep aşkın

Arkasına sığındığın yanlışların

Gün gelir içinden çıkamazsın

İstesende istemesende

Gerçeklerle yüzleşmek zorundasın

Mazereti vardır hep aşkın

Zamana bıraktığın akışın

Gün olur akarsa gözyaşın

Sevgi yetmez

Bir türlü nedenini anlamazsın

Mazereti vardır hep aşkın

O, çok sevip inandığın

Uğruna herşeye katlandığın

Giderse eğer

Sadece arkasından bakarsın

Anlamasan da

Mazereti vardır hep aşkın', 'Mazereti vardır hep aşkın Arkasına sığındığın yanlışların Gün gelir içinden çıkamazsın İstesende istemesende Gerçeklerle yüzleşmek zorundası...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mazereti-vardir-hep-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklın Başına Gelir', 'aklin-basina-gelir-tevfik-karinca-o34qp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yutkunursun

Mahşer gibi sarar içini sessizlik

Gönül gözünde düştüğün çaresizlik

An gelir, Adamlıktan çıkarsın

Kendi kendine konuşmaya başlarsın

Değil mi ki bu delilik

Vaktin ne kadar geciktiğini hatırlarsın

Yaptığın hatalara sende şaşarsın

An gelir, yürekten ağlarsın

Aklın başına gelir

Konuşmamak üzere susarsın

Ne vesvese kalır, ne de kuşku

Sevdiğim günlerdeki huşu

Uçtu elinden bak, gönül kuşu

An gelir, anlarsın

Seni ben gibi seven bulamayacağını

Aklın başına gelir', 'Yutkunursun Mahşer gibi sarar içini sessizlik Gönül gözünde düştüğün çaresizlik An gelir, Adamlıktan çıkarsın Kendi kendine konuşmaya başlar...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aklin-basina-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyle doldursak yerini yeniden', 'sevgiyle-doldursak-yerini-yeniden-kardelen-ceyda-u7fm2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hala dudaklarimda sicakligin var

ellerin,tenime tanidik geliyor nedense

yanimda olsan diyorum

ellerin tenimde gezinse

dudaklarim sicakliginla kavrulsa

yiksak tüm tabulari seninle

zincirlerden kurtarsak 

yasanacak yarinlari

tüketsek acilari

yasayarak yüregimizde

sonra sevgiyle doldursak

yerini yeniden...', 'hala dudaklarimda sicakligin var ellerin,tenime tanidik geliyor nedense yanimda olsan diyorum ellerin tenimde gezinse dudaklarim sicakliginl...', ARRAY['Türk Edebiyatı','Şiir','Kardelen Ceyda']::text[], 8.5, '{"poet":"Kardelen Ceyda","poet_slug":"kardelen-ceyda","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevgiyle-doldursak-yerini-yeniden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olur ya...', 'olur-ya-serap-demirturk-6vzjj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Olur ya bir gün benden haber alamazsan,

Nerdedir diye arayıp durma.

Beni kelimelerin şarkısında-

Beni şiirlerin hamamında

Sevda türküleri söylerken bul.

Olur ya bir gün benden haber alamazsan,

Nerdedir diye sakın yanma.

Beni şu karşı yayladaki

Kır çiçeklerinin  ortasında

Sevda türküleri söylerken bul.

Olur ya bir gün benden haber alamazsan,

Nerdedir diye dertlenme.

Aç yüreğinin bahçesini,

Beni, koyduğun o yerde

Sevda türküleri söylerken bul.

'' Hayatta 

 En Kötü Şey; 

 Merhaba Diyerek 

 Birleşen Ellerin, 

 Elveda Diyerek 

 Ayrılmasıdır... 

  ''', 'Olur ya bir gün benden haber alamazsan, Nerdedir diye arayıp durma. Beni kelimelerin şarkısında- Beni şiirlerin hamamında Sevda türküleri sö...', ARRAY['Türk Edebiyatı','Şiir','Serap Demirtürk']::text[], 8.5, '{"poet":"Serap Demirtürk","poet_slug":"serap-demirturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/olur-ya-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel sevdigim', 'gel-sevdigim-i-shak-ozlu-f0kv3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyah saçıma beyaz düşmeden,

Gönül sarayımda özlem pişmeden,

Gören gözümün feri geçmeden,

Gel sevdigim,Ömür bitmeden.

Sana koşan ayagım durmadan,

Gönlümdeki sevda gülün solmadan,

Uzanmış kollarım yere inmeden,

Gel sevdigim,Vakit dolmadan.

Sevginle çarpan yürek durmadan,

Can bedenden uçup gitmeden,

Topragımda yeşil ot bitmeden,

Gel sevdigim,dilim susmadan.', 'Siyah saçıma beyaz düşmeden, Gönül sarayımda özlem pişmeden, Gören gözümün feri geçmeden, Gel sevdigim,Ömür bitmeden. Sana koşan ayagım durm...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-sevdigim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Güvercin', 'bin-guvercin-nevin-konuk-jk5v9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bin güvercin salıversem göklere

Her birinin ağzında zeytin dalı

Bin güvercin ayrı yerlere uçup

Ayrı ayrı yüreklere konmalı

Bin tane yıldıza ip bağlasalar

Yukardan yeryüzüne sallasalar

İçlerine biraz sevgi koysalar

Sevginin yanında umut olmalı

Güvercinin kanadında bin gümüş

Dönüp gelir boyuncuğu bükülmüş

Umut ekmiş/ hüzün biçmiş

Yıkılmış

Bir yıldızı bin parçaya bölersem

Her birine bir bir hesap sorarsam

İnanmayın bir gün size söylersem

Kim? 

Nerede? 

Nasıl demiş

Sormalı

İnmeli dağlardan afşar elleri

Çözülmeli artık gönül dilleri

Bağlansa da kanatları,kolları

Saygı nedir,

Yürek nedir bilmeli

SEVGİ  nerde

Asıl onu bulmalı

    Sevgi  NERDE

Asıl onu bulmalı', 'Bin güvercin salıversem göklere Her birinin ağzında zeytin dalı Bin güvercin ayrı yerlere uçup Ayrı ayrı yüreklere konmalı Bin tane yıldıza ...', ARRAY['Türk Edebiyatı','Şiir','Nevin Konuk']::text[], 8.5, '{"poet":"Nevin Konuk","poet_slug":"nevin-konuk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bin-guvercin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sık Yum Gözlerini', 'sik-yum-gozlerini-salim-diyap-v9827', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ayıldın mı

bu gece yarısı sarhoşluğundan?

aranma boşuna, kaybettiğin benim!

mavisi uçmuş denizlerin tuzundayım şimdi.

dünya kaçkını yüreğim,

gözlerinin mavisine sığınmış; 

açsan gözlerini, döküleceğim.', 'ayıldın mı bu gece yarısı sarhoşluğundan? aranma boşuna, kaybettiğin benim! mavisi uçmuş denizlerin tuzundayım şimdi. dünya kaçkını yüreğim,...', ARRAY['Türk Edebiyatı','Şiir','Salim Diyap']::text[], 8.5, '{"poet":"Salim Diyap","poet_slug":"salim-diyap","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sik-yum-gozlerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanacak Sevda ya', 'yasanacak-sevda-ya-hikmet-feridun-demir-lpdkq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen; 

Sevdanın acan Rengi

Beyaz Gülün sırlı özünün Dengi

Kalblerde ki aşkın kızıl Rengi

Morlar diyarın da özlemlerin Dengi

Ben; 

Kızıl ve Morun, Yaşamın Özlemi

Kırdaki çiçeğin tabii Rengi

Doru seklavi kır atın özgür Ruhu

Göklerde kanat tutan Kartalın Dengi

Sevdaya hasret iki yüreğin Sılası

Sana ulaşabilmem ruhumun sevdası

Sırlarla dolu gizemli bir Rüya ya..

Acabileceksen yüreğini, 

Attım yüreğimi yaşanacak Sevdaya...

30.01.2005 

Wermelskirchen/Almanya', 'Sen;  Sevdanın acan Rengi Beyaz Gülün sırlı özünün Dengi Kalblerde ki aşkın kızıl Rengi Morlar diyarın da özlemlerin Dengi Ben;  Kızıl ve Mo...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasanacak-sevda-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-esat-korkmaz-fdqjn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bir yıkılırken kaleler

Taşınırken ırmaklar karanlık delhizlere

Tükenirken umutlar

Umutsuzluğun karanlığında 

Yitip giderken hayaller

Düşüp giderken bir bir 

Yoluna baş koyanlar

Yalnız seni düşünüyorum 

Yaşamın anlamsızlığında dahi

Kör karanlıkların ardından

Aydınlık yarınlarda

Varlığına olan inancımdır

Yaşama direnci veren

Sellere kapılmış kütük misali

Savrulurken çaresizlik girdabında

Yarına tutunma istencim

     Bilirim.geleceksin

                              Ey  Özgürlük', 'Bir bir yıkılırken kaleler Taşınırken ırmaklar karanlık delhizlere Tükenirken umutlar Umutsuzluğun karanlığında  Yitip giderken hayaller Düş...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozgurluk-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yapayım.', 'ne-yapayim-i-shak-ozlu-h23uk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüregime yazdım okumadın,

Türkü yaptım duymadın,

Bulutlara çizdim görmedin,

Söyle sevgili ne yapayım.

Güneşten buz yagdırayım.

Yıldızlara cemalin çizdireyim.

Rüzgara ismin söyleteyim.

Söyle daha ne yapayım.

Hindi Yemeni tarayım.

Kaf dağındaysa varayım

Yeterki sevgini bulayım.

Söyle sevgili ne yapayım.', 'Yüregime yazdım okumadın, Türkü yaptım duymadın, Bulutlara çizdim görmedin, Söyle sevgili ne yapayım. Güneşten buz yagdırayım. Yıldızlara ce...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-yapayim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgu', 'sorgu-esat-korkmaz-qkh8n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şoklar saldırırken belleğime

Çığlıklarla uzaklaştırdım

Zihnimdekileri bedenimden

İnsana reva değil olanlar

İnsan mıyım başka mahluk mu

Sorguladım kendimi/olanlardan 

Peki insan mı onlar

 insana işkenceden zevk   alanlar

Unuttum ne olduğumu /ben zaten

Artık adımı biliyordum yalnızca 

                        sorduklarında

Ne parmaklar dokunduğunu

Ne gözler gördüğünü

Ne de kulaklar seçebiliyor

                     duyduğunu

Yalnızca gelen kokudan

Farkındaydım çürüdüğümün

Hayvanlar aleminin

           Canlı mezarlığında 

Ölümün parçalıcası

            Sergileniyordu/ bedenimde', 'Şoklar saldırırken belleğime Çığlıklarla uzaklaştırdım Zihnimdekileri bedenimden İnsana reva değil olanlar İnsan mıyım başka mahluk mu Sorgu...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sorgu-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım Ben', 'aglarim-ben-atil-kesmen-glv72', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çağlar, akar gözlerim			

Demine oturmuş aşkımın			

Tutuklu kalmış			

Acılarla, arkadaş olmuş			

Gönül yaram''dan			

			

Güneş''siz toprakmıyım			

Kök saçak salmış ağaçmıyım			

Geceler düşmüş gönlüme			

Yıldız oldum			

Kaydıkça, yolumu bulamıyorum			

			

Bu neyin nesi''dir			

Sevgimi''dir, acımı''dır			

Bilmeden geçilen yolmudur			

Gönlüm''de gönlüme			

Derman olacak ilacı bulamıyorum			

			

Görülmezliklere esir düştüm			

Toz dumanım			

Göz yaşlarım arasında, kaçışım			

Kalp atışlarımda, hesabım			

Bir sevgi''dir kendimden geçiyorum			

			

Gönül sesi''me			

Ağlasam çare bulamıyorum			

Sevdim, ama sevgimde üzülüyorum			

Şaşkına döndüm			

Dört''te dört,dört bir yana bölündüm			

Ağlarım ben			

Kalbe, kalp koyduğum yerde', 'Çağlar, akar gözlerim			 Demine oturmuş aşkımın			 Tutuklu kalmış			 Acılarla, arkadaş olmuş			 Gönül yaram''dan			 			 Güneş''siz toprakmıyım...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aglarim-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Türkümüz', 'sevda-turkumuz-meral-vurgun-4u1ck', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''bilmezler nasıl sevdik, 

nasıl aradık birbirimizi''

sol yanım yaralı ceylan

sağ yanımda kahpe pususu ölümün

gözlerimin perdesine düşmüş sevdan

kah yoldaş olup Köroğlu''na

dağlara vurduk yüreği dolu dizgin

kah korsan bir kaptan olup 

attık hırçın dalgasına okyanusların

biz coştuk...

erguvan kokularına karışıp

ipek polenlerle serpildik doruklara

hercai menekşelere inat

gece karası perçemi yarin

sümbül sümbül düşerdi alnına

gün oldu çağladık aktık nehirlerce

gün oldu mavzer çattık Karayılan misali

biz vurulduk...

türküler söyledik

kor ateşlerde toptan yandık /yakıldık

biz sevdik hesapsız-kitapsız

ak sayfalara yazıldı sevdamız

tarihlere kazındı tırnakla

damarları çatladı duvarların

biz dayandık...

sürgünlere biz sürüldük

gurbetlere biz düşürüldük

kanarken sol göğsümüzde cevahir 

oluk oluk 

asi gelincik kızıllığında

biz yine güldük

çalındı umutlarımız 

sökülüp alındı yılları gençliğimizin

biz büyüdük...

rüzgar gibi esti çelik bakışlarımız

fırtına olup karanlıklarından tarihin

gelip geçtik apaydın

yağmur bulutu olduk

bereketli topraklara

ılık ılık aktı kanımız

biz yağdık...', '''bilmezler nasıl sevdik,  nasıl aradık birbirimizi'' sol yanım yaralı ceylan sağ yanımda kahpe pususu ölümün gözlerimin perdesine düşmüş sevd...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sevda-turkumuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Hep Seveceksin', 'sen-beni-hep-seveceksin-nesrin-gocmen-qunbk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirim sen beni hep seveceksin,

Benden hergün haber bekleyeceksin,

Ömürlük sevdamda biricik, teksin,

Bilirim sen beni özleyeceksin...

* 

Bahtıma ne kadar darılmış olsam,

Vurulmuş, yorulmuş, kırılmış olsam,

Bitmez hüzünlere sarılmış olsam,

Bilirim sen beni isteyeceksin....

.*

Ağlayan şu yazgım gülümser sana,

Gönlüm mabedinde ''ilah'' der sana,

Bıkıp usanmadan sevgi ver bana,

Bilirim umudu yeşerteceksin...

*

Ruhum dert gölünde derine dalsa,

Yalanı olmaz ya, yanlışı olsa,

Deneye, yanıla eğride kalsa,

Bilirim sen beni hep seveceksin....

*

30/01/2005', 'Bilirim sen beni hep seveceksin, Benden hergün haber bekleyeceksin, Ömürlük sevdamda biricik, teksin, Bilirim sen beni özleyeceksin... *  Ba...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-beni-hep-seveceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadık Dost', 'sadik-dost-ali-seyh-ozdemir-oygur', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Şefkatnisar gönlüne sığındım senin...  -

Bak yine sana sarıldım,

Kucak açan sen olursun.

Küstüm hayata darıldım,

Barıştıran sen olursun…

Acıkınca yemekle aş,

Yalnız isem bir tek yoldaş,

Başımı vurduğum her taş,

Sen olursun, sen olursun …

Yolda kalsam barınağım,

Aksar isem dayanağım,

Sıkışınca sığınağım,

Sen olursun, sen olursun …

Ağlar iken gözümde yaş,

Benim ile sarmaş-dolaş

Her şeyimi bilen sırdaş,

Sen olursun, sen olursun …

Çağırmadan bana gelen,

Dertlerimi hemen bilen,

Gönlümün yasını silen

Sen olursun, sen olursun …', '- Şefkatnisar gönlüne sığındım senin...  - Bak yine sana sarıldım, Kucak açan sen olursun. Küstüm hayata darıldım, Barıştıran sen olursun… A...', ARRAY['Türk Edebiyatı','Şiir','Ali Şeyh Özdemir']::text[], 8.5, '{"poet":"Ali Şeyh Özdemir","poet_slug":"ali-seyh-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sadik-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıkıntılıyım', 'sikintiliyim-dursun-onal-75xcn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yersiz bir sıkıntı kapladı yüreğimi

Oysa çok mutluyum, bir o kadarda huzurluyum

En sevdiğime de yakınım, bir o kadar

Anlayamadım, neden sıkıntılıyım bu kadar

Bir karamsarlık ki çöktü bedenime

Takatım kalmadı, dokunsalar yıkılacağım yere

Çok üzüldüğümde hissederdim bu bitaplığı 

Büyük fırtına öncesi sessizliğimi ne

Sen yanımdayken zaman su gibi akıp gidiyordu

Şimdi, sanki önüne set çekildi de, zaman durdu

Yoksa yaşananlar kavuşmanın öncüsümü

Bilmiyorum, yoksa bu özlemin sancısımı

Benim istediğim değilki seni sıkmak

Umudum hep sonsuza dek dost kalmak

Yapılan hatalar yıkmasın seni

Çünkü hataların hepsi geçici

Biliyorum birgün bu fırtına duracak

Bizim dostluğumuz ebediyen olacak

Bu yaşanılanların hepsi anı kalacak

Belli ki kalbim yine senin için atacak', 'Yersiz bir sıkıntı kapladı yüreğimi Oysa çok mutluyum, bir o kadarda huzurluyum En sevdiğime de yakınım, bir o kadar Anlayamadım, neden sıkı...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sikintiliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyhat!', 'heyhat-kadir-yildiz-n18hq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kızıl bir kazağın 

son ilmeğini sökerken şafak

     göğden yere vurup yansıyan umutlar

topraklarımda bekleyen buz kurbalarının 

kanlarını alevlendirirken

dağlarımdaki eşkiyaların yaktıgı 

sevda ateşinin kıvılcımları 

sıçrayıp canımı yakarken

düşlerimde kaçırıp beynimin mapushanesinde

ugruna yattığım

gün saydığım duvarlara attığım çiziklerle 

ismini yazdığım 

kürek mahkumu olduğum korsan gemin

teknelerimi bir bir batırırken 

sen

göl manzaralı gönül köşkümde

yakamozları izlerken

heyhat! ay ne kadar rahat', 'kızıl bir kazağın  son ilmeğini sökerken şafak      göğden yere vurup yansıyan umutlar topraklarımda bekleyen buz kurbalarının  kanlarını al...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yıldız']::text[], 8.5, '{"poet":"Kadir Yıldız","poet_slug":"kadir-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/heyhat-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoyrat', 'hoyrat-dursun-onal-4crpa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neden bu kadar hoyratsın bilmiyorum ki? 

Seni bu kadar çabuk değiştiren ney ki? 

Bazen sıcaksın bana bir ateş gibi

Bazen buzulları bile aratmıyorsun ki

Bir zamanlar sevdiğine inandığım sen

Neden şimdilerde uzaksın benden

Ben her zaman yaklaşmaya çalıştım oysa

İsteğim, derdine, sevincine ortak olmaktı güya

Yine beni sevdiğine inanıyorum

Sorun bende değil, ben bunu biliyorum

Neyse bunların hepsi gelip geçecek

Yaşananlar gizli bir macera kalacak

Ne yere, ne göğe sığdırabiliyorum seni

Saf ve temiz kalplerin budur tecellisi

Bir günün bir gününe uymuyor ki

Benim senden çektiğim nedir bilmem ki', 'Neden bu kadar hoyratsın bilmiyorum ki?  Seni bu kadar çabuk değiştiren ney ki?  Bazen sıcaksın bana bir ateş gibi Bazen buzulları bile arat...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hoyrat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak istiyorum', 'aglamak-istiyorum-dursun-onal-dagw0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünmeden aldğım havayı, saymıyorum nefesten

Sen yokken akıttığım damlaları, saymıyorum göz yaşından

Saymıyorum tebessümden, atılan kahkahaları

Nefes bile almıyorum sen yanımda yokken

Bu gün ağlamak istiyorum üzüntü adına, asla

Çok zaman geçsede kavuştum umuduma

Haykırmak istiyorum gözyaşlarımla, mutluluğumu dünyaya

Sevmek varmış, sevilmek varmış, temiz duygular adına

Biz gösterdik bunu, gerçek sevgilerin varlığının ispatına

Günü birlik yaşanıp biten aşklar için değil

Ebediyen var olan mukaddes aşklara

Huzur ve mutluluğu sevmekte bulanlara

Bugün ağlamak istiyorum bütün bu duygular adına', 'Seni düşünmeden aldğım havayı, saymıyorum nefesten Sen yokken akıttığım damlaları, saymıyorum göz yaşından Saymıyorum tebessümden, atılan ka...', ARRAY['Türk Edebiyatı','Şiir','Dursun Onal']::text[], 8.5, '{"poet":"Dursun Onal","poet_slug":"dursun-onal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglamak-istiyorum-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceaydın', 'geceaydin-fevzi-gunenc-eagfm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alışmışız hep gün aydın demeye

günler aydınlıktır zaten yeterince

aslında asıl önemlisi

gecenin aydın olması

Ben bozuyorum bu kuralı

gecen aydınlık olsun sevgilim

gecen aydın

geceaydın!', 'Alışmışız hep gün aydın demeye günler aydınlıktır zaten yeterince aslında asıl önemlisi gecenin aydın olması Ben bozuyorum bu kuralı gecen a...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geceaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daglar', 'daglar-i-shak-ozlu-vpo9z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başı dumanlı yüce daglar,

Yamacında bir gelin aglar,

Yaşı ondokuz karalar baglar,

Derdin dermanı yokmu daglar.

Zirvende huma kuşu öter.

Bölük bölük dumanın tüter.

Sende bir yigit yatar.

Derdin dermanı yokmu daglar.

Erimiş karların çaglar akar,

Ayrılık düştügü yeri yakar.

Gelinim yitirmiş yigidin bakar,

Ver yigidi,derman daglar.', 'Başı dumanlı yüce daglar, Yamacında bir gelin aglar, Yaşı ondokuz karalar baglar, Derdin dermanı yokmu daglar. Zirvende huma kuşu öter. Bölü...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/daglar-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son durak', 'son-durak-burhan-kucuk-ks03z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son durak

Tespihin tanelerinde saklı

Hayatın ince sızıları

Ne çok sevmeli

Ne de çok bağlanmalı

O, deli mavi göklere

O,uçsuz denizlere

Ömür dediğin angarya

Gelip geçiyor nasılsa

Bir iki adımda

Bulandığında gözlerin

Yeltenir dinlenmeye

Ki son durak olur

Sevgilinin gözbebekleri

Burhan KÜÇÜK

Kdz.Ereğli-31.01.2005', 'Son durak Tespihin tanelerinde saklı Hayatın ince sızıları Ne çok sevmeli Ne de çok bağlanmalı O, deli mavi göklere O,uçsuz denizlere Ömür d...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-durak-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apansız Çıkagel', 'apansiz-cikagel-zekeriyya-bican-c8jxs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'APANSIZ ÇIKAGEL

Çiçekler dünyasındayım...

Güller, menekşeler, daha neler neler...

Hanımelileri kokuyor güzel bahçeler,

Ve ben şiirle meşgulüm, cümleler örmedeyim,

Senin için kelimeler,

Dizeler koşuşurken dimağımda, 

Bir şiir oluşmada ki, dökülecek az sonra,

Henüz öpmediğin dudaklarımdan...

Bir ‘sen’ eksiğiyle, çiçekler dünyasındayım,

Ve şiir bitecek, tam havasındayım,

Şiirin bittiği yerde;  apansız çıkagel...', 'APANSIZ ÇIKAGEL Çiçekler dünyasındayım... Güller, menekşeler, daha neler neler... Hanımelileri kokuyor güzel bahçeler, Ve ben şiirle meşgulü...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/apansiz-cikagel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Yolu', 'hayat-yolu-zekeriyya-bican-852is', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HAYAT YOLU

Yıllar sonra uğradım, o gençlik bahçesine,

Gençliğimi aradım, yitirdiğim o yerlerde.

Bir aşina yüz yoktu, bakındığım tüm yüzlerde,

Avutucu bir söz yoktu, konuştuğum kimselerde...

Bir tanıdık ağaç vardı, o günlerden kala kalan,

Onun da bağrı yanıktı taşıdığı yazılardan,

İnce ince oyulmuştu, yüzü göğsü kazılardan,

Bir ben ona, bir o bana, bakışıp da acımıştık...

	

Ne de çabuk vakit geçmiş, nasıl geldik buralara,

İlkbaharı, yazı geçmiş, ulaşmıştık sonbahara.

Pınarlarda su kurumuş, bizim gözler yaşlı, sulu,

Acı tatlı anılarla, sürüp gider hayat yolu...', 'HAYAT YOLU Yıllar sonra uğradım, o gençlik bahçesine, Gençliğimi aradım, yitirdiğim o yerlerde. Bir aşina yüz yoktu, bakındığım tüm yüzlerde...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-yolu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olacak Şey mi', 'olacak-sey-mi-zekeriyya-bican-v5cs9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'OLACAK ŞEY Mİ

Dün duydum, biri sana, seni unuttuğumu söylemiş,

Hele bak şimdi, inan ki vebalime girmişler! 

Kendi adımı unutabilirim,

Evimin kapı numarasını sorsalar, söyleyemem belki,

Pazardan ne alacaktım diye, düşünebilirim...

Telefon numaramı sordular, deftere bakayım dedim.

O anda, ben de çok gülmüşüm kendi kendime,

Biri bir şey sorsa, alık alık bakabilirim yüzlerine...

Bana bir adres sorsalar, tarif edemem belki,

Ben böyle bir haldeyken, hele bak şimdi...

Dün duydum, biri sana, seni unuttuğumu söylemiş,

Olacak şey mi? 

Seni unutmak, düşlerimden seni çıkartmak...

Oysa sen, gündüzümde fikrimdesin, gece düşümde,

Her şeyi unutuyorum, leylâm sen fikrime düşünce...

Dostlarım çok unutkan olduğumu yüzüme söylüyorlar,

Kimileri bu aralar beni vefasızlıkla suçluyorlar...

Bilmiyorlar ki, kim aldı benden beni? 

Sana geleceğim yolum engelli, yolum dikenli...

Özledim, hem de çok özledim meleğim seni,

Ben böyle bir halde iken, hele bak şimdi...

Dün duydum, biri sana, seni unuttuğumu söylemiş,

Hele bak şimdi, olacak şey mi?', 'OLACAK ŞEY Mİ Dün duydum, biri sana, seni unuttuğumu söylemiş, Hele bak şimdi, inan ki vebalime girmişler!  Kendi adımı unutabilirim, Evimin...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olacak-sey-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlatan Şiirler', 'seni-anlatan-siirler-zekeriyya-bican-y3b10', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SENİ ANLATAN ŞİİRLER

Seni anlatan şiirleri, bir bestede bulacaksın,

Sevenlerin dudağında, birer şarkı olacaksın.

Bir kemanın tellerinde, bir udinin dillerinde,

Bir tamburun yüreğinde, inleyip de duracaksın.

Bir denizde, gemilerde, nice nice sahillerde,

Bu öykümüz dilden dile, benim gibi savrulacak.

Her cümlesi, kelimesi, seni anlatan tüm hecesi,

Susuz tuzlu dudaklarda, bir köz gibi kavrulacak.

Ben aşkınla kavrulurken, kaçıyorsun bucak bucak,

Sen esirgerken bir buseyi, ben sunmuştum kucak kucak.

Senin kalbin almasa da, sevdam ile dolmasa da,

Seni anlatan şiirler, tüm kalplerde yer bulacak...', 'SENİ ANLATAN ŞİİRLER Seni anlatan şiirleri, bir bestede bulacaksın, Sevenlerin dudağında, birer şarkı olacaksın. Bir kemanın tellerinde, bir...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-anlatan-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemiyorum', 'soyleyemiyorum-zekeriyya-bican-5ctq2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SÖYLEYEMİYORUM

Söyleyemiyorum,

Seni ne çok sevdiğimi.

Kaç kez niyetlensem de söylemeye,

Bir türlü dilim dönmüyor,

Söyleyemiyorum...

Bak gör ki,

Her gördüğümde seni,

Esiyor başımda kavak yelleri,

Kalbim oluyor bir çılgın, sanki bir deli...

Bir söyleyebilsem, bir büyü bozulacak sanırım.

Ya çalımlı bir eda ile, bir kahkaha duyarsam,

Yer yarılacak, veya kalbim duracak...

Korkuyorum, söyleyemiyorum...

Ama boş ver, bu büyü bozulmasın,

Hatırası dahi yeter bana.

Sen de bilmesen olur, lâkin,

İçimden geçenleri bir bilsen,

Bir kâhin gibi, ne olur...

Lisanım mı yetersiz, kelimeler mi yoksa,

Anlıyorum, biliyorum oysa,

Lisanımda yeterli, kelimeler de belki,

İnanmayacaksın, anlamayacaksın diye çok korkuyorum...

Çekip gitme ne olur, sevecen bakışlarınla,

İçimde bir dağ  yıkılacak gibi geliyor.

Mor akşamlara kalmasın ümitlerim, söylemeliyim,

Bir başka bahara kalmasın vuslat...

Daha kaç bahar bekleyeceğim...', 'SÖYLEYEMİYORUM Söyleyemiyorum, Seni ne çok sevdiğimi. Kaç kez niyetlensem de söylemeye, Bir türlü dilim dönmüyor, Söyleyemiyorum... Bak gör ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/soyleyemiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zifir Gecelerde', 'zifir-gecelerde-zekeriyya-bican-4nona', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ZİFİR GECELERDE

Fanuslarda titrer gibiydi bütün kandiller, hayret...

Mumlar da eridi, bu bitmeyesi geceye ışık tutan,

Bir kör kandile bile hasrettim o gece, sen yoktun,

Bu zifir  gecede, yarasa dostlar da yoktu artık.

Seni arıyordum şarkı sözlerinde, inleyen tambur tellerinde,

Şu tamburu dinlerken, ah olaydı şimdi ellerin ellerimde,

El ele tutuşup biz, uçsaydık yarasalar gibi körü körüne.

Nedendir hiç bir şey avutmuyor, sensizlik hep yerli yerinde,

Sen nerelerdesin, tambur nerede, bak ki ben nerelerdeyim,

Bu zifir gecelerde...', 'ZİFİR GECELERDE Fanuslarda titrer gibiydi bütün kandiller, hayret... Mumlar da eridi, bu bitmeyesi geceye ışık tutan, Bir kör kandile bile h...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/zifir-gecelerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurup Olmuş Gözlerim', 'gurup-olmus-gozlerim-zekeriyya-bican-fk9am', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GURUP OLMUŞ GÖZLERİM

Hatırımdadır hep,

Sen gurup vakitlerini severdin.

Şimdi uzaklardasın,

Oralarda da seviyorsan eğer,

Her günün akşamını bekleme,

Her vakte gurup oldu gözlerim,

Gel, saatlerce gözlerimde gurubu gör.

Sen gideli gurup ifadesi her dem,

Oturmuş gözlerimde...

Bülbüller gurup vakitlerinde ağlarmış,

Çiçekleri solarmış, gülünü görmeyince.

Sen yoksun ya, gurup renginde gözlerim,

Gel gurubu her dem gör,

Her vakte gurup olmuş gözlerimde sefa sür...', 'GURUP OLMUŞ GÖZLERİM Hatırımdadır hep, Sen gurup vakitlerini severdin. Şimdi uzaklardasın, Oralarda da seviyorsan eğer, Her günün akşamını b...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gurup-olmus-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsafsız Zaman', 'i-nsafsiz-zaman-zekeriyya-bican-v790e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İNSAFSIZ ZAMAN

	

Zaman, insafsız fırçasıyla çizerken resmini,

Yüzümde kurdu tezgâhını, önce ilkbahara,

Sonra yaza çevirdi yüzümü...

Zamanın paletinde, renkler değişti nicedir,

Bir başka manzara oluşturdu başımda saçlar,

Yamaçlarına düşercesine ilk kar...

Meltemle yer değiştirdi rüzgârlar, mevsim sert,

Esiyor şimdilerde, kesercesine bir deli rüzgâr,

Bilemiyorum,

İçinde baharı olmayan, daha kaç yıl var? 

Bir başka tablo oluşturdu  zaman,

Bir başka güzellikte şimdi sonbahar...

Bu tabloda sadece ben değilim oluşan resim,

Birlikte oluşturduk bu son manzarayı, güzelim...', 'İNSAFSIZ ZAMAN 	 Zaman, insafsız fırçasıyla çizerken resmini, Yüzümde kurdu tezgâhını, önce ilkbahara, Sonra yaza çevirdi yüzümü... Zamanın ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/insafsiz-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seher Vakitlerinde', 'seher-vakitlerinde-zekeriyya-bican-2076a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEHER VAKİTLERİNDE

Her sabah seher vakitlerinde, tam yüreğimden,

Kurşuna diziliyor sanki bütün duygularım...

Kirpiklerin bir kargı olup, delip geçiyor tam on ikiden,

Gecelerin yalnızlığı başlıyor, ikindi vakitlerinden...

Gündüzler başka alem, eser yok gonca gülden,

Nefret ediyorum, duyguları yargılayan şu uzun gecelerden...

Çam kokusu, deniz kokusu, ve o yaz kokusu yok şimdi,

Soğumuş denizler gibi, gül gelmez bahçelerden...', 'SEHER VAKİTLERİNDE Her sabah seher vakitlerinde, tam yüreğimden, Kurşuna diziliyor sanki bütün duygularım... Kirpiklerin bir kargı olup, del...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seher-vakitlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah! Bir Tutabilsem Ellerini', 'ah-bir-tutabilsem-ellerini-huseyin-erdogan-je2w9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'neden beni 

perişan ediyorsun böyle? 

sevmekse sevdim seni

tutuldum sana

senden ne istedim ki

dostluktan sevgiden başka

lütfen söyle

beni sensizliğe

mahkum edip de

yaralar açma yüreğimde

belki bir gün

sen de anlayacaksın

seni ne denli çok sevdiğimi

belki de sen

bir kez olsa da

söylemeyeceksin bana

beni sevdiğini

keşke bir gün ben de

o güzel kalbinde açıversem

bir gonca gibi

seni kollarımla sarıversem

sarmaşık misali

ah! bir tutabilsem ellerini

inan ki yine doyamam sana

ömrüm boyunca

kollarımla sarsam da seni

her gece koklasam da

saçının  tellerini

             31.01.2005', 'neden beni  perişan ediyorsun böyle?  sevmekse sevdim seni tutuldum sana senden ne istedim ki dostluktan sevgiden başka lütfen söyle beni se...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ah-bir-tutabilsem-ellerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimiz', 'i-kimiz-oguzkan-bolukbasi-29koy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İkimiz

En çok anlattığım bir aşkın öyküsü

Her cümlesinde özlem

Her cümlesinde uzak kentlerin damlarına tünemiş baca dumanlarının kıvrım kıvrım türküsü

Kırmızı kiremitli evlerde çoluk çocuk heyecanlar

Camlarda kar buğusu

Yaz akşamlarında bir bardak soğuk su gibi

Unutulmamış mutlulukları anımsıyorum

İkimiz 

Bu değişmiş zamanda karşılaşmış olsaydık

Yani şimdi

Acele giden bir hayatın

Ecelinden önce bir otobüste

Veya okulda

Seni fark edecek zamanım olur muydu? 

Gözlerinde ne süre tutunurdum

Belki son durakta unuturdum

Aklımdan nehirler geçiyor

Su aynı yeri hiç bilmiyor

Anı yok

An yok

Zaman yok

Oysa aşkı tanıdığım yerdesin hala

Kaç durak gittiysek yanımdasın

Hızlı değişmeyen zamanların

Hızlı değişmeyen insanları olmaktır insan yanımız

Basit

Anlaşılır

Ve sıcacık

İkimiz

En çok anlattığım bir aşkın öyküsü olarak kalacağız', 'İkimiz En çok anlattığım bir aşkın öyküsü Her cümlesinde özlem Her cümlesinde uzak kentlerin damlarına tünemiş baca dumanlarının kıvrım kıvr...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ikimiz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı Olmak', 'yabanci-olmak-zekeriyya-bican-9igxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YABANCI OLMAK

Ne kadar zor bir yabancı olmak, aşina iken.

Bir gün bir yolda, bir şehirde beni görürsen,

Eğip de başını geçme, ne olur! 

Bir selâm ver, sor halimi istemesen de,

Veya hiçbir şey sormadan selâm ver, ne olur? 

İster miydim düşeyim vefasız, böyle bir aşka,

Vallahi günahım yok, seni sevmekten başka.

Sevmek suç mu, yazmıyor ki hiçbir kitapta,

Oysa, ‘sevmek sevaptır’ diyor, dört semavî kitapta,

Geçip de gitme yolumdan, selâm ver ne olur? 

Sevmek ve sevilmek, zorla olamıyor ki,

İnsan seveceğini, bir ömürde bile bulamıyor ki,

Bulmuşken sevdiğini unutmak mümkün olamıyor ki.

Gözlerin açtı, yüreğime büyük bir boşluk,

O boşluğa gülden başka ne koysam dolamıyor ki,

Ezip de gitme yolumdan, selâm ver ne olur?', 'YABANCI OLMAK Ne kadar zor bir yabancı olmak, aşina iken. Bir gün bir yolda, bir şehirde beni görürsen, Eğip de başını geçme, ne olur!  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yabanci-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merak', 'merak-ahmet-kurt-yt37e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesim duyulmuyorsa, 

Sanmayın uzaktayım. 

Bir karanlık köşede, 

Sinsi bir tuzaktayım. 

Gözlerim alışıyor, 

Siluet karışıyor, 

Hislerim karışıyor, 

Biraz da telaştayım. 

Vurgundan sonra gibi, 

Göründü suyun dibi, 

Karıştı ölü, diri, 

Merakta yarıştayım, 

Ne uzun menzil böyle, 

Varılmaz yürümeyle, 

Ayaklar sürümeyle, 

Arşında, karıştayım. 

Kurdoğlu selam söyler, 

Duysun, bayanlar, beyler, 

Gafiller gönül eyler, 

Özümle savaştayım.', 'Sesim duyulmuyorsa,  Sanmayın uzaktayım.  Bir karanlık köşede,  Sinsi bir tuzaktayım.  Gözlerim alışıyor,  Siluet karışıyor,  Hislerim karış...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/merak-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni sonbaharda sevdim', 'seni-sonbaharda-sevdim-tarik-teke-ssx7e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'seni sonbaharda sevdim

sararan yapraklar düşerken

sen yaz güneşim oldun

sonbaharın soguklugunu unutturdun.

seni sonbaharda sevdim

kuşlar terk ediyorken buraları

sen gönlüme yerleştin.

seni sonbaharda sevdim

çiçekler solarken

sen yeni filizlendin.

seni sonbaharda sevdim

aglayan gökyüzüyle birlikte

seni sonbaharda kaybettim

aglıyorum gökyüzüyle birlikte...', 'seni sonbaharda sevdim sararan yapraklar düşerken sen yaz güneşim oldun sonbaharın soguklugunu unutturdun. seni sonbaharda sevdim kuşlar ter...', ARRAY['Türk Edebiyatı','Şiir','Tarık Teke']::text[], 8.5, '{"poet":"Tarık Teke","poet_slug":"tarik-teke","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-sonbaharda-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağıma Saygım Sonsuzdur', 'bayragima-saygim-sonsuzdur-mehmet-karli-vn2rz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adına nice destanlar yazılmış canımsın bayrak

Ay yıldızın üzerine ne güzel de yakışmış bayrak

Ülkemin her yerinde uçar dalgalanırsın bayrak

Benzeri olmayan bayrağıma saygım sonsuzdur...

Genç kızlar seninle gelin olmak istiyor bayrak

Şehitlerin tabutlarına örtülür hep sarılır bayrak

Kale burçlarına dikilmiş dalgalanırsın bayrak

Şehitler kanıdır bayrağıma saygım sonsuzdur....

Düğün varsa biryerde yükseklere dikilir bayrak

Bayramlarda törenlerde kurtuluşta asılır bayrak

Hacdan dönenler evlerine asar sallanır bayrak

Manevi değerli bayrağıma saygım sonsuzdur...

Gönüllüyüm istekliyim bayraktarın olayım bayrak

Gücün bize güç katsın hız versin millete bayrak

Bayrağa hürmetsiz kimler varsa hepsi soysuzdur 

Atadan emanet bayrağıma saygım sonsuzdur...', 'Adına nice destanlar yazılmış canımsın bayrak Ay yıldızın üzerine ne güzel de yakışmış bayrak Ülkemin her yerinde uçar dalgalanırsın bayrak ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karlı']::text[], 8.5, '{"poet":"Mehmet Karlı","poet_slug":"mehmet-karli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bayragima-saygim-sonsuzdur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-kamil-boyraz-ds9du', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tez gelesin diye attım suyunu

Gitmeden özledim fidan boyunu

El alem ne bilir senin huyunu

Gittiğin ellerde kalma sevgilim

sılada bekleyenin var be sevgilim.

Resmini çekip duvara astım

Sazımı sözümü yalnız bıraktım.

Ayırıyor diye kadere kızdım.

Gittiğin ellerde kalma sevgilim.

Sılada bekleyenin var be sevgilim.', 'Tez gelesin diye attım suyunu Gitmeden özledim fidan boyunu El alem ne bilir senin huyunu Gittiğin ellerde kalma sevgilim sılada bekleyenin ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgilim-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Davacıyım', 'davaciyim-sahin-erturk-b59bw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son günlerde sabrım taştı

Gördüklerim hep yanlıştı

Kentlisinden,köylüsünden

Davacıyım,davacıyım

Aşka fesat bulaştıran

On''la,bun''la kırıştıran

Kadının''dan,erkeğin''den

Davacıyım,davacıyım

Devlet malı deniz deyip

Dalanlardan,çalanlardan

Arsızlardan,yüzsüzlerden

Davacıyım,davacıyım

Vefa nedir bilmeyenden

Dosta sırtın dönenlerden

Aşka mezar kazanlardan

Davacıyım,davacıyım

Soyguncuyu,bozguncuyu

Nota bilmez sanatcıyı

Şöhret yapan medya''danda

Davacıyım,davacıyım', 'Son günlerde sabrım taştı Gördüklerim hep yanlıştı Kentlisinden,köylüsünden Davacıyım,davacıyım Aşka fesat bulaştıran On''la,bun''la kırıştıra...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/davaciyim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerkük''ten Mektup Var', 'kerkuk-ten-mektup-var-ahmet-kurt-dpsqg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“Ucu telli” değil rengi de siyah, 

Bir zarfın içinde mektubun dostum. 

Yüreğimde sızı içimde bin ah! , 

Yakıyor elimi mektubun dostum. 

Öncesi güzeldi, vaadler hoştu, 

Demokrasi barış ve herkes koştu, 

İnsanlar toplandı, coştukça coştu, 

Coşkuyla başladı mektubun dostum. 

Dostluğumuz çağdan öte dayanır, 

Bedenler silinir ruhlar uyanır, 

Tabiat her türlü renge boyanır, 

Gönülden mühürlü mektubun dostum. 

Sayfası buruşmuş, koynumda kalan, 

Tarife yetmez ki, içinde olan, 

Damlayıp damlayıp ruhlara dolan, 

Çileyle dürüldü mektubun dostum. 

Solan yerlerine bakıp üzülme, 

Muhtemel göz yaşım düştü üstüne, 

Kartal kanadından derim üstüne, 

Kırmızı işlendi mektubun dostum. 

İbret olsun diye yazdım sana da, 

Bu bir başlangıçtır, sürer dünyada, 

Görsen inanamazsın, sanki rüyada, 

Yaşarken yazıldı mektubun dostum. 

Önce tırnaklayıp, sonra oydular, 

Oyuklara tuzlu sular koydular, 

Derilerim neşter ile soydular, 

Kan ile yazıldı mektubun dostum. 

Anlatamam ardır, yapılan zulüm, 

Bin kere iyiydi inan ki ölüm, 

Ellerim, ayağım bağlı gördüğüm, 

Son diye yazıldı mektubun dostum. 

Kızımın saçları mektup süslüyor, 

Eşimin eşarbı evlat örtüyor, 

Babamın takkesi postal siliyor, 

Kan ile yazıldı mektubun dostum. 

Kerkük’ten selam var kanlar içinde, 

Hilal hapsedildi, cami içinde, 

Çizgiler silindi, zangoç haçında, 

Kan ile yazıldı mektubun dostum.', '“Ucu telli” değil rengi de siyah,  Bir zarfın içinde mektubun dostum.  Yüreğimde sızı içimde bin ah! ,  Yakıyor elimi mektubun dostum.  Önce...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kerkuk-ten-mektup-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esir Düştüm Gözlerinde', 'esir-dustum-gozlerinde-esra-aksu-v6s5s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gülün yaprağında

Renginde, rayihasında

Titriyorsun Ey sevgili

O haletle esir 

                 düştüm   

                             gözlerinde!', 'Bir gülün yaprağında Renginde, rayihasında Titriyorsun Ey sevgili O haletle esir                   düştüm                                 gö...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esir-dustum-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Sokağında Kırçiçeği', 'dusler-sokaginda-kircicegi-tamer-kayikci-q7gf2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşler sokağında yürüyorum bu akşam

Tepemde ay parıltısı.

Yıldızlar göz kırpıyor birbiriyle yarışırcasına

Etrafım insanlarla dolu.

Ama ben onlardan uzaktayım.

Onlar kaldırımlarda,

Ben, düşler sokağındayım.

Düşler sokağı sessiz.

Sevenlerimle dolduruyorum sokağı.

Kimi istersen koy filmine. 

Nasıl olsa yönetmen benim.

Düş dediğin gerçeğin bir parçası,

İnsanın kamçılayıcısı.

Dünya düşlerle kuruldu…

İnsanoğlu,

Yarattığı dünyayı

Gerçeklerde kasıp kavurdu.

Bir insan düşlüyorum bu akşam

Belki de bir sevgili 

Yüreğinde bir çiçek sadeliği.

Bir çiçek ki; 

Sabah beyaz, öğle sarı, akşam kırmızı.

İçindeki tüm özü kelebeklerle doğaya sunup…

Kendisi yediveren gülü gibi.

Çiçeklerini topla topla koy kucağına.

Bu insanı tanıyorum

Benim için bir tane.

Dünya da belki binlerce.

Ama o benim bir çiçeğim

O benim solmaz kır çiçeğim

Yazın papatyam, kışın kardelenim', 'Düşler sokağında yürüyorum bu akşam Tepemde ay parıltısı. Yıldızlar göz kırpıyor birbiriyle yarışırcasına Etrafım insanlarla dolu. Ama ben o...', ARRAY['Türk Edebiyatı','Şiir','Tamer Kayıkçı']::text[], 8.5, '{"poet":"Tamer Kayıkçı","poet_slug":"tamer-kayikci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dusler-sokaginda-kircicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alvarlı Aşık Reyhani (Devam-32)', 'alvarli-asik-reyhani-devam-32-i-smet-barlioglu-alfek', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '32*

Tan etmek ne lazım eli- alemi? 

İyi insan hergün eşref sayılır.

Elinden geldikçe dinle kelamı; 

Tahsil gören ehl-i meşreb sayılır.

Lazımdır vatana mukaddes gayret,

Uyanık durmayı etmeli adet,

Büyüğe itaat, küçüğe şefkat

İnsana en büyük edeb sayılır.

Nerde olsa; edeb, haya başgelir,

Edepsiz ‘Can’ dese; gözden yaş gelir,

Edepliyse; ‘Çor’ da dese; hoş gelir,

Cahil sözü zehir-akrep sayılır.

İyi bak yoluna; olmasın yanlış,

Yanlış olan yollar çok uzarlarmış,

Eşiğe basmadan delile danış; 

Nasihat insana mektep sayılır.

Reyhani söz söyler yerine göre,

Alet yerindeyse; işler bin kere,

İnsandır; yanlışlık yapar birine,

Ama tekrarlayan merkep sayılır.

-------------------------------

32* Başkalarını suçlamaya-ezmeye-üzmeye ne hakkın var? İyi insan ol ki; her zaman soylu sayılasın. Biri konuşurken, elinden geldikçe dinle onu. Eğitim gören kişi iyi huylulardan varsayılır. Yurduna, senin göstereceğin kutsal çabalar gereklidir, çünkü; uyanık durmayı alışkanlık haline getirmek yurt için zorunluluktur. En güzel ahlak büyüklerin buyruklarına uymak ve küçüklerine sevgi göstermektir. Ahlakın ve utancın yeri her zaman başköşedir. Ahlaksız kişinin ‘Can’ demesi bile insana ağır gelir, insanı üzer ve ağlatır. Ahlaklı insanın ‘Zıkkım’ demesi dahi kişinin hoşuna gidebilir. Söz bilmeyenin sözüyle akrebin zehiri arasında hiç fark yoktur. Gittiğin yolu doğru yol olup olmadığına iyi bak. Kısa olan doğru yoldur, yanlış yol uzanır gider. Bir işe başlamadan onu iyi bilen birine danış, zira; öğüt kişi için okul gibidir. Reyhani sözünü yerine göre söyler. Kullandığı araç işinin aracıysa; aksatmadan işler durur. İnsandır bu; elbette ki; yanlışlık yapabilir ama eğer bunu yinelerse eşekten ne farkı kalır? 

Aşık bu şiirinde, kendisini dinleyenlere ve okuyanlara öğütler vermektedir ve öğütleri ahlak üstünedir. Hal Edebiyatı ‘ndaki bu şiir türü, halkın ötedenberi hoşuna gitmekte ve o bunlardan kendine dersler çıkarmakta, paylar almaktadır. Zira; Halk Aşığı Hak Aşığı ‘dır ve onun bilgisi doğuştandır, Hak ‘tandır. O, halkı eğitmek ve uyarmak için gönderilen öğretmenlerdendir. Dediklerinde yanlışlık bulmaya çalışmak doğru değildir. Öğütleri dinlenmeli, tutulmalı, yerine getirilmelidir. Halk Aşıkları ‘nın tümü zaman zaman öğütler vermişler ve bunu sazla yaptıkları için olumlu sonuçlar da almışlardır. Halk Aşıkları ‘nın babası sayılan  Sümmani Baba ‘nın bir öğüdünün bir dörtlüğü şöyledir: ‘Sümmani söz söyler iktidarınca, Süleyman ‘a söz öğretti karınca, Nasihat dinlemek noksanlık mıdır? ’ Yani ‘Sümmani ancak elinden gelebildiği kadar söz söyler ama yerden göğe kadar üst üste koyulabilecek her el, bir başka elden daha üstündür. Hz. Süleyman bir Kral ve bir Peygamber olduğu halde bile, yerinde bir karıncadan akıl danışmış, öğüt almıştır. Öğüde kulak vermek insan için noksanlık mıdır? 

Şiirin yabancı sözcükleri şöyle açıklanabilir: ‘Tan etmek-Başkasını suçlamak, kuşku altında bırakmak, ezmek, üzmek’, ‘Lazım-Gerek’, ‘El-Alem-Herkes, eller’, ‘Eşref-Soylu’, ‘Kelam-Söz’, ‘Tahsil-Eğitim, öğrenim’, ‘Ehl-i Meşreb-İyi huy, iyi eğilim’, ‘Vatan-Yurt’, ‘Mukaddes-Kutsal’, ‘Gayret-Çaba’, ‘Adet-Alışılagelen davranış’, ‘İtaat-Uyma’, ‘Şefkat-Küçüğe, yaşlıya, güçsüze, yoksula gösterilen sevgi’, ‘Edep-Ahlak, Utanç, Ar’, ‘Çor-Zıkkım,Zakkum’, ‘Cahil-Bilgisiz, Görgüsüz, Göreneksiz’, ‘Delil-Bilen, Rehber-Yolgösteren, Akılveren’, ‘Nasihat-Öğüt’, ‘Mektep-Okul’, ‘Alet-Araç’, ‘Merkep-Eşek’.

Şiir hece ölçülüdür. 6+5 Duraklı bir 11 ‘liktir. Durak atlaması yoktur ve duraklar yerli yerindedir. Örgüsü (a-b-a-b) , (c-c-c-b) , d-d-d-b) , (e-e-e-b)  ve (f-f-f-b)  dir.

(ALVARLI AŞIK REYHANİ isimli Araştırma-İnceleme ''lerinden > 136-139/201) 

(Devam edecek...)', '32* Tan etmek ne lazım eli- alemi?  İyi insan hergün eşref sayılır. Elinden geldikçe dinle kelamı;  Tahsil gören ehl-i meşreb sayılır. Lazım...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/alvarli-asik-reyhani-devam-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bingül''lerden Size', 'bingul-lerden-size-i-brahim-ethem-bingul-k4pgf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağda çırpınan balığınki kadardı

Ümidimin ufku

Ve umutsuzluğun karanlığındaydı

Bekleyişim

Göz yaşlarımın tuzunda eridim...

Saatlerin

Geçmeyen saniyelerinde kayboldum

Vurmuştum okyanusların siyah diplerine

Sabırla çare bekledim...

Şimdi gökyüzünün turkuazındayım

Binlerce teşekkürlerle

Sebeb-i hayatım sıhhatte

Gül yüzlü anam neşede

Sevdiklerimle sevindim...

Yaradana

Bizler için uzanan her ele ve gönüle

Binlerce teşekkürler 

Bingül''lerden size

Hepinize...

www.iebingül.com', 'Ağda çırpınan balığınki kadardı Ümidimin ufku Ve umutsuzluğun karanlığındaydı Bekleyişim Göz yaşlarımın tuzunda eridim... Saatlerin Geçmeyen...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bingul-lerden-size-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '# Kalabalığın Yalnızlığı #', 'kalabaligin-yalnizligi-gulsen-senderin-5xpkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşam karmaşası içinde birçok apartman 

Kent kalabalığında kimseyi  tanımadan

Çoğu kez kuytuların yalnızlığında insan

İş yerinde tek düzen, üne takar kancayı...

Karmaşa bir düzende uzaktır sevgilerden

Uzaktır yuvasından, en   yakını bebeden

Hasrettir kimi zaman kökü ebeveyninden

Hafta sonu kör zaman, kın''a takar kancayı...

Kahvaltı gülümsemez, ağlar öğle sofrası

Gece eve geç döner, iş yeri bahanesi

Ayrılır bölüşümler, başlar sorun borsası

Uykuya sığınırken, an''a takar kancayı...

Bu ne karmaşa bu ne yaşamdaki yansızlık

Kalabalıklara sığmayan büyük  yalnızlık

Aileden toplumdan bihaber bilinçsizlik

İşlerle  övün dövün, sana takar kancayı...

İletişim çağında iletimsiz kalmışız

Eşler bir yerde çocuklar bir yerde gülmüşüz

Bir çapraşık düzenin kul kölesi olmuşuz

Kimlik ayrıklarından, eve takar kancayı...

Yok mu bunun çaresi, boşluklar vurur bizi

Yalnızlığın sesidir, örseler hepimizi

Çağı yetişmek için kim çaldı neşemizi

Puslu bir camekândan, güne takar kancayı...

~~~

Yalnız geçiyor günler, hırçın ayaz geceler

Bin bir telaş içinde bitmez yaşam gailesi

Bir yorgana sarılı gül maduru günceler

Kalabalık içinde  yalnızlığın çilesi

Yorgun ezgin canandan, cana takar kancayı..', 'Yaşam karmaşası içinde birçok apartman  Kent kalabalığında kimseyi  tanımadan Çoğu kez kuytuların yalnızlığında insan İş yerinde tek düzen, ...', ARRAY['Türk Edebiyatı','Şiir','Gülşen Şenderin']::text[], 8.5, '{"poet":"Gülşen Şenderin","poet_slug":"gulsen-senderin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kalabaligin-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehzade Gözyaşı', 'sehzade-gozyasi-esra-aksu-sb9c5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Verip elime koskoca baltayı,

Devir dedin asırlık çınarımı

Nasıl bozarım daldaki yuvayı,

Nasıl yaşarım sonra sormuyorsun,

.

Kurursa elinde kırçiçekleri

Aynalara sor o vahim nedeni

Şehzade gözyaşı, korkutur beni

Nasıl yaşarım  sonra sormuyorsun,

Olan biten bu:yüreğim biçare

Sıcak ama ben uzağım güneşe

Elveda dedim belki hata ile

Ne yaparım ben sensiz sormuyorsun.

Şimdi gecem degil günüm de kara

Cannımm gitti duramam buralada 

Dünya dar,ölsem bile mezarımda

Yaşayamam sensiz,sen bilmiyorsun!', 'Verip elime koskoca baltayı, Devir dedin asırlık çınarımı Nasıl bozarım daldaki yuvayı, Nasıl yaşarım sonra sormuyorsun, . Kurursa elinde kı...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sehzade-gozyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasan’ a Mektup / 6 (Sevinç)', 'hasan-a-mektup-6-sevinc-ahmet-turan-altunsu-quvys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(hilâl kaşlı, ay yüzlü bir dilber-i rânâ... / derdimin ilâcı, / başımın tacı! .. / sorgulayıp duruyordun ya hani karındaşım? ! . / muştumdur sana! ..)    

ayaklarım yere basmıyor,

kavak yelleri esiyor başımda Hasan! ..

bir bahar sabahına açmışım da gözlerimi,

kalemim artık hüzün yazmıyor...

unutmuşum bulutlar üzerinde yürümeyi.

say ki emekliyorum bu yaşımda Hasan! 

kalbim beni üzmüyor,

huma kuşu; sağolsun,

taşıyor sevdamızı uzaklara, uzaklara...

bir o, bir ben: aramızdan su sızmıyor...

hani, “artık yetti gari! ” demeyesin sakın:

gönül bu işte; tutuşmaya görsün! 

{oysa sen, biliyorum ki

-“ota da konar,..... da konar! ” dersin(!)      }

hele bir de muhabbete kulak verebilsen? ! .

hem gülmekten kırılır, hem de çok seversin! ..

asma be suratını Hasan? ! .

hâyâl gördüğümü sanmayasın...

hasta falan değilim, sapasağlam ayaktayım...

sadece, ayaklarım yere basmıyor,

sadece, kavak yelleri esiyor başımda,

sadece, bulutların üzerinde emekliyorum! ! ! 

ama ille de derdimi söylememi istiyorsan

buyur, dinle:

ondan çok uzaktayım! ..

işte, ahvalimiz bu minval üzre seyrediyor...

yaz diyeceklerini karındaşım; 

bilirsin ki boynum kıldan ince,

sana fedadır başım! 

                           31.01.2005 / Ankara

                           Ahmet Turan Altunsu', '(hilâl kaşlı, ay yüzlü bir dilber-i rânâ... / derdimin ilâcı, / başımın tacı! .. / sorgulayıp duruyordun ya hani karındaşım? ! . / muştumdur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hasan-a-mektup-6-sevinc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paylaşmak', 'paylasmak-fevzi-gunenc-z8jnk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Paylaşmak güzel şey

paylaşmalı insanlar güzellikleri

acıları da...

Paylaşılmayacak tek şey sevgili..

''Paylaşamam seni kimseyle'' diyorsun

bak sevgilim. dinle...

Hiç kaygın olmasın bu konuda

o kadar küçüğüm ki

paylaşmak istemez kimse 

beni seninle.', 'Paylaşmak güzel şey paylaşmalı insanlar güzellikleri acıları da... Paylaşılmayacak tek şey sevgili.. ''Paylaşamam seni kimseyle'' diyorsun bak...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/paylasmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılsa da hayalleri bir mavzer sesin de', 'yikilsa-da-hayalleri-bir-mavzer-sesin-de-haydar-turan-jxfnu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uçar füzeler Filistin''li çocukların üstünde,

Yıkılsa da çocukca hayalleri, bir mavzer sesinde,

Patlar bombalar, kücük bedenlerinde,

Bir gece vakti, tank sesleriyle...

Doğmaz güneş karanlık gecelerine,

Düşesi uçaklar saldırır her gece,

Barut kokar minik bedenlerinde,

Yıkılsa da hayalleri bir mavzer sesinde.

Çocuklar ölüyor,barış bunun neresinde,

Elin de taşla karşı koyarlar bilmedikleri bir güce,

Hiç görmedikleri bir oyuncağı  hayal etselerde,

Yıkılır hayalleri  bir mavzer sesin de! ..', 'Uçar füzeler Filistin''li çocukların üstünde, Yıkılsa da çocukca hayalleri, bir mavzer sesinde, Patlar bombalar, kücük bedenlerinde, Bir gece...', ARRAY['Türk Edebiyatı','Şiir','Haydar Turan']::text[], 8.5, '{"poet":"Haydar Turan","poet_slug":"haydar-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yikilsa-da-hayalleri-bir-mavzer-sesin-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Dost', 'ey-dost-huseyin-sigirtmac-bj37s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yorulmam aşkından güzel insanın.

Sevgisiz kalır mı rengi dünyanın? 

Yüreğimde alev, parlar yangının.

Söndür ateşini yanarım ey dost.

Bağrımda özlemin yürek paralar.

Düşman taşı değmez, gülün yaralar.

Beni oyalamaz sensiz buralar.

Hangi dala sensiz konarım ey dost.

Sensiz dünyadaki yaşam boşuna.

Sığırtmaç sevgiyle düştü peşine.

Sürdüm hasretliği yanan döşüme.

Hayalini görüp kanarım ey dost.', 'Yorulmam aşkından güzel insanın. Sevgisiz kalır mı rengi dünyanın?  Yüreğimde alev, parlar yangının. Söndür ateşini yanarım ey dost. Bağrımd...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ey-dost-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktın Beni Ayazınla', 'yaktin-beni-ayazinla-murat-demir-fvbg8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani bana söz vermiştin

Başka biri yok demiştin

Benden gayrı bu alemde

Hiç kimseyi sevmemiştin

Gel gör şimdi ne haldeyim

Gelen giden oldu beyim

Bir sana bak birde bana

Sen nerdesin ben nerdeyim

Yalancısın hemde fazla

Yaktın beni ayazınla

Benim gibi bir seveni

Hep aldattın birazınla

Sana değil gözlerine

Lanet olsun sözlerine

Peki şimdi mutlu musun

Ben vurdukça dizlerime

Lanet olsun sana lanet

Beni yıktı bu ihanet

Bundan böyle senin için

Nasıl derim gönlüm sabret.', 'Hani bana söz vermiştin Başka biri yok demiştin Benden gayrı bu alemde Hiç kimseyi sevmemiştin Gel gör şimdi ne haldeyim Gelen giden oldu be...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yaktin-beni-ayazinla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-zeynep-nilgun-gokceoz-x4fhd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana vereceğim ceza

Ödülün olmamalı.

Her kahpelikte olduğu gibi

Kader sana gülmemeli.

Yalanların dudaklarından döküldüğü zaman

İnanan ben değil sen olmalısın.

Aldattığın her sevgi

Yüreğinden çıkmamalı.

Ellerinle sökmeye çalışsan da

Avuçlarında sızısı kalmalı.', 'Sana vereceğim ceza Ödülün olmamalı. Her kahpelikte olduğu gibi Kader sana gülmemeli. Yalanların dudaklarından döküldüğü zaman İnanan ben de...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sana-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dileğim', 'dilegim-zeynep-nilgun-gokceoz-adjps', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalancı yarim mi desem,

Yalanın mı olsam.

Karşılıksız sevgilere

Yoldaş mı ol desem.

Suladığın her umut

Kuru bir ağaç mı olsun desem,

Beklediğin baharı

Hiç görmesen.

Elimden gelse

Bütün hüzünleri sana versem.

Sev ama

Asla sevilme desem,

Her aşkın için

Tükendiğini bilip,

Bahtsızlığına ağladığını görsem.', 'Yalancı yarim mi desem, Yalanın mı olsam. Karşılıksız sevgilere Yoldaş mı ol desem. Suladığın her umut Kuru bir ağaç mı olsun desem, Bekledi...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Nilgün Gökçeöz']::text[], 8.5, '{"poet":"Zeynep Nilgün Gökçeöz","poet_slug":"zeynep-nilgun-gokceoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dilegim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-sule-aydemir-guus0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''''Darağacına kuruldu 

________________Salıncaklarım...''''



kaybetmek ince çizgide

gölgem kendimden ağır 

taşıyamam eksikliklerimi

yanar ellerim

hayallerim hoyratlaşır 

sevda 

sevgi 

oraklaşır 

............ 

kurak topraklarda çıkan yangınların cıtırtısıdır 

yalnızlığım

......', '''''Darağacına kuruldu  ________________Salıncaklarım...'''' kaybetmek ince çizgide gölgem kendimden ağır  taşıyamam eksikliklerimi yanar elleri...', ARRAY['Türk Edebiyatı','Şiir','Şule Aydemir']::text[], 8.5, '{"poet":"Şule Aydemir","poet_slug":"sule-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizlik-221-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-sosyal Şair', 'a-sosyal-sair-mustafa-gokcek-kfofa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'A-SOSYAL ŞAİR

Dışarıda çöp kamyonlarının gürültüsü

Balkonda hijyenik şiirini yazan şair

Bence içeri girmeli açık hava ilhama zararlı

Hem gürültü, hem okumama a-sosyal şair

Şair kalem tutmalı ekinli ve esinli olduğunca

Çiftçi buğdayını ekmeli sıcak ekmekleri kucaklamalı

Aşık sazının telleriyle esmeli ozanlığını bellercesine

Kalem tutan eller nice şairleri sosyalleştirmeli



01.11.2003                                   Mustafa GÖKÇEK', 'A-SOSYAL ŞAİR Dışarıda çöp kamyonlarının gürültüsü Balkonda hijyenik şiirini yazan şair Bence içeri girmeli açık hava ilhama zararlı Hem gür...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Gökçek']::text[], 8.5, '{"poet":"Mustafa Gökçek","poet_slug":"mustafa-gokcek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/a-sosyal-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel dost', 'guzel-dost-i-lhami-arslantas-z2v3l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimliğimin sualini sorarken 

Seni buldum ben kendimi ararken 

Aynımmışsın aynaları tararken 

Sen bendesin,ben sendeyim güzel dost 

İçinde nefreti,atmışsın kini 

Bir ömür taşırım canımda seni 

Senin pencerenden gördüm ben beni 

Sen bendesin,ben sendeyim güzel dost 

Seninle yaşarım birlikte gibi 

Kendimi hissetmem hiç yükte gibi 

Düşmüşsün içime bir nükte gibi 

Sen bendesin,ben sendeyim güzel dost 

Yedi veren güller nede haklıymış 

Bütün manâ gönüllerde saklıymış 

Herkes birbirinden alacaklıymış 

Sen bendesin,ben sendeyim güzel dost 

Onca yıldır tamamımı aradım 

Kırk yıl sonra gördüm,işe yaradım 

İşte buldum sende imiş muradım 

Sen bendesin,ben sendeyim güzel dost 

İlhamiyim hakikâtin yolunda 

Ne mutlu ki dostlar sağım,solumda 

Namertlerin olsun param,pulum da 

Sen bendesin,ben sendeyim güzel dost', 'Kimliğimin sualini sorarken  Seni buldum ben kendimi ararken  Aynımmışsın aynaları tararken  Sen bendesin,ben sendeyim güzel dost  İçinde ne...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzel-dost-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Mehmet', 'coban-mehmet-zafer-topsir-i1xds', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıl 1930

Mısır tarlasında doğurmuştu 

anası

Kafkas kökenli

Sürü sahibi

Yaylacı bir aile ataları

Bereler

Tuzlaklar

Büyük koyun ağılları

Keçiler, kuzular ve atlar

Bunların yanında

Fındık ne ki fıstık ne ki

	

Önem vermezlerdi

Bahçelerine bağlarına 

Yaya beş günde varırlardı

Gavur dağlarına

Sürü meymarından öğrenmişti

Koyun gütmesini

Çoban Mehmet

Berede süt sağardı 

Şepçi kızı Macar kıyı

Abdinin hanife ve hacer teyze

Yıl dokuzyüz kırklar zekat yılları

Gaza tuza, beze insanlar muhtaç

Kıtlık demişler sabır demişler

Fındığı güdüneyi

Bulabilenler

Öğütüp yemişler

	Elde yok avuçta yok

	Gönül zengini

	Habba düşkünü

		Garibanlar

	Gün olmuş 

	Munzur eteklerinde

Ölüleri gözlermiş

Çarıklı ayaklar

Çizme için….

Gün olmuş

Bit sirkesi içerisinde

Kıvranıp durmuşlar

Güllük yatağında

Sırtları sınır sınır olmuş

Şafak vaktinde….

Şalı üzerinde 

Zıpkanın içinde

Yakışıklım yakışıklı

Çoban Mehmet

Gönül vermişti huriyeye

Hey gidi günler hey

Nereden …… nereye….

Eğircek elinde 

İplik eğirirdi

Doğan kurardı 

Dastar dokurdu 

Çama giderken 

Dallı fistanlı

Obanın alımlı kızı

Mani okurdu

Türkü okurdu…

Obada herkes

Birbirinin toyunda düğününde

İmeci ile yapılırdı işler

Mutluluk yönünde kurulurdu

Hayaller düşler 

Ehli vukuf hallederdi

Dövüşü kavgayı ve hatta

Cinayetleri bile…

Fakir ama gönlü zengin obalılar

Anca beraber kanca beraber

Yaşarlardı dünya cennetinde…

Babalar merkezde yağ satar

Seyrana buğdaya giderlerdi

	Aşkın cemresi düşmüştü gönlüne 

	Temmuzda ot biçme gününde

	Eğer sevdiğine kavuşamazsa

	Barak obasının alımlı kızı

	Ne ederdi…. Nasıl ederdi….

	Korkunun ecele faydası yok

	Yüreğini barak yapmıştı sevdiğine

	Bir gün bize bir şey olursa

	Yandı gülüm keten helva

	Deyip gezerdi….

“ Yalnız seni sevdim

Yalnız seni sevdim

için için eriyorum

aşığın gözü kör

yüreği kor

Deli divaneyim “

Sözlerini duymamıştı

Eroin tozu kadar

Gönlü beyaz hainler

Birbirlerine doymadan

Doyamadan 

Ciğer delik deşik

Ölümüne ağlaştılar

“Armudu yedin yedin

Zıpçığına ne dedin

Haçan almayacaktın

Niye alırım dedin

Seni alırım diye

Bana yalan söyledin”

Deyip gezerdi

Kurşun sıktılar

Sevdalarına 

Sevdalılara

	Adil hoca öğretmen olsun

	Zeki bir çocuk Mehmed

	Keçiyi bıraksın

	Demesine diyecek

	Anası …. Ah anası

	Söylendi… “malımızı kim yiyecek”

	Umudunu saklamıştı çoban Mehmed

	Çocuklarına torunlarına 

	Lami cimi yok 

	Onları hazırlayacaklardı yarına

Özgür olmayı

Mazlumdan yana olmayı

Zincirsiz yularsız

Ağılda rahat yatan

Koyundan, keçiden öğrenmişti.

	Oyunu demirkırata vermişti

	Komşusu köylüsü

Olmamıştı çoban mehmedin

Güçlü bir partisi

Sürü devrinin kapandığını görmüştü

Mısırda para etmiyor

Irgatlık için

Ayakları daha gitmiyor

Çoban mehmedin

Alamanyaya da yazılmamıştı

Doldurmuyordu da fındık sepeti

Ama yine de çocuklarını 

Okutmaktı hevesi 

Dedesini halasını

Yavaş yavaş ebedi yurduna

Yolcu ediyordu birer birer

Alıp götürdü bizi derdi

Kader ….. kader….. kader……

Alaman zenginmiş 

Balçıka zenginmiş

Ana komşu Urusu bilmiyordu

Gurbetçilerin anlattıkları

Kulaklarından silinmiyordu.

	Oralarda buradan farklı olarak 

	Komşulara yardım yokmuş

Bölüşüm yok dostluk yokmuş

Onsekizine gelince evlat

Baba evinden terkmiş

Ancak onların zenginleri,

Beğenmedikleri işte çalışmasalarda

Ahaliye bakarlarmış

Oda hayal etmeye başlamıştı 

Elektrikli evleri

Telefonu

Köyünde fabrika bacalarını

Asfalt yolları

Ve musluktan akan suları

	Köy, Karadeniz, Gavurdağı

	Ömrünü yiyip bitirmişti

	Yinede çoban mehmedi

	Onlar bu günlere getirmişti.

970 ortaları 

Gelip çatmıştı

Enflasyon terör

Savaş yılları gibi

Kıtlık yılları gibi

Yine yakmıştı Anadoluyu

Oğulları üniversitede 

Sıkça mektup yazamamıştı

Enflasyonu, terörü, mafyayı

Hür kümeste hür tilkiyi

Bu sefer sezememişti.

	Eşkiya uykusundan uyandı

	Tabakasına  uzandı

	Çakmağını eline aldı

	Tüttürdü cigarasını acı acı

	Bakkal Mehmet artık 

	Ne yapacaktı…. Nasıl yapacaktı.

Dalgı gitmişti o gün yalıya

Bir serseri kurşun 

Titredi çoban Mehmet birdenbire 

Götürdüler bedenini

Ebedi evine

Unutmayacak gavurdağları 

Ve unutmayacak Anadolu

Çoban mehmedi

Bakkal Mehmedleri

                      Zafer TOPŞİR Aralık 2001', 'Yıl 1930 Mısır tarlasında doğurmuştu  anası Kafkas kökenli Sürü sahibi Yaylacı bir aile ataları Bereler Tuzlaklar Büyük koyun ağılları Keçil...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":188,"source_url":"https://www.antoloji.com/coban-mehmet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulan sevdamız', 'unutulan-sevdamiz-cenk-aksal-mwm4c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaz türkülerinin,sonbahar sevişmelerinin

uzağında,deli bir fırtına gibi yaşam

her sabah uyandığımızda acıdan ürperip,

hüzünleri üretiriz istemeden,çaresiz

sevgiyi,aşkı unuttuk acının tenhalarında

kalplerimiz,kirli yarınlara alıştı,

oysa her aşk mutluluktur

aşk denizin mavisinde saklıdır

şimdi sevdalarımız,dağların ardında

geleceğimiz,sonsuz zaman tünelinde kaldı

alaca şafakta yitirdik zamanı.

kör gecelerde koybolduk hepimiz,

sonsuz acılarla uyanıp,her sabah,

uykunun derinliklerinde avunur

boşvermişliğin peşinde geziniriz...', 'yaz türkülerinin,sonbahar sevişmelerinin uzağında,deli bir fırtına gibi yaşam her sabah uyandığımızda acıdan ürperip, hüzünleri üretiriz ist...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutulan-sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdamda Aşk Kavgamda Aşk', 'sevdamda-ask-kavgamda-ask-zafer-topsir-2w1jb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yârime çiçek topladım

Yaddan yabandan sakladım

Kokusu yetiyor bana 

Sevdamda aşk kavgamda aşk

Çare olmaz yara doktor

Çobanın bir şeyi yoktur

Gönlün sunar sunasına

Sevdamda aşk kavgamda aşk

Yar yoluna varın verir

Başım gözüm üstüne der

İçim yordun koca dünya

Sevdamda aşk kavgamda aşk

Bir baş soğan kuru ekmek

Hasretin görevi, yakmak

Vefasızlık çıldırtacak 

Sevdamda aşk kavgamda aşk

Dönenler hep savruldular

Dört kul bir güzel, durdular

Demir asa demir çarık

Sevdamda aşk kavgamda aşk

Buruşturup atamazsın

Yerin yoktur yatamazsın

Yoktan ancak yok gidecek

Sevdamda aşk kavgamda aşk

Uyan gülüm uyan uyan 

Dayan yüreciğim dayan

Yağlı ilmeği boynuma

Sevdamda aşk kavgamda aşk

Çoban ali mahzun günün

Oruç benim bayram elin 

Dağlar sevginin beşiği 

Sevdamda aşk kavgamda aşk

                              Ali Zafer TOPŞİR \ Aralık 2005', 'Yârime çiçek topladım Yaddan yabandan sakladım Kokusu yetiyor bana  Sevdamda aşk kavgamda aşk Çare olmaz yara doktor Çobanın bir şeyi yoktur...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevdamda-ask-kavgamda-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tonlarca Barutun Sisi', 'tonlarca-barutun-sisi-zafer-topsir-ot9wq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tonlarca barutun sisi, 

Kimi sakat, ya kimisi, 

İnsanlığın tek ülküsü, 

Bayramınız bayram ola.

Ormanları gümbür gümbür, 

Uçuşurlar kuşlar özgür. 

Gül derdine yanan bülbül, 

Bayramınız bayram ola.

Başı bağlı beyaz puşi, 

Dolanıyor dağı, taşı. 

Kuzuların can yoldaşı, 

Bayramınız bayram ola.

Sevgi suyu ilaç cana, 

İçem ondan kana kana. 

Yavrudan ayrılan ana, 

Bayramınız bayram ola.

Gençlik biter, ilerler yaş, 

Hayat yürür yavaş yavaş, 

Sönen yıldız batan güneş, 

Bayramınız bayram ola.

Der''din, herşeye yabanım. 

Doğum yerim Sivas benim 

Gözler gizli Ahmet canım. 

Bayramınız bayram ola.

Devir devir, nöbet nöbet, 

Bir tek sevda kalır ebet. 

Bizim köylü deli memet, 

Bayramınız bayram ola.

Mevlam nice kullar vermiş. 

Kimi meczup kimi ermiş. 

Çileyle bekleyen derviş. 

Bayramınız bayram ola.

Yıllarca, yolunu bekler. 

Dünü bugüne ilmikler, 

Sevda dolu genç yürekler, 

Bayramınız bayram ola.

Deli oluyorum deli, 

Matem kınalıdır eli, 

Boyalı cam sakinleri, 

Bayramınız bayram ola.

Gel terkeyle alemleri. 

Bulamazsın o demleri. 

Gökyüzünün kalemleri. 

Bayramınız bayram ola.

Herkes eşit hep birdirler. 

Mahşer yerine yürürler. 

Gelmezden önce dinler. 

Bayramınız bayram ola.

Ölüleri dirileri, 

Biri gelir, binleri... 

Dosta koşan seherleri, 

Bayramınız bayram ola.

Geçiciden kim ne bekler. 

Hebaya gitti emekler. 

Musalladaki garipler. 

Bayramınız bayram ola.

Yaprak dökümü yazında. 

Söz artık oğlun, kızında. 

Dört kişinin omzunda. 

Bayramınız bayram ola.

                            Zafer Topşir', 'Tonlarca barutun sisi,  Kimi sakat, ya kimisi,  İnsanlığın tek ülküsü,  Bayramınız bayram ola. Ormanları gümbür gümbür,  Uçuşurlar kuşlar öz...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/tonlarca-barutun-sisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım', 'aklim-cenk-aksal-zxcxt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'insanlığını,unutmuş,

bu zalimlerin arasında,

ilk çağlardan kalmış gibi

barbarca savaşıyorum,

hangi yaşamın,neresindeyim

artık aklım ermiyor,

hangi yalnışlara düştüm

neresinde yanıldım hayatın

kader mi yoksa yaşadıklarım

artık aklım ermiyor..', 'insanlığını,unutmuş, bu zalimlerin arasında, ilk çağlardan kalmış gibi barbarca savaşıyorum, hangi yaşamın,neresindeyim artık aklım ermiyor,...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aklim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara Haber', 'yara-haber-zafer-topsir-hgjle', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sarıkamışa

Koyun meler, kuzu meler, 

Bin derdim var, neler neler, 

Gelen geçen bu trenler, 

Yare haber götürseler.

Hicran akar durdu yaşlar, 

Öteye mi kaldı düşler.? 

Gökyüzünde uçan kuşlar, 

Yare haber götürseler.

Vatan bize yaban eller,

Bizim ilde soldu güller.

Ilık ılık esen yeller, 

Yare haber götürseler.

Kapalı duruyor yollar, 

Bitip tükenmez arzular, 

Şırıl şırıl akan sular, 

Yare haber götürseler.

Şura şehir, şurası köy, 

Şunlar fakir, şunlar da bey, 

Bütün her şey, bütün her şey... 

Yare haber götürseler

                                  Zafer Topşir', 'Sarıkamışa Koyun meler, kuzu meler,  Bin derdim var, neler neler,  Gelen geçen bu trenler,  Yare haber götürseler. Hicran akar durdu yaşlar,...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yara-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-zafer-topsir-k2mvi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Yapraklar açtı mı desem, 

Leylekler uçtu mu desem, 

Gönlüm yola düştü desem, 

Ah sevgili anam ah... ah! 

Çiçeklerin soluşunu, 

Seyrederdim gülüşünü, 

Duy kimsesiz kalışımı, 

Ah sevgili anam ah... ah! 

Şırıl şırıl su süzülür. 

Sözler kağıda yazılır. 

Yaşlar bir yerde dizilir. 

Ah sevgili anam ah... ah! 

Bayramlık kına elime, 

Bir hediye sevgilime, 

Veremedim bu yıl yine, 

Ah sevgili anam ah... ah! 

Umut dolu dolu her dem, 

Yaralı gönlüme merhem, 

Ben anamı nasıl görem, 

Ah sevgili anam   ah...ah! 

Hasretinle yanıyorum, 

İçin için kanıyorum, 

Kavuşmadan ölüyorum, 

Ah sevgili anam ah... ah

İnsanoğlu nasıl özgür, 

Vatan inler, inler gel gör, 

Altın kafesteki bülbül, 

Ah sevgili anam ah... ah! 

İnle garip kuşum inle, 

Birazcık da beni dinle, 

Neler paylaştık seninle, 

Ah sevgili anam ah... ah! 

Herkes dostlarına koşar, 

Anam bensiz nasıl yaşar, 

Kanat takıp gönlüm uçar, 

Ah sevgili anam ah... ah! 

Hacı Bayram Hacı Bayram, 

Divaneler sana hayran, 

Nasılsın ana bu bayram? 

Ah sevgili anam ah... ah! 

Halim bu bayram gününde, 

Bir gelin çocuk elinde, 

Biz de böyleydik seninle, 

Ah sevgili anam ah... ah! 

Nasip olur bayramlaşmak, 

Zorlu engelleri aşmak, 

Ölmez bayrama ulaşmak, 

Ah sevgili anam ah... ah! 

                         Zafer Topşir', '''Yapraklar açtı mı desem,  Leylekler uçtu mu desem,  Gönlüm yola düştü desem,  Ah sevgili anam ah... ah!  Çiçeklerin soluşunu,  Seyrederdim ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/anam-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayşen', 'aysen-zafer-topsir-c354e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece gözlerim seni aradı 

Utandım bakmaktan, yollara Ayşen 

Sayılı günlerdi, su gibi aktı 

İsyanım var sensiz yıllara Ayşen! 

Okulun bahçesi buluşma yeri 

Zil çalınca herkes girer içeri 

Saplandı kalbime aşkın hançeri 

Sevdamız düşmüştü dillere Ayşen! 

Cuma gün doğduğun ilçeyi gördüm 

Orada herşeyden hep seni sordum 

Rüzgarın ardına düştüm savruldum 

Kıvılcımlar saçtın küllere Ayşen! 

Başka bir şey gelmez, gelmez elimden 

Öyle tatlı gülüşün var hayalimde 

Benim kır çiçeğim şimdi kimlerde 

Bedduam var saran kollara Ayşen! 

Gözü görmez genç abayı yakınca 

Hele birde aşk bacayı sarınca 

Sizin yurda dikkatlice bakınca 

Dalıp gittim eski günlere Ayşen! 

Yaremden kan aksın basmayın tütün 

İlaçsız hastayım başımdan gidin 

Kavrulan dudağım çatladı bütün 

Çöllere düşmüşüm, çöllere Ayşen! 

Yanıma oturdu yaşlı bir adam 

Duramadım seni ona sormadan 

Tamam...şimdi bildim sorduğun madam 

Düştü çok değişik hallere Ayşen! 

                                                        Zafer Topşir', 'Dün gece gözlerim seni aradı  Utandım bakmaktan, yollara Ayşen  Sayılı günlerdi, su gibi aktı  İsyanım var sensiz yıllara Ayşen!  Okulun bah...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aysen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-zafer-topsir-59ns1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Açıl tomurcuk gül, yalnız değilsin. 

Deli gönül bekler seni sevgili. 

O kim ise beri gelsin demişsin, 

Deli gönül bekler seni sevgili.

Nere baksam hep o durur karşımda 

Yayla yapıp, kışlar oldu düşümde, 

Şafak vakti köyde çeşme başında, 

Deli gönül bekler seni sevgili.

Göz gayriyi görmez körpe ciğerde, 

Bir mahluk yok sevgi sevda değerde, 

Aklın alıp gözün gördüğü yerde, 

Deli gönül bekler seni sevgili.

Sis kapladı sevgimizin üstünü, 

Bilemedin düşmanını, dostunu, 

Düşünme hiç o yar sana küstü mü? 

Deli gönül bekler seni sevgili.

Kim suçludur, aramızda geçenden, 

Soram seni gezenlerden uçandan, 

Ne sen ne ben, ayrılığı seçenden, 

Deli gönül bekler seni sevgili.

Yola yakın koyun bi vefa görür, 

İç rnezar suyumu yürekten gelir, 

Sinem sana çiçek verir, gül verir, 

Deli gönül bekler seni sevgili.

Aşktan gayrı merhem yoktur yareye, 

Gelir misin hatırımı sormaya, 

Kendin için sakın mezar arama, 

Deli gönül bekler seni sevgili.

Gönül arzu eder sevgiye koşmak. 

Adım adım sevgiliye yaklaşmak, 

Ufuktan da uzak olsa ulaşmak. 

Deli gönül bekler seni sevgili

Müşgüle düşmüşüm hesap işinde, 

Helal lokma, sevgi çıktı aşımda, 

Gelir diye seni mizan başında, 

Deli gönül bekler seni sevgili.

Herkeste bir şeyler, ben ne almışım! 

Gücüm yoktur, hediyesiz gelmişim. 

Boynu bükük, mahzun, yetim kalmışım. 

Deli gönül bekler seni sevgili.

                                                Zafer Topşir', 'Açıl tomurcuk gül, yalnız değilsin.  Deli gönül bekler seni sevgili.  O kim ise beri gelsin demişsin,  Deli gönül bekler seni sevgili. Nere ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/deli-gonul-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Ettiler', 'gurbet-ettiler-zafer-topsir-9p40c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüce dağlar başı hey gönül hey hey! 

Yaralı yüreği, sevgili bir duy 

Şimdi nasıl acep, nasıl bizim köy? 

Benim ile beni gurbet ettiler.

Bozulmuş bahçeler, solgunca güller. 

Aşk yağmuru suskun, kurumuş dallar. 

Karma karış olmuş, gönülden yollar. 

Can ile cananı gurbet ettiler.

Kafeste kapalı, ufacık serçe, 

Derler senin için, o gider güce 

Birbirinden kopmaz, gündüzle gece 

Bu gün ile dünü gurbet ettiler

Kavuşmamız hayal, canların canı, 

Sevgili nerede, sevdalar hani? 

Hem geçici hem ezeli vatanı, 

Gurbet ettiler dost, gurbet ettiler.

                                                Zafer Topşir', 'Yüce dağlar başı hey gönül hey hey!  Yaralı yüreği, sevgili bir duy  Şimdi nasıl acep, nasıl bizim köy?  Benim ile beni gurbet ettiler. Bozu...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gurbet-ettiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Ve Anılar', 'yagmur-ve-anilar-cenk-aksal-r03th', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dışarda yağmur yağıyor

çatıda tıkır tıkır damlaların sesi

soğuk bir sonbahar gecesi

yağmurun şırıltısı ninni gibi

buğulu camların ötesinde damlalar

damlalar bir durup bir zıplayarak

camdan aşağıya kayıyorlar

dalıpta eski bir sevdanın anılarına

saçları sırıl sıklam sevgilimin

yağmur damlaları arasında kaybolan

gözyaşlarına takılıp kalıyorum

boğazım düğüm düğüm

ve o günlerden kalma bir şarkı çalıyor

yağmurlu bir gündü buluştuğumuzda

kimseler görmedi öpüştüğümüzü

ve yalnızlığım aklıma geliyor

ne zaman yağmur yağsa utanıyorum

çatıdan yağmur tanelerinin tıkırtısı gelince

camın öte yanında damlalar dansa başlayınca

dar bir sokağın köşesinde ıslak sevgilimin

yüreğimde bıraktığı sızı kıpırdanır

ve o hüzün şarkısı çınlar kulaklarımda

ben öyle yağmurları sevmem

ne zaman yağmur yağsa utanıyorum

benim canımı sıkan yağmur değil

caddeleri suların almasıda değil

benim canımı en çok sıkan

damlalarda yaşanan minik minik

milyonlarca sevda yerine

yalnızlığımın yüreğimi sızlatması

bir yağmur tanesinde eski sevdaları,

yaşamak yerine,yalnızlığımı paylaşmak

benim canımı sıkar durur,

benim sevdiğim yağmurlarda

damlalar anıları taşır

bir ıslak sevgilinin şarkısını duyarım,

ve kapı açılır anılar içeri dolar

ne zaman yağmur yağsa utanırım...', 'dışarda yağmur yağıyor çatıda tıkır tıkır damlaların sesi soğuk bir sonbahar gecesi yağmurun şırıltısı ninni gibi buğulu camların ötesinde d...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yagmur-ve-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Mahsun', 'gonul-mahsun-zafer-topsir-uurx4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yapraklar açtı mı bilemiyorum, 

Aşılmaz dağlardan gelemiyorum, 

Ayrı düştüm yardan, gülemiyorum, 

Günüm mahzun, gönül mahzun, Gülbahar! 

Özlemişim Erimez''in yolunu, 

Mahkum oldum bağladılar kolumu, 

Bir hücrede bekliyorum sonumu, 

Günüm mahzun, gönül mahzun Gülbahar! 

Kara gölün başı kar ile boran, 

Hastaneye düştüm dediler verem, 

Ne ziyaret eden, ne bir su veren, 

Günüm mahzun, gönül mahzun Gülbahar! 

Her gün iğne yapıyorlar adama, 

Doktor beyim kapıları kapama, 

Ölüyorum, bir haber sal anama, 

Günüm mahzun, gönül mahzun Gülbahar! 

Demet demet çiçek ellere gider, 

Ziyaret günleri beni deli eder, 

Ciğerimi sardı gam ile keder, 

Günüm mahzun, gönül mahzun Gülbahar! 

Böyle yazmış kaderimi yazanlar,

Bizi   ayıramaz   ara   bozanlar

Derin kazın mezarımı kazanlar,

Günüm mahzun, gönül mahzun Gülbahar! 

                                                         Zafer Topşir', 'Yapraklar açtı mı bilemiyorum,  Aşılmaz dağlardan gelemiyorum,  Ayrı düştüm yardan, gülemiyorum,  Günüm mahzun, gönül mahzun, Gülbahar!  Özl...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonul-mahsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustosta Kar', 'agustosta-kar-zafer-topsir-7b7pz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rengarenk çiçekler, buğulu sular, 

Karagölün yollarına sor beni. 

Vadilerde bayazlıklar bambaşka, 

Deli eder Ağustosta kar beni.

Çadırlar kurulur düze, bayıra, 

Sürüler sürülür ota, çayıra, 

Beni senden kimler, niçin ayıra, 

Al götür de dağdan dağa vur beni.

El köyüne köyüm desem ne çıkar, 

Dereler ummana akar ha akar, 

Bu ayrılık seni de beni de yıkar, 

Bilmem arar mı ki, nazlı yar beni.

İşte söylüyorum perişan halim, 

Kaderimiz böyle biz ne yapalım, 

Evi yok barkı yok dul kalmış gelin, 

İflah olmaz derde koydu cer beni.

Boşuna tesellin boşuna bırak, 

Gönlüm olsun sana hem ev hem durak, 

Arada engel var kavuşma ırak, 

Verem eder gönüldeki ur beni.

Doktor kapısında bekleme işim, 

O yardan gayrisi olamaz düşüm, 

Her şeyimsin benim; ekmeğim, aşım, 

Erim erim eritiyor nar beni.

Ciğerlerim cayır cayır yanıyor, 

Azgın yaralarım göz göz kanıyor, 

Yetiş anacığım yavrun ölüyor, 

Ağır ağır tüketiyor kor beni.

Gece ayaz sokaklarda gezilmez, 

Doktor, bu hastaya ilaç yazılmaz, 

Sevda vurgununa mezar kazılmaz, 

Kolun açıp yüreğine sar beni.

Umudun tükenmez bir gün gelirsin, 

Sevda çılgınıyım bunu bilirsin, 

Eğer sana kavuşmadan ölürsem, 

Yalvarırım mahşer günü gör beni.

                                           Zafer Topşir', 'Rengarenk çiçekler, buğulu sular,  Karagölün yollarına sor beni.  Vadilerde bayazlıklar bambaşka,  Deli eder Ağustosta kar beni. Çadırlar ku...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/agustosta-kar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fakülteliye', 'fakulteliye-zafer-topsir-4s4dr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fakülteliye

Gönlümü gönlüne verdim bir kere, 

Verileni almak, zehirdir Ayten! 

Yeryüzünde sensiz gezip dolaşmak, 

Kahırdır sevene, kahırdır Ayten! 

Dağlara güz geldi bozuldu yaprak, 

O nazlı gülümü sardıysa toprak, 

Perişan halime bir lahzacık bak! 

Bu çile çok ağır, ağırdır Ayten! 

Paylaşım öğrettin bütün canlara, 

İnsanlık hasrettir, özgür günlere, 

Kerbela boyandı, kızıl kanlara, 

Bize darağacı seyirdir, Ayten! 

Karşılıksız çıktı verilen çekler, 

Bilmem boşuna mı bunca emekler? 

Doğuştan çarıklı kahpe yürekler, 

Sağırdır acıya, sağırdır Ayten! 

Ağlasın yeryüzü, ağlasın gökler, 

Yeşil örtü, kara taş yolunu bekler, 

Gel artık, n''olursun söktü şafaklar, 

Nehirdir kalp gözüm, nehirdir Ayten! 

                                        Zafer Topşir', 'Fakülteliye Gönlümü gönlüne verdim bir kere,  Verileni almak, zehirdir Ayten!  Yeryüzünde sensiz gezip dolaşmak,  Kahırdır sevene, kahırdır ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Topşir']::text[], 8.5, '{"poet":"Zafer Topşir","poet_slug":"zafer-topsir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/fakulteliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-ali-gencay-sgmmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kat,kat giydiğim pişmanlıklar

Tutunduğum dalı kırıp

Sonsuzluğa düşüyorum

Dibine daldığım cehennem

Yanıyor taştan yakıtlar

Bende titreme

Üşüyorum

Kuşlar uçuşuyor tepemde

Garip,adlarını bilmiyorum

Gagalarında kan,kanatları  kılıçtan

Çiçek atıyorlar,kan kırmızı

Çiçekler gülümsüyor bana

Bende sızı,inceden ince

Ağlıyorum

Havada ağır intihar kokusu

Hüzün,damarıma giriyor

Beynimde yapma demenin uğultusu

Rüyalar giriyor kanıma,uyanıyorum

Bende ne yapacağını bilmeme duygusu

Bilmediğim sona yürüyor

Korkuyorum', 'Kat,kat giydiğim pişmanlıklar Tutunduğum dalı kırıp Sonsuzluğa düşüyorum Dibine daldığım cehennem Yanıyor taştan yakıtlar Bende titreme Üşüy...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korku-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye mektuplar1', 'sevgiliye-mektuplar1-denizhan-solmaz-i6cxz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dokunma demiştin (demiştim)

yanarsın....

yandımda....(yandında) 

kaç yaşındaydım anımsamıyorum 

ateşle tanışmamı

ama halen izi var kolumda

''cis'' demişleridi 

yanarsın demişlerdi ya...

şimdi daha iyi anlıyorum.

sonra buz koyarsın yanığına

buz erir...

en sondamlası sıyrılıp gider

göz yaşınla birlikte 

acık ateşini almıştır 

ama sen yanık kiremi sür 

ben senin yanığına ançak buz olurum

iyleşmez yaran

sızını alabilirim belki

ama yanık kiremi öylemi! 

kapatır yaranı belki izi bile kalmaz yaranın

içine tenine girer ve artık sen olur

oysa ben 

ben erir giderim.....

hangi göz yaşı geri geldi ki.......

ben geleyim

düştüm gözünden (gözümden)  artık', 'Dokunma demiştin (demiştim) yanarsın.... yandımda....(yandında)  kaç yaşındaydım anımsamıyorum  ateşle tanışmamı ama halen izi var kolumda ''...', ARRAY['Türk Edebiyatı','Şiir','Denizhan Solmaz']::text[], 8.5, '{"poet":"Denizhan Solmaz","poet_slug":"denizhan-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sevgiliye-mektuplar1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğimi Söyleyemedim', 'sevdigimi-soyleyemedim-sahin-erturk-mhvw7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzelliğine önce sana baktım

Sonra aynaya,saçlarıma baktım

Bir acayiplik gördümde bu aşkta

Seni sevdiğimi söyleyemedim

Toplum kabul etmez böyle bir aşkı

Yüreğim kanıyor,gözlerim yaşlı

Bu kalpten bu sevgi çıkmaz bulaştı

Seni sevdiğimi söyleyemedim

Senin düşlerin,geleceğin vardı

Benim geçmişim,gerçeklerim vardı

Düşle gerçeği karıştırmadım''da

Seni sevdiğimi söyleyemedim

Milyon kere geldi inan dilime

Sözcükler boğazda tıkalı hala

Bilenler gülüyor,şaşkın halime

Seni sevdiğimi söyleyemedim

((BOYALI DÜŞLER adlı

4.ncü şiir kitabımdan)

04.01.2003-Takvim Gazetesi)', 'Güzelliğine önce sana baktım Sonra aynaya,saçlarıma baktım Bir acayiplik gördümde bu aşkta Seni sevdiğimi söyleyemedim Toplum kabul etmez bö...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdigimi-soyleyemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bölünme', 'bolunme-ertugrul-sakar-cigep', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece gündüz oldu bölündü zaman

Işık oyunlarının sonunda', 'Gece gündüz oldu bölündü zaman Işık oyunlarının sonunda...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bolunme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Köşe', 'dort-kose-i-hsan-uncuoglu-mjun6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ufka yelken açtık

Dünyanın deryasında

Rüzgarımız yerinde 

Uçuyoruz hepimiz 

Yolun sonu birdir bir 

İnsan bilmez  Allah bilir

Güle oynaya gidiyoruz

Kendimizden habersiz,

***

Maşallah doğru yoldayız yanlışsa eyvallah 

Sevda yolunda uğruna al takke ver külah,', 'Ufka yelken açtık Dünyanın deryasında Rüzgarımız yerinde  Uçuyoruz hepimiz  Yolun sonu birdir bir  İnsan bilmez  Allah bilir Güle oynaya gid...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dort-kose-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maneviyat', 'maneviyat-i-hsan-uncuoglu-dp84a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar herbiri

Zaman değerli 

Paralısın birader 

Sağlıklı insanlık 

Babadan kalmasın

Olmazsa duyardım 

Neler oluyor neler', 'İnsanlar herbiri Zaman değerli  Paralısın birader  Sağlıklı insanlık  Babadan kalmasın Olmazsa duyardım  Neler oluyor neler...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/maneviyat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzuhalim', 'arzuhalim-mustafa-zincirkiran-frh11', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya Rabb’i ilham ver, dedim Bismillah

	İlahımsın senden başka yok ilah.

	Kulun ve habîbin o Resulullah

	İnandım sana şirk, koşmam Allah’ım.

	Atom bir zerredir, gözle görülmez

	Galaksiler büyük, ona erilmez.

	Nasıl bir tertip ki, döner yorulmaz

	Tesadüf değil ki, şaşmam Allah’ım.

	Yoktan var etmişsin, yeri ve göğü

	Seni tesbih eder, karınca – arı.

	Bana nasip etsen Cennet diyârı

	İzninle haddimi, aşmam Allah’ım.

	Aşkın yaksa, şu bağrımı başımı

	Gönlüme akıtsam gözüm yaşını

	İkram etsem, nîmetinden aşımı 

	Şeytanın ardından, koşmam Allah’ım.

	Derviş kullar, boyun büker el bağlar

	Allah Allah deyip, aşk ile ağlar

	Göz yaşı dökerken kâlbini dağlar

	Riyakârca kab’tan taşmam Allah’ım.

	Halakada zâkirlerde dil olsam

	Yansam aşkın ile hepten kül olsam

	Yüce zât’ına da lâyık kul olsam

	Bir daha hatâya düşmem Allah’ım.

	Behlül kulun işte diliyor böyle

	Kusurlu da olsa sen kabul eyle

	Sen bilirsin Rabb’im neylersen eyle

	Kendimi kaybedip, coşmam Allah’ım. 

	                                                               18.11.1999', 'Ya Rabb’i ilham ver, dedim Bismillah 	İlahımsın senden başka yok ilah. 	Kulun ve habîbin o Resulullah 	İnandım sana şirk, koşmam Allah’ım. 	...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Zincirkiran']::text[], 8.5, '{"poet":"Mustafa Zincirkiran","poet_slug":"mustafa-zincirkiran","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/arzuhalim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Mavisi', 'kar-mavisi-husnu-bozkurt-9wcn5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(kar mavisi bir aydınlık doldu mu hiç gözlerinize

siyah beyaz bir resim taşıyor musunuz yüreğinizde...) 

kar mavisi bir aydınlıkta gördüm onu

birden çıktı karşıma hiç beklemiyordum

ince uzun duruyordu

sazlar arasında tek başına kıvrılmış bir leylek gibi

hayatımın soru işaretiydi sanki

hayal miydi düş müydü yoksa gerçek mi? 

ağaçları çıplanmış

hüznü salkım saçak bir kış ikindisiydi

saçları dalga dalga omuzlarına salıktı

hava soğuktu

kan bulaşığı lacivert bulutlar vardı gökötesi

yanaklarına dökülmüştü kirpiklerinin gölgesi

dudakları morumsu benzi soluktu

o''nu gördüm

siyah beyaz bir resim gibiydi

bilinmez hangi galerinin duvarından

öyle mahzun

anlaşılmaz...

tutuklu kelebekler çırpınıyordu gamzelerinde

kimi kimsesi yok gibiydi alemde

sesi var mıydı dünyalı mıydı

kadın mıydı kız mıydı yoksa çocuk mu

bir aydınlık görülmedik kar mavisi

o''muydu aydınlıkta duran aydınlık mı o''ndandı? 

günü üşümüş bir cumartesi

aşık kollar gibi sarmıştı boynunu kızıl atkısı

yakasını kaldırmış etekleri buz beyazı

ellerinde rengi eksilmiş yün eldiven

avuçlarında mısır taneleri

sağ şakağına dizilmiş belli belirsiz üç ben

yeşili sızıyordu gözlerinin kirpiklerinden

o''nu gördüm

siyah beyaz bir resim gibiydi

bilinmez hangi ressamın tuvalinden

öyle masum

anlatılmaz...

eflatun bir güvercin yağmuru düşüyordu kaldırımlara

puslu boşluğa görünmez düğümler atan kırık kanat sesleri

gitgide eksilen

duvarın dibinde bir ıslak kedi bir başınalığını miyavlıyordu

o kış ikindisi o meydan oluk oluk yalnızlık kusuyordu

eksilen yoksa hayat mıydı? 

siyah beyaz tek başına kıvrılmış duruyordu

üşüyor muydu

avularıma doldurup yüzünü sıcacık öpmek geldi içimden

renk eksilsin ses eksilsin isterse hayat eksilsin de o 

                                                                 eksimesin istedim

gamzelerinden kelebekleri kanatlanıversin

gün üşüsün donsun isterse ama o üşümesin

hayatımın soru işaretiydi

ve bir yudum aydınlık görülmedik kar mavisi

elimde değildi

o''nu sevdim

öyle çok

inanılmaz...

sonrası 

kar mavisi bir aydınlık gözlerimin içinde

siyah beyaz bir resim var artık yüreğimde 

                                                   Şubat / 2003 - Konya', '(kar mavisi bir aydınlık doldu mu hiç gözlerinize siyah beyaz bir resim taşıyor musunuz yüreğinizde...)  kar mavisi bir aydınlıkta gördüm on...', ARRAY['Türk Edebiyatı','Şiir','Hüsnü Bozkurt']::text[], 8.5, '{"poet":"Hüsnü Bozkurt","poet_slug":"husnu-bozkurt","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/kar-mavisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-tayfun-yilmaz-g62av', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kusura bakma gidiyorum

sensizligi seçiyorum

sana göre dogru

ama bana göre yanlış

farketmez yine de gidiyorum

ne kadar sevsem 

ne kadar baglansam 

olmuyor canım

gidiyorum..', 'kusura bakma gidiyorum sensizligi seçiyorum sana göre dogru ama bana göre yanlış farketmez yine de gidiyorum ne kadar sevsem  ne kadar bagla...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Yılmaz']::text[], 8.5, '{"poet":"Tayfun Yılmaz","poet_slug":"tayfun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gidiyorum-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-cenk-aksal-t2swx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gelecek bir gün elbet

sonbahar

dökülecek ve solacak

o yemyeşil yapraklar

hüzünle dolu olacak

o neşeli mutlu insanlar

son bulacak toz pambe

sonsuzluklar

isyan edecek birden

güzelim kiraz dudaklar

güller solarken

yağmur yağarken

gelecek bir gün

sonbahar

herşey bir anda

son bulacak

bütün yaşananlar

silinip anılarda kaybolacak

işte mevsim SONBAHAR..', 'gelecek bir gün elbet sonbahar dökülecek ve solacak o yemyeşil yapraklar hüzünle dolu olacak o neşeli mutlu insanlar son bulacak toz pambe s...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sonbahar-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-hasan-can-x8oww', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ayna durur karşımda,

Kendime değil, geçmişime bakıyorum.

Geleceği umursamadan, geçmişimi soruluyorum.

Biliyorum hiçbir şey gelmez elimden geçmişe dair,

Elimde değil geçmişimi silip atmak...

Aynaya sırtımıda çevirsem,

Ben yine aynadaki gerçeği görüyorum,

Acısı dinmemiş gerçeği,

Bir türlü aklımdan çıkmayan geçmişi.

Ben aynaya baktıkça kendimi değil,

Kendi geçmişimi görüyorum,

Ve gördüklerim gözümün önünden gitmeyecek biliyorum...', 'Bir ayna durur karşımda, Kendime değil, geçmişime bakıyorum. Geleceği umursamadan, geçmişimi soruluyorum. Biliyorum hiçbir şey gelmez elimde...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayna-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Ben', 'i-ste-ben-cenk-aksal-k3zeh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kapkaranlık gecedeki işıksız ateş

duvarlardaki çatlakların motifleri

sigaramdan çıkan puslu duman

birşeyler çağrıştırır kalbimde

her zaman birşeyler yapmak

en güzeli aşık olmak istemek

birgün aşkı tanıyıp yaşamak

sonrada ümitsizlikle yıkılmak

birçok kez aldatılmak sevgide

isyanları şiirlerde anlatmak

bir mum gibi erimek gecede

sonrada ümitsizlikle yıkılmak

birçok şey yaşamak varken

yokalan hayallere aldanmak

yüreği kasıp kavuran sevgiyi

bir hiç uğruna gömmek toprağa

esir olmak öldüren yalnızlığa

yüzlerce aşk arasında aşksız yaşamak

mutluluğu hayel etmek sadece.

çabalamak yaşamı ve aynı dramı...', 'kapkaranlık gecedeki işıksız ateş duvarlardaki çatlakların motifleri sigaramdan çıkan puslu duman birşeyler çağrıştırır kalbimde her zaman b...', ARRAY['Türk Edebiyatı','Şiir','Cenk Aksal']::text[], 8.5, '{"poet":"Cenk Aksal","poet_slug":"cenk-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iste-ben-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Yalnızım', 'ben-yalnizim-hasan-can-fjed8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben yalnızım, kaderim bu benim,

Dünüm yok, bugünüm yok, yarınım olmayacak.

Ben yalnızım, derdim çok benim,

Alıp başımı gitsem ne fayda yalnızlık her yerde.

Ben yalnızım, geceler bile yanımda değil,

Uykularda bile kimse yok yanımda.

Ben yalnızım, sabahlarımı sorma gitsin,

Sabahın güneşi bile yok penceremde.

Ben yalnızlım, sevgi olsa ne değişir,

Yanımda kimse olmadıkça sevmek neye yarar.

Ben yalnızım, bir yağmur damlası bile yok yanaklarımı ıslatan,

Yanaklarımı ıslatmadıktan sonra yağmur neye yarar.

Hani bir rüzgar eser ya saçları dalgalandıran,

Benim saçlarım bile yalnız, rüzgarı olmayan,

Hani insan yaşamak için nefes alır ya boğazdan,

Benim boğazım bile yalnız, nefesi olmayan...', 'Ben yalnızım, kaderim bu benim, Dünüm yok, bugünüm yok, yarınım olmayacak. Ben yalnızım, derdim çok benim, Alıp başımı gitsem ne fayda yalnı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-yalnizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim İçin', 'sen-benim-i-cin-serpil-ozcan-kwss2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen benim için herşeyden önce geliyorsun

