INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Aydede', 've-aydede-kadir-yildiz-6vz4g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 've 

aydede dünyayı izliyor,

tek damla gözyaşı akıyor

insanların üstüne', 've  aydede dünyayı izliyor, tek damla gözyaşı akıyor insanların üstüne...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yıldız']::text[], 8.5, '{"poet":"Kadir Yıldız","poet_slug":"kadir-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ve-aydede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz İnsanlar', 'siz-i-nsanlar-kadir-yildiz-5bns7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'siz insanlar; 

neden kulaklarınız kızarmış,

utanıyormusunuz? 

neden?', 'siz insanlar;  neden kulaklarınız kızarmış, utanıyormusunuz?  neden?...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yıldız']::text[], 8.5, '{"poet":"Kadir Yıldız","poet_slug":"kadir-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/siz-insanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Adı Var', 'umudun-adi-var-kadir-yildiz-7q2fo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'umudun adı var

kim kaybetmişte kim bulmuş

umut etmiş gerçek olmuş

adı umut değil mutluluk olmuş

biri düş kurmuş

umut etmiş

umut uyanık olanın rüyası olmuş

umut edilmiş

umut olmamış

umut,umut olmuş

kimisi umudunu kaybetmiş,kimisi umut bulmuş', 'umudun adı var kim kaybetmişte kim bulmuş umut etmiş gerçek olmuş adı umut değil mutluluk olmuş biri düş kurmuş umut etmiş umut uyanık olanı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yıldız']::text[], 8.5, '{"poet":"Kadir Yıldız","poet_slug":"kadir-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umudun-adi-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Batmayan Vakitlerde', 'gunes-batmayan-vakitlerde-kadir-yildiz-j0rjn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç gitmediğim o dağ köyünde

sabahsız günün akşamında 

güneş batmayan vakitlerde

bakan gözlerin bulamayacağı

o yolun sonunda

beklenen

biliyorum ben değilim

benim yolum değil ela gözlerin beklediği

deli lodosta savrulan saçlarını 

üşüyen bedenini

saracak okşayacak ben değilim

benim değil kış harmanlarında 

hüzünler savuran yüreği 

ve 

benim olmadığı gibi

doğurgan umutlara ağlayan elleri

benim olmayacak sevgisi

yaşanansa kalacak  benle tutsak', 'hiç gitmediğim o dağ köyünde sabahsız günün akşamında  güneş batmayan vakitlerde bakan gözlerin bulamayacağı o yolun sonunda beklenen biliyo...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yıldız']::text[], 8.5, '{"poet":"Kadir Yıldız","poet_slug":"kadir-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gunes-batmayan-vakitlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Allahaşkına! ...', 'don-allahaskina-leyla-isik-k9a6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duygular yıkıldı bir bir 

Terkedip gitti son kuşta 

Hangi gönülde şimdi 

Mutlu mu? 

Kimbilir... 

    Suskunluk vardı son bakışta

      Esen rüzgarla savruldu 

          Kurumuş yapraklar 

            Biten sevginin hüzünlü şarkısını fısıldadı

                Yalnızlık dolu sokaklar 

Geceler sessiz ve soğuk 

Anılar mahzun kaldı 

Düşler umutsuzlukta boğuk 

Sevdayı yaşanmamış kılıp

Yarım kalan bir aşkla 

Anıları gizleyip duvarların ardına 

Rüzgara eş olup 

Sanki 

Bırakıp gidecek ne vardı. 

Hangi düş avutacak şimdi beni 

      Hangi düş süsleyecek gecemi 

         Kiminle paylaşacağım duygularımı

            Ve... nasıl unutacağım seni? 

Yürüsem… 

Bitmeyecek yalnızlığın sokakları

Terketmeyecek beni 

Hüzünlü gölgeler

Bir kadehte bin kahırla tüketeceğim 

Sensiz hasret dolu akşamları

Siyah perdeler çekiyorum 

     Bürünüp yasına 

         Aydınlık sabahları unutup 

             Zamanları tüketiyorum kahırla 

                   Nerdesin…her şeyim? 

Dön,

    Dön  Allahaşkına! ...', 'Duygular yıkıldı bir bir  Terkedip gitti son kuşta  Hangi gönülde şimdi  Mutlu mu?  Kimbilir...      Suskunluk vardı son bakışta       Esen ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/don-allahaskina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Gözümle İnsanları Seyrettim', 'tek-gozumle-i-nsanlari-seyrettim-kadir-yildiz-22as0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tek gözümle insanları seyrettim

onu kapattım diğeriyle baktım,

çıık! ! yine aynı', 'tek gözümle insanları seyrettim onu kapattım diğeriyle baktım, çıık! ! yine aynı...', ARRAY['Türk Edebiyatı','Şiir','Kadir Yıldız']::text[], 8.5, '{"poet":"Kadir Yıldız","poet_slug":"kadir-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tek-gozumle-insanlari-seyrettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haram', 'haram-i-shak-ozlu-hatp6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haram zehirli bala benzer.

Bal sanıp konarsın,

Bir parmak tadarsın,

Damarında yürüyünce zehri,

Yaptıgın hatayı anlarsın.

Haram zehirli bala benzer.

Çeker seni rengine,

Bulaşmak ister sevgine,

Yüregine ulaşınca zehri,

Pişman olsan nafile.

Haram zehirli bala benzer.

Tadına kanıp yersin,

Hayat buymuş dersin,

Beynini sarınca zehri,

Fayda etmez panzehri.', 'Haram zehirli bala benzer. Bal sanıp konarsın, Bir parmak tadarsın, Damarında yürüyünce zehri, Yaptıgın hatayı anlarsın. Haram zehirli bala ...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/haram-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokundun mu sen hiç', 'dokundun-mu-sen-hic-yasar-dogan-qqwmg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tene dokundun mu sen hiç

seyrettin mi ürpertisini

anlaşılmaz iniltisini

çobanpüskülü gibi 

dalda tir tir titreyişini –bir eylülden sonra

güne dokundun mu sen hiç

hipokrit antipatik sistem-matik

ve sempatik görünemeye çalışıp

tonlarca antibiyotik

yutup kuduzluğunu gizleyen güne –öteki günden sonra

öğlene dokundun mu sen hiç

kızılından ve yakıp kavurucusuna

açlıktan midesi kıvrılanına

sokağın ortasında vurulana

vurdun mu sen hiç ellerini

bir gazete sayfası atıp üstüne

herkesin kanının üstünde yürüyenine – ulu orta yerde

dokundun mu sen hiç 

susturulmuş çığlığa

kirlenmemiş suya

keşfedilmemiş ruha

bir yağmur sonrası – atılan çamurlardan sonra

yağdın mı sen hiç

kurumuş dudağa

uzanmış ele

patlamış kalbe

mahvedilmiş bir hayata – bir gece yarısından sonra

baktın mı sen hiç

parçalanmış ve parçalayan

göz bebeklerin heyelanına

düştün mu sen hiç

oların gözleriyle o uçurumlara –bir irkilmeden sonra

nasıl dokunursun bilmem ama

bak 

bir asırlık soğan doğramış yıldızlar

gözlerimin baktığı bütün ufuklara

Yaşar Doğan	/Lolan	/ 05/02/05', 'tene dokundun mu sen hiç seyrettin mi ürpertisini anlaşılmaz iniltisini çobanpüskülü gibi  dalda tir tir titreyişini –bir eylülden sonra gün...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Doğan']::text[], 8.5, '{"poet":"Yaşar Doğan","poet_slug":"yasar-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dokundun-mu-sen-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyis', 'bekleyis-rengin-gardner-lwhht', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekleyis

Bekledim seni gelmedin internete, yine girdim, yine yoksun, 

Kaderin boylesine pes dedim, ask olsun. 

Uyku gozlerimi zorluyor, goz kaparklarim yenik dusuyor, 

Bekliyorum gelmiyorsun, icim hasretinle burkuluyor 

Halbuki bu denli ozlendigini bir bilsen 

Nefes nefese kalirdin halimi bir gorsen 

Biliyorum son zamanlarda cok yogunsun 

Olsun varsin bana ne, beni hic ozlemiyormusun? 

Bu yurek kus herseye, sen yoksan eger 

Seninle her turlu aci cekilmeye deger 

Biliyorum, sende beni seviyorsun, 

Sende benim yollarimi gozluyorsun. 

Ihanet etmeyelim bu duru bu masum bu icten askimiza 

Gormesin gozlerimiz baskalarini, gelmeyelim nazara 

Rengin soyler Rengin yazar askini sevdigine 

Od olur yanar sevdiginin  aski ile', 'Bekleyis Bekledim seni gelmedin internete, yine girdim, yine yoksun,  Kaderin boylesine pes dedim, ask olsun.  Uyku gozlerimi zorluyor, goz ...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bekleyis-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorundayim', 'zorundayim-rengin-gardner-656qq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnizligim, Beni bu denli sevmek zorundamisin demistim,

Yalnizlikmiydi beni cok seven, Yoksa yalnizliga asik  benmiydim

Cevrem  kalabalikta olsa, sarilsamda sevgi yumagiyla

Islemis bir kere yalnizlik icime, gitmezki kovsamda

Alsitimi ne bu urpertici ama bir o kadar cekici duyguya

Kayboluyorum sanki kendi icimde, yalniz kalmayinca

Bilmezdim yalnizligin bu denli guzel oldugunu

Yalnizlikta varolup, kendimi buldugumu

Rengincik

Subat 05 2005   2002 de Yazdigim  Zorundamisin siirine, 3 yil sonraki yanitim', 'Yalnizligim, Beni bu denli sevmek zorundamisin demistim, Yalnizlikmiydi beni cok seven, Yoksa yalnizliga asik  benmiydim Cevrem  kalabalikta...', ARRAY['Türk Edebiyatı','Şiir','Rengin Gardner']::text[], 8.5, '{"poet":"Rengin Gardner","poet_slug":"rengin-gardner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/zorundayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
