INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceydi', 'geceydi-orhan-demirtas-a96rg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'geceydi, 

.....sahipsiz kentlerin yıldızları

............dökülüyordu parmak uçlarımdan

hayallerim gövdeme düşüyordu

..........gövdemdeki çocukların düşleri inciniyordu

özgürlüğüm asılıyordu çıplak bir dala

.............masum, 

.......................mavi bir kız ölüyordu

geceydi,

.....yıldızların ışığından dökülüyordu yalnızlığım

...kırmızı kadar asiydi

....................................su 

...........................................ve 

................................................toprak

ve uçsuz ve bucaksız,

...................................kızıl, 

...........................................ateş

alıp götürüyordu beni çırılçıplak bir yeşil

...............gölgesine düşüyordum

............................henüz tutulmamış bir ayın

geceydi, 

omuzlarında ışığın yükü vardı

............asil kadınların

........................asil erkeklerin

.....................................asil çocukların

ve her ölüm newroz getiriyordu

en güzel çiçekler adına yaşanıyordu ölüm

....görünen en parlak ağaç Mezopotamya uğruna 

              

geceydi, 

bir kahraman iniyordu yorgun düşleriyle dağlardan

.......kalemimden kan damlıyordu içime

.................gözlerim parlıyordu,

............................öpülen bir yanak gibi

 güneşten daha cömert yüzüne bakarken

 dünyanın ormanlarında zarif bir kuş büyüyordu

 .........................gözlerimin bitmeyen yalnızlığına

geceydi, 

ağlıyordu anneler damarlarında gezinen sancıyla

.......................................................Çekilen acılara

göz yaşları bir gül gibi düşüyordu toprağa

ellerimden çürük ağaç kokusu geliyordu

yumruklarım''a kelepçeler vurulmuştu

sesimi tutuyordu oliympos kartalları kanlı pençeleriyle

bir kölenin oğlu değildi düşlerim

adını bir ermiş fısıldamıştı kulağıma

.................gölgem gibi taşıdığım

..................................sevgilim, özgürlüğüm

                                                                     

geceydi, 

yanımda aysız bir kurşun, çiçeksiz hapis

öfkem geceye inen bir balyoz

.........kardeşçe bir düş için, 

...............................yarınlara, 

.........................................yoksul çocuklara

güneşin gölgesinde unutulmuş kalabalıklara

yaşamı adarcasına	

............getirecek sesler 

..........................sert bir bıçak gibi

..........................................ak bir sevda	 

.....................göreceksiniz

geceydi, 

dışımda Temmuz 

..............İçimde tuhaf bir buz kokusu

yalnızım 

......gece karanlık

...............ay ve yıldızlar içimde üşüyor

her yanıma hüzünle açılan bir kapı

omuzlarımda bıçak yarası gözler

benim sessiz, 

......çürük bir elma kurdu gezinirken ruhumda 

geceyi esmer sevişlerim

.........soğuk 

................ve 

...................nemli

kimse bilmez benim bu derdimi

bir senden başka, ey nazlı hürriyet

...... ah ölümsüz sevgili

Orhan DEMİRTAŞ', 'geceydi,  .....sahipsiz kentlerin yıldızları ............dökülüyordu parmak uçlarımdan hayallerim gövdeme düşüyordu ..........gövdemdeki çoc...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/geceydi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüle Nasihat-2-', 'gonule-nasihat-2-i-smail-baharsen-9t25w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir gönlüm var arsızmı arsız

ne yaptığını bimez durumda

aşk yönünden bahtsızmı bahtsız

dilin söylediğini duymaz durumda

ey gönlüm uslan geçiyor hayat

aklına getir duygular bile bayat

uçacaksın kimbilir kanat kanat

sonunu bir türlü görmez durumda

yavaşlanır gün gelir atışın bile

yıllarca aşk için yaşanmaz köle

yaşlanma başladı zamanda bile

acı ama dünya kalmaz durumda

gerçekten uzakken düşersin belki

zalim dünyanın dokunmaz eli

dostun dosttan kaçtığı yeri

bilirde aklı sarmaz durumda', 'bir gönlüm var arsızmı arsız ne yaptığını bimez durumda aşk yönünden bahtsızmı bahtsız dilin söylediğini duymaz durumda ey gönlüm uslan geçi...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonule-nasihat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alvarlı Aşık Reyhani (Devam-38)', 'alvarli-asik-reyhani-devam-38-i-smet-barlioglu-7qh43', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '38*

‘Allah var mı, yok mu? ’ Diyen avara,

Sıtkile ‘Allah’ de, O sana söyler.

Fikrin çok muannit, küfrün bedava,

‘Esteğfurullah’ De, O sana söyler.

O, nurundan alıp güneş doğurur,

Her yıldızı bir semaha çağırır,

Yorgunluk duymadan çarkı çevirir,

‘Amentübillah’ De, O sana söyler.

İşlemez silahı yanına alma,

Ara, bul mürşidini, gir erkanına,

Hele bir adım at İslam Dini ‘ ne,

‘Vallah ve Billah’ De, O sana söyler.

Gözden geçir evliyanın adını,

Gel çiğneme vermiş isen va ‘dini,

Tükenmez zannetme ağız tadını,

‘Sevap ve Günah’ De, O sana söyler.

Sakın ihmal etme; bu yaranı sar,

Emr-i İlahi ‘ye olursun mahzar,

Reyhani der: ‘Dört kitapta bir O var’,

Sen bir ‘Bismillah’ de, O sana söyler.

----------------------------------

38* Ey ‘Allah var mı, yok mu=’ diyen boşadam. Şöyle yürekten bir ‘Allah’ de, O sana var olduğunu söyleyecektir. Düşüncen ne kadar inatçı, yadsıman ne kadar ucuz? Sen bir kerecik ‘Tövbe’ de, gerisini O ‘na bırak. O güneşleri kendi ruhundan yaratır., her bir yıldızı dönüşe çağırır, yorgunluk belirtisi göstermeden evreni çeker çevirir, ‘Herşeyin Allah ‘tan olduğuna inandım.’ De, O sana gerekeni verecektir. İşlemeyen silahlarına güvenme. Bir yolgösteren, bir akılveren bul ve onun gösterdiği, öğütlediği yoldan git. İslam Dini ‘ne yek bir adım at ve Allah adına andiç, O seni yanıtsız bırakmayacaktır. Ermişlerin adlarını ve verdiklerini bir kere gözden geçir, bu yolda herhangi bir söz vermişsen, o sözünü çiğneme. Sağlığın ve mutluluğun sürüp gideceğini sanma.  Sevabın ve günahın ne olduğunu bir araştır, O ‘ndan gereken yanırı gecikmemeksizin alırsın. Yaranın gangren olmamasına onu sararak özen göster, o zaman tanrısal buyruğun altına girmeye hak kazanırsın. Reyhani der ki: Dört kitabın hangisinde O yok? Sen önce bir ‘Allah ‘ın adıyla’ de, gerçeği sana O söyler.

Aşığın bu şiiri türünden olan şiirlere ‘Methiyye ve Zemmiye’ derler. Yani şiir, bir şeyleri veya birilerini hem övmekte, hem de yermektedir. Burada ‘Allah’ ın övülüşü ve bir O ‘na inanmayanın yerilişi mevcuddur. Bu bakımdan şiir, dinle ve tinle yani ruhla ilgilidir. Halk Aşıkları arasında bu tür övgülere ve yergilere çok rastlanmaktadır ve Reyhani de burada öyle davranmıştır.

Şiir 6+5 duraklı 11 ‘lik bir hece şiiridir. Duraklarında atlamalar vardır. Örgüsü öncekiler gibidir.

Sözlük durumu aşağıdadır: ‘Avara (Avare ‘den bozma) -Boşadam, akılsız, işsiz’, ‘Sıtkile-İçten, yürekten’, ‘ Estağfurullah-Özür dileme’, ‘Semah-Dinsel törendeki dönüş, Semah’, ‘Amentübillah-Allah ‘a inanmak, inanç’, ‘Erkan-Yollar, kurallar’, ‘Vallah ve billah-Allah için andiçmek, Yemin etmek’, ‘Evliya-Veliler, Erenler, Ermişler’, ‘Vaad-Verilen söz’, ‘İhmal-Aksatna’, ‘Emr-i İlahi-Tanrı buyruğu’, ‘Bismillah-Allah ‘ın adıyla’.

Aşığın son dörtlükte sözünü ettiği ‘Dört Kitap’ ‘Dört Kutsal ve Göksel Kitap’ tır. Bunlar: Hz. Davud ‘a indirildiğine inanılan ‘Zebur’, Hz. Musa ‘ya indirildiğine inanılan ‘Tevrat’, Hz. İsa ‘ya indirildiğine inanılan ‘İncil’ ve Hz. Muhammed ‘e indirildiğine inanılan ‘Kur ‘an’ dan ibarettir. Öncekilerin gökten sayfalar halinde indirildiğine inanıldığı halde, sonrakinin yani Kur ‘an ‘ın ‘İnzal’ ve ‘Vahiy’ suretiyle indirildiğine inanılmaktadır. ‘İnzal’ kutsal metnin gökten yere indirilmesi ve ‘Vahiy’ Hz. Muhammed ‘in içine, ruhuna söylenmesidir.

(ALVARLI AŞIK REYHANİ isimli Araştırma-İnceleme ''lerinden > 153-155/201) 

(Devam edecek...)', '38* ‘Allah var mı, yok mu? ’ Diyen avara, Sıtkile ‘Allah’ de, O sana söyler. Fikrin çok muannit, küfrün bedava, ‘Esteğfurullah’ De, O sana s...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/alvarli-asik-reyhani-devam-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-erkan-senses-uj2f2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklarda

Çok uzaklarda

Birbirimizi deliler gibi sevebileceğimiz

Dengimiz vardır elbet,

Ama

Nerde oralara gidecek

Para,pasaport,vize...

    28 Aralık 2004  Kocamustafapaşa', 'Uzaklarda Çok uzaklarda Birbirimizi deliler gibi sevebileceğimiz Dengimiz vardır elbet, Ama Nerde oralara gidecek Para,pasaport,vize...     ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Şenses']::text[], 8.5, '{"poet":"Erkan Şenses","poet_slug":"erkan-senses","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arayis-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alvarlı Aşık Reyhani (Devam-37)', 'alvarli-asik-reyhani-devam-37-i-smet-barlioglu-uziyu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '37*

Baksı ‘da bir güzel gördüm,

Nazlı Sultanlar ‘a benzer.

Aslını-neslini sordum,

Dilbilmez lallara benzer.

Ha bir yokmuş, ha bir varmış,

Mevla ‘m övmüş de yaratmış,

Parmak ince, tırnak kamış,

Saçı sırmalara benzer.

Yanağı has bal süzmesi,

Misk ü amber gül nefesi,

Sinesi cennet bahçesi,

Göğüsleri nara benzer.

Mestoldum gül endamından,

Bal damlarken dudağından,

Ter-mer gördüm gerdanından,

Yeni yağmış kara benzer.

Bir gülümser, bir de dinler,

Dışı güler, içi inler,

Ak gerdana çifte benler

Ferman eden dâra benzer.

Ak bilekte sedef halhal,

Gözler ceylan, kaşlar hilal,

Reyhani ‘de kalsa da hal

Yorgun yolculara benzer.

------------------------

37* Reyhani ‘nin hem güzel, hem de açıklama ve yorum gerektirmeyen şiirlerinden biridir. Söyleyiş Karacaoğlan ‘ı andırmaktadır. Niteleme abartılı fakat etkileyicidir. Baskı ‘da gördüğü güzeli, usta bir san ‘atçı gibi fırçasıyla tuvaline işlemiş, renkli ve kokulu bir tablo gibi önümüze koymuştur.

Şiirin sözlüğü şöyledir: ‘Asıl-Soy,sop’, ‘Nesil-Kuşak’, ‘Mevlâ-Yaratıcı’, ‘Sine-Göğüs’, ‘Mestolmak-Kendinden geçmek’, ‘Endam-Boy,bos’, ‘Ferman-Padişah buyruğu’, ‘Dâr-Darağacı, idam sehpası’, ‘Lal-Dilsiz’.

Üçüncü dörtlükteki ‘Misk ü amber’ ‘Misk ve amber’ olarak birlikte kullanılan iki güzel kokudur. ‘Misk’ adı verilen güzel koku keçiden ve amber adı verilen güzel koku da balinadan çıkarılır. Bu nedenle; güzel kokan bir şey için ‘Mis gibi kokuyor.’ Demek yanlıştır. Çünkü; ‘Mis’, sarı bir metal olan pirince denir ve metalin güzel kokma özelliği yoktur. ‘Misk gibi kokuyor.’ Dendiğinde; bu doğrudur. Kendisinden güzel koku çıkarılan keçinin adı da ‘Mis Keçisi’ değil, ‘Misk Keçisi’ dir.

Şiir bir ‘Methiye’ yani ‘Güzelleme’ ve yani ‘Övme’ dir. 4+4 Duraklı bir 8 ‘liktir. Örgüsü öncekiler gibidir.

(ALVARLI AŞIK REYHANİ isimli Araştırma-İnceleme ''lerinden > 151-152/201) 

(Devam edecek...)', '37* Baksı ‘da bir güzel gördüm, Nazlı Sultanlar ‘a benzer. Aslını-neslini sordum, Dilbilmez lallara benzer. Ha bir yokmuş, ha bir varmış, Me...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/alvarli-asik-reyhani-devam-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüle Nasihat-3-', 'gonule-nasihat-3-i-smail-baharsen-safgt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'koptuki can parçası bedenden

ben seni atamadım gönül

herkes şikayetçi kaderinden

bende senden çektim gönül

darbenin darbesi bir kılıç gibi 

parçaladı bağrını şevkine indi

başlar dediklerin zamansız bitti

köle gibi koşturdun gönül

tut sözleri çektirme artık

sende bende hasretten bıktık

geleceğimizin dalları kırık

beynimde sabırı taşırdın gönül

kolay aslında biraz anlasan

dönüpte macerana baksan

belki tüm hayatın korsan

sana inancımı bitirdin gönül', 'koptuki can parçası bedenden ben seni atamadım gönül herkes şikayetçi kaderinden bende senden çektim gönül darbenin darbesi bir kılıç gibi  ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonule-nasihat-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahın hesabı yok yasak şiir.', 'gunahin-hesabi-yok-yasak-siir-ali-riza-unal-yelsa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel gidelim kaçmadan o leyli-i yara

Dar ile narın orta yerine.

Gel buseni vur yerine

Gayrı aşığın günahı hesabı yok..

Terk edersen benliği tükenir dava

Kalırmı cennet sevgisi cehennem korkusu.

Hayadır o zatı zülcêlâl hesap sormaya.

Her azan vuslattır hicabı yok.', 'Gel gidelim kaçmadan o leyli-i yara Dar ile narın orta yerine. Gel buseni vur yerine Gayrı aşığın günahı hesabı yok.. Terk edersen benliği t...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunahin-hesabi-yok-yasak-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgüne İnat', 'surgune-i-nat-esat-korkmaz-1n6rz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnadım tuttu yeniden

Ne sürgünü/ kalmalı insan

Kıyısında bekleyeni olan diyarda

Yönümü buldum artık

Bırak inadı yelkenli

Çevir yüzünü rüzgara

Doldursun atlas brandanı

Taşı beni el sallayan kıyılara 

Bak çiçekler de açmış rengarenk

sevdalı yürek taşıyacağım oraya

binbir kokulara dolayacağım

deste gül diye sunacağım

baharı bekleyen gönüle

daha dün / yönünü bilmeyene

 yardım edemem diye nazlanan rüzgar

yeniden doğan güneşe rotan/ işte

varsın yönelsin gün batımına/ güneş

düş peşine götür beni yeni adresime

Küreğe mahkum etme nolur

                                Bu yaşta

Bak deniz de dönüyor maviliğine

Dalgaları/ dalga geçiyor benimle

Anlaşıldı varken sende bu inat

Son çare çekilecek kürek

Canım kürek al dalgaları ardına

 yardım edeyim sana 

Taşı beni kıyıda çarpan yüreğe

Benim de inadım inat

Gitmeyeceğim bu sürgüne

Bir ömür sürsede küreğe mahkumiyet

Varacağım Mavilikleri seyreden kıyıya', 'İnadım tuttu yeniden Ne sürgünü/ kalmalı insan Kıyısında bekleyeni olan diyarda Yönümü buldum artık Bırak inadı yelkenli Çevir yüzünü rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Esat Korkmaz']::text[], 8.5, '{"poet":"Esat Korkmaz","poet_slug":"esat-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/surgune-inat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıklar Hayal Kurar', 'asiklar-hayal-kurar-i-smail-baharsen-06lpz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşıklar hayal kurar eller ellerde

gözlerin hasreti bitmeden daha

felek acımasız sormadan yıkar

bir mutlu gün görmeden daha

vasat sevdalara yeter  gücün

acısını çok görmezler ölümün

parçasısın sende bu bütünün

herkes sever bilmeden daha

seninde bağın çözülür elbet

ahlar yerde kalmaz sabret

son gününü yaşa günü gün et

sevenler seni yakmadan daha', 'aşıklar hayal kurar eller ellerde gözlerin hasreti bitmeden daha felek acımasız sormadan yıkar bir mutlu gün görmeden daha vasat sevdalara y...', ARRAY['Türk Edebiyatı','Şiir','İsmail Baharşen']::text[], 8.5, '{"poet":"İsmail Baharşen","poet_slug":"i-smail-baharsen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asiklar-hayal-kurar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşkın Anısına', 'bir-askin-anisina-ahmet-aksoy-dj5ss', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çağları deviren bir tutkunluktu 

kenetlenmiş bedenlerimiz

başkalaşıma uğrayan inançlar

kendine dönmeden 

sargın

sonra sonra kırılıyor tılsımlı aynalar

düşler ayrılıyor sevişmelerden

fark bir uçurumdur

gün geçtikçe büyüyen

yazgılarımızı yüzlerimizde gördük

en derin mahremimize kadar

bir gün ölecektik 

ayrı dinleri paylaşan 

nebiler gibi 

büyüttüğümüz aşkımızla', 'çağları deviren bir tutkunluktu  kenetlenmiş bedenlerimiz başkalaşıma uğrayan inançlar kendine dönmeden  sargın sonra sonra kırılıyor tılsım...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-askin-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk; Sözüm Sana', 'mutluluk-sozum-sana-gulay-yildiz-99cnh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırak şu saçma duruşu! 

Yaptığın tek şey nokta vuruşu...

Al hüzünden uzun çizgileri.

Geldiğinle gittiğin bir,

Bitir şu çabuk gidişi...', 'Bırak şu saçma duruşu!  Yaptığın tek şey nokta vuruşu... Al hüzünden uzun çizgileri. Geldiğinle gittiğin bir, Bitir şu çabuk gidişi......', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mutluluk-sozum-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlle de Benini', 'i-lle-de-benini-leyla-isik-2d3yg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oturup penceremin önüne

 süzülen ışıkları seyrederken akmamlarda

 özleminin sarhoşluğuyla

 dolaşırım anılarda.

 sessiz,sakin gönlüme aniden

 bir deniz mevsiminde geldin

 en güzel duyguları yaşatarak

 unuttuğum günlerimi geri verdin.

 seninle renklendi bir kısır döngü yaşamım

 oturup penceremin önüne

 süzülen ışıkları seyrederken akşamlarda

 seni anımsatır ne varsa

 ne yapıyorsun kimbilir bu saatlerde,

 kimbilir...

 senden uzakta düşer kalbime,korkusu yalnızlığın.

 geceye uzayan akşamla 

 çöker içime hüzün

 belirir kararan akşamlarda

 nemli dudakların,

 gözlerin,

 yüzün.

 bedenimi bir ateş sarar

 bir kor nasıl yanarsa

 tenim işte öyle yanar.

 biliyorum,benden uzaktasın.

 bir deli rüzgar eser yalnızlıkların ortasında

 kapansa da kapılar

 örtülse de perdeler

 seninle dolu düşlerim var ya

 sen varsın ya anılarda

 isterse arada olsun kilometreler.

 sen uzaklarda değil,

 bendesin.

 ellerimde,

 gözlerimde

 özleminle yandığım tenimdesin.

 seni düşünürüm kapatıp gözlerimi.

 her parçanı ayrı karelere bölerim.

 ellerim dolaşır teninde

 öperim...

 öperim her kareni.

 ama,

 ille de benini....', 'Oturup penceremin önüne  süzülen ışıkları seyrederken akmamlarda  özleminin sarhoşluğuyla  dolaşırım anılarda.  sessiz,sakin gönlüme aniden ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ille-de-benini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadin,', 'o-kadin-leyla-isik-gpnoa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Meshuruymus o sokagin

 adi muhim degil ''O  Kadin''

 apaydin umutlardan

dusmus

''O Kadin''i'' olmus karanligin.

 sevgi bu,

 ask bu hic belli olmaz.

 kus gibidir

 bakarsin,istedigin yere konmaz

 kimini yuceltir bas taci eder,

 kimini dusurur sokaklara,

''O Kadin''gibi kadin eder.

 dolastirir kucaklardan kucaklara

o guller ki koktukca sehvet sacar,

 o guller ki karanliklarda acar,

 o guller ki sarhos gecelerin,

 sarhos erkeklerin koynunda sabahlar.

 sorunca yasam oykulerini

 ''kader'' der,bir bir siralar.

 basindan gelip-gecenleri...

 ona kaderi ''kader'' edenleri

 belki yalan

 belki gercek.

 hic mi sucu yok? 

 hic mi payi? ....

 istemedi mi o da acep,

 ''O Kadin'' olmayi.

 neyse.......

 bu sokakta daha neler varmis neler...

 dinlerseniz,her dudaktan ayri oykuler

 oykunun sonunda hepsi

 ''Gencler severken dikkat edin''

 derler.', 'Meshuruymus o sokagin  adi muhim degil ''O  Kadin''  apaydin umutlardan dusmus ''O Kadin''i'' olmus karanligin.  sevgi bu,  ask bu hic belli olma...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/o-kadin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiş Olsaydın', 'sevmis-olsaydin-orhan-kartalci-zh5vd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmiş olsaydın,,,

Issız gecenin nöbetini tutarmıydım

Sabahları bu kadar çaresiz bu kadar zor gelirmiydi bana

Seninle dolu hayallerim,umutlarım yarım kalırmıydı hiç

Sevmiş olsaydın,,,

Aşkın sıcaklığı bedenimi üşütürmüydü

Göz göze geldiğimiz her an kilometrelerce uzak olurmuydun bana

Rüyalarım acılarla bölünüp aşkın kabusuna dönüşürmüydü hiç

Sevmiş olsaydın,,,

Yaşamaktan,nefes almaktan korkarmıydım

Dertlere sımsıkı sarılıp, yanlızlığa mahkum olurmuydum

Garip gönlüm aşkın zindanınında çürürmüydü hiç

Sevmiş olsaydın,,,

Mutluluğa hasret yüreğim dinmez bir feryatla, susmaz ağlamakta olurmuydu hiç

Aşkın çaresizliği bedenime yapışmasa gelmeyeçeğini bile bile vuslatın yollarını beklermiydim hiç', 'Sevmiş olsaydın,,, Issız gecenin nöbetini tutarmıydım Sabahları bu kadar çaresiz bu kadar zor gelirmiydi bana Seninle dolu hayallerim,umutla...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kartalcı']::text[], 8.5, '{"poet":"Orhan Kartalcı","poet_slug":"orhan-kartalci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevmis-olsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakır sedası-4-', 'diyarbakir-sedasi-4-mehmet-selim-tolay-u2jf9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlkti bir güzelin kara kirpiklerinde bukadar sendelediğim

anlaşılmaz ruhunda angarya limanlarda beklediğim

her çizgisiyle bana diyarbakırlı olduğunu hatırlatan

ilkti böylesi işveliyi gözlerinden seçtiğim

Zamanın yankısı var benliğe örgülenmiş her daim

neydi sanki aşkıyla mevsim mevsim değiştiğim

gölgeli bir ağacın gölgesiz yerinde beklediğim

bir gülüşü var diyarbakır kokan

bir bakışı var hüzünler saçan...

Ne denir ki ayrılıpta arayıp sormayana

onu görememenin yalaz ateşi var koynumda

her gün saat onikiyi vurduğunda

bir gül açar gözlerimin kara sularında

Bekliyorum ama umutsuzca değil

deli olmuşum aşkıynan vallahi umrumda değil

oda bunun farkında bakışlarım müphem değil

her gizin ardındaki bilinmez bir yol değil

Şimdi beyaz bir rüyayım tertemiz nurlu yollarında

beni saran bu ateşin inleyen sancısında

aşığım diyarbakırlım aşığım ben sana

titriyorum üzerine senin titriyorum anlasana

Gel etme naz benim nazlı bebeğim

ayrılığın karanlık bir gündüz benim için

sen gül ki dağılsın tüm sıkıntılar kır çiçeğim

yollarına daha ne leylaklar ekeceğim

Bekliyorum bekletme gayri gel barışalım

içimizdeki akarsuyu tekrardan akıtalım 

al bu beden senin sarıl ona yarım yarım

yaklaş bana adım adım

benim diyarbakırlım

benim diyarbakırlım

06.01.2005', 'İlkti bir güzelin kara kirpiklerinde bukadar sendelediğim anlaşılmaz ruhunda angarya limanlarda beklediğim her çizgisiyle bana diyarbakırlı ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Tolay']::text[], 8.5, '{"poet":"Mehmet Selim Tolay","poet_slug":"mehmet-selim-tolay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/diyarbakir-sedasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla beni..', 'bagisla-beni-leyla-isik-0w0vg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dört bir yanımda ayna

dört bir yanımda sen

tanıdığım sen...

tanıyamadığım sen.

gizlediğim yüzünle sen...hep sen

ben de yok değildim hani

kah yanında,

kah arkanda

kah önünde,

ama hep var olan yüzümle...

aynalar...lanet olsun! 

bakmak,görmek istemiyorum

geçmişe uzanan upuzun yıllar,

birden kollarını uzatıp beni kıskıvrak kavradılar

ellerimde kelepçeler,

ayaklarımda prangalar.

kendimi savundum.

severken,

sevildiğimi sanarken

mahkum olduğumu haykırdı yüreğimdeki fisıltılar.

Bağışla beni....

benim olan duygularımı,

sorgusuz,savunmasız yargılamamalıydım seni.

yine yalnız kaldım kalabalığın içinde

hava günlük güneşlik

ben üşüyorum.

yüreğimde mevsim kış ya...

hep aynı zamanları yaşıyorum

hep aynı sahne,

hep aynı dekor

ben kaçıncı kez yıkılıyorum? 

hep aynı coşku

ayakta alkışlanıyorum.

perde iniyor yavaş yavaş

oyun bitiyor biliyorum.

rol değil! 

uyanın dostlarım

gerçeği,

inanın gerçeği oynuyorum.

Serüven Kuşu-1996', 'dört bir yanımda ayna dört bir yanımda sen tanıdığım sen... tanıyamadığım sen. gizlediğim yüzünle sen...hep sen ben de yok değildim hani kah...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bagisla-beni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanat', 'sanat-jale-ozler-l0j73', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir yaşamanın felsefesidir

Müzik tabiatın gönlün sesidir

Sanat güzelliğin sevgi anıtı

Sevmek hayranlığın en yücesidir', 'Şiir yaşamanın felsefesidir Müzik tabiatın gönlün sesidir Sanat güzelliğin sevgi anıtı Sevmek hayranlığın en yücesidir...', ARRAY['Türk Edebiyatı','Şiir','Jale Özler']::text[], 8.5, '{"poet":"Jale Özler","poet_slug":"jale-ozler","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanat-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın kalemi - II', 'sevdanin-kalemi-ii-turgut-baki-hb3od', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne zaman şiirden dem vursa biri

o susar

şair değilim derdi 

şairlik zor zanaat

ve ben bilirdim ki

gümüş kağıtlara camdan hecelerle

sevgiyi işlerdi nakış, nakış

sorsalar 

yürek işçisiyim derdi belki

sevgi emekçisi

kim bilir

ne kimse sordu

nede o söyledi

kimse bilmez belki ama

isimsiz nice karalamalarında

ışığa ve sevgiye düşmanlara

kurşun gibi bir kalemdi', 'ne zaman şiirden dem vursa biri o susar şair değilim derdi  şairlik zor zanaat ve ben bilirdim ki gümüş kağıtlara camdan hecelerle sevgiyi i...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdanin-kalemi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yitik zaman hikayeleri - VI', 'yitik-zaman-hikayeleri-vi-turgut-baki-0iggr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece olup ta 

el ayak çekilince

çıkarıp adem giysilerini

hiçliğin hırkasını giyerdi

o ki

harflerin efsununu iyi bilir

billur kağıtların derisine

alemlerden varlığa doğru akan

kelamı nakşederdi

ne rahminde taşımış olan bilirdi bu yönünü

ne yanı başında bulunanlar görürdü

ona bir tek  o gecelerde

gümüş kanatları ile

sevgini nuru eşlik ederdi', 'gece olup ta  el ayak çekilince çıkarıp adem giysilerini hiçliğin hırkasını giyerdi o ki harflerin efsununu iyi bilir billur kağıtların deri...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yitik-zaman-hikayeleri-vi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yitik zaman hikayeleri - VII', 'yitik-zaman-hikayeleri-vii-turgut-baki-8c3f3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kendi benliğinin kuytuluğuna sığınmış bir adam

sövüyor elinde bir şişe şarap

sövüyor geçmişi kınalı dünyanın düzenine

ve gülüyor kendi haline

korkunun yumuşak karnına çöreklenmiş bir ifrit 

ansızın beliriyor gecede 

elinde nardan bir ayna

tutuyor yüzüne adamın

adam şaşkın

adam ürkek

donuyor yüzünde attığı kahkahanın izleri

ayna soruyor adama

kimin içindi verdiğin kavga

anımsıyor adam

faniliği tercihinin nedenini

soruyor ayna

değer miydi

değer miydi nur dan vazgeçip

nar da yanmaya

söyle

unuttuğum uykuyu 

sevdanın kollarında bulurum sanmıştım

diyor adam

oysa aşk benim için iğneli yorganmış

yanılmışım

bunca zaman

vazgeçip nur dan

aşkın narında boşuna yanmışım

derken tüm alem 

o sesle titredi

boşuna mı

boşuna mı

boşuna mı', 'kendi benliğinin kuytuluğuna sığınmış bir adam sövüyor elinde bir şişe şarap sövüyor geçmişi kınalı dünyanın düzenine ve gülüyor kendi halin...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yitik-zaman-hikayeleri-vii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akılalmaz.', 'akilalmaz-aysun-erat-ooc0t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi sen, ne çoksun içimde anlamıyorsun.

Bütün damarlarımda, hızla akıyorsun. 

Milyonlarca hücremde sen.

Hepsinde sen.

Öyle hızlı çoğalıyorsun ki…

Şaşıyorum.

Aklın almaz! 

Aklım almaz! benim de.

Nasıl oluyor da sen,

Bu kadar çoksun bende.

02/2005', 'Şimdi sen, ne çoksun içimde anlamıyorsun. Bütün damarlarımda, hızla akıyorsun.  Milyonlarca hücremde sen. Hepsinde sen. Öyle hızlı çoğalıyor...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/akilalmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllardan Sonra', 'yillardan-sonra-jale-ozler-93qvf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yılların ardından sesleniyorum

Şu gönül sesimi duyuyor musun

Gökkuşağı gibi renklidir ruhum

şarkılarda beni buluyor musun

Bana yüreğini ardına kadar

Açtığın günleri unutur muyum

Solsa da çiçekler, geçse de yıllar

Sevgini vazoda kurutur muyum

Sana kavuştuğum şu mutlu günde

Bırak dertlerimi bir yerde dursun

Geçen bunca yılın iki yönünde

İki başka insan gibi durursun

Mahkum ziyareti gibi dönüşün

Aşka da dönüş mü bilemiyorum

Yıllarca süren şu sükuta düşün

Ağlayamıyorum gülemiyorum

Yediveren gülü gibidir sevgim

Boşa geçen ömre yanıyor musun

Tertemiz yürekle çağrına geldim

Bugünkü halimi tanıyor musun', 'Yılların ardından sesleniyorum Şu gönül sesimi duyuyor musun Gökkuşağı gibi renklidir ruhum şarkılarda beni buluyor musun Bana yüreğini ardı...', ARRAY['Türk Edebiyatı','Şiir','Jale Özler']::text[], 8.5, '{"poet":"Jale Özler","poet_slug":"jale-ozler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yillardan-sonra-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-aysun-erat-y5jw3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gelmeden önce ben,

Öylesine bir hayal içindeydim.

Yaşıyordum hayatı bir böcek gibi.

Sabah olunca, güneş doğardı telaşsız.

Akşam olunca, sezsizce, çeker giderdi.

Nasıl bir gürültüyle girdin sen hayatıma? 

Sağır kulaklarım duyar oldu, bir yaprağın düşüşünü bile.

Hiç de öyle, amaçsızca doğmazmış güneş anladım.

Yaprağın yeşili, denizin mavisi, ateşin kırmızısı varmış.

Danseder dururmuş meğer, kuşlar gökyüzünde.

Rüzgarın bir ıslığı varmış, en sevdiğimden…

Ve ben! 

Ve ben, yaşıyormuşum…

Canım yanarmış benim de.

Anladım…

02/2005', 'Sen gelmeden önce ben, Öylesine bir hayal içindeydim. Yaşıyordum hayatı bir böcek gibi. Sabah olunca, güneş doğardı telaşsız. Akşam olunca, ...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anladim-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alpagut''a Güzelleme, Alpagut''a Ağıt', 'alpagut-a-guzelleme-alpagut-a-agit-mustafa-suna-vdeqz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Mezarlık”ta kayardık çim kayağı

			Geç kalınca yerdik evde dayağı.

			Yollar eder çamur, eli, ayağı.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			Çelik çomak, uzun eşek, imâme,

			“Meyyit Taşı” etrafında, pervâne,

			Çocuk idik, oynar idik, divâne.

			

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

	

			“Çukur Bağ”da görür,görmez, hasılı,

			Hasıl üstü, başlar güreş fasılı.

			Yenen belli, yolda gider, kasılı.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Kıraç”larda yüklediler katırı,

			“İlk Geçit”de kaldırdılar yatırı.

			“Keskin Çayı” nice canlar batırı.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Çaylarımız”, “Kurt Üzüm”e çağlamış.

			Bent tutanlar, tutamayıp, ağlamış.

			Yeri gitmiş, karaları bağlamış.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Kıraç Câmi”, şadırvanı şarıldar.

			Yağmur yağar, sel dibinden harıldar.

			Ramazanda, kandilleri parıldar.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Yaşım on bir, koyun sürdüm, “Yüğ”üne.

			Ateş yaktım, gelin “Oruç bağı”na.

			Çırpı ıslak, dayandım gaz yağına.

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

 “Sündiken Dağı”nda, keklik uçurdum.

			“Çınarlar Başı”nda, tilki kaçırdım.

			“Çalcı Bayır”dan, keçi geçirdim.

  			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Pak “Sakarya”m, “Büklüm”, “Büklüm” akıyor.

			Yazın, kışın “Alpagut”a bakıyor.

			Dinleyene  şakır, şakır, şakıyor

.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Umarlar Bükü”nde,çağlayan  dolap.

			İniler, yalvarır, Çalab da Çalab.

			Aksın “Sakarya”m, bitmesin,yâ Rab.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Akşam oldu, kuzu oğlak meleşti.

			Acı haber, tezden köye ulaştı.

			Anasını kurt yiyenler bekleşti.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Horoz öter, “Çay suyu”nu keserdik.

			“Yirik Gever”ine, fener asardık.

			Su başında, susuz kalıp, susardık.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			“Kavık Mehmet”, “Usta Mehmet” pınarı,

			Yosun tutmuş, olukların kenarı.

			Yaralandık, bizi, kimler onar? 

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

                                    At dehledim, seher vakti, kübüre.

			“Ardıçlar”da, sırtı köpür, köpüre.

			Erken varan, yakın “ağıl” süpüre.		

			 			

			

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			

“Tarpak Çayı”, son durağı,”Dâr-ı Pak”.

			“Erecören” tarlaları, pek kaypak.

			“Isbâ Dedem”, domuz bekler, şen şakrak.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Kiraz yedim, “Kirazların Doruk”ta.

			“Pınar Başı Suyu” akar, arıkta.

			Yaz ortası gitmez olur, karıkta.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Güneş doğar, “Öküz Ören Bağı”na.

			“Kara Tepe” hemen düşer, sağına.

			Dönebilsem, yine gençlik çağına

			

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Kızıl Tepe”, yolu “Tont”a taşırmış.

			Çaktırmadan, kızıl meşe aşırmış.

			Ormancılar bakıp kalmış, şaşırmış.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtiğim, bağ pınarlarım.

			“Çatal Tarla”m, çatalından ot biçtim.

			“Erik Pınarı”ndan, soğuk su içtim.

			“Eşme Yanı” yokuşundan zor geçtim.

			

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Bol Pınar”da, koyun, kuzu meleşir.

			“Mahal”ında, tosun, düvey eyleşir.

			Çayırında, koç yiğitler küleşir.

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Alpagut”la “Avlamış”ın arası.

			Şükür, bitti, yörük-manav yarası.

			Yeni kuşak, sözle bulur çaresi.

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Adalar”ın,inciriyle, ayvası.

			“Yatan Aslan”, “Şahin Gözlü” kayası.

			Bir de çoban, kavalı tutar yası.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Kum Dere”nin tatlı olur üzümü.

			“Katırcılar” gamlandı, bağ bozumu.

			Dedi: “Bağbân, dinlemiyor sözümü”

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			“Kavşık Kaya”, “Kazan Kaya”, “Ar Kaya”.

			“Ivacın”a geçen yolun, dar kaya.

			Bağlarında üzüm var mı, sor kaya.

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			“Erenler Tepesi”, “Erenler” nerde? 

			Taşların yok olmuş, soranlar nerde? 

			Bayramda, seyranda, varanlar nerde? 

.

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			“Sekiler”de bayam yedim, baharda.

			Nar ağacı don mu yemiş, kaharda.

			“Çukur Harman” çukur kalmış, pek darda.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Seki Harman”, harman olmuş, “bükler”e.

			Dik yokuşu bel ağdırır, yüklere.

			Kalp kazınır, çetlemek kütüklere.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Dumanlandı “Arkaya”nın tepesi.

			“Dere Mahalleli, bekler sel sesi.

			Sele gitmiş, yanar, ciğerpâresi.

		            Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Dedeleri” gözetliyor, “Köpürcek; 

Korkar mı ki; yaban, kapıp; götürcek..

“Teknekaya” teknesini göçürcek.

			

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Hayranı da deli gönül hayranı.

			Bayram gelir, seyrederler seyranı.

			“Salaklar Bayır”da dürdük devranı.

			 Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Allar giymiş “Sâlehlerin Bayırı”.

			Kızlar selamlıklı, dostlar ayırı.

			Bayram biter, yavuklular kayırı.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			Gelin kınalandı, yası tutuldu.

			Ana yaslı, sungu tası tutuldu.

			Binsin diye, atın hası tutuldu.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Akşam olur, gün kayaya değerdi.

			Sırtta bohça, bacım belin eğerdi.

			Yaş otuzda, gören elli sayardı.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

Ecel geldi, dede gitti, sıradan.

			At, eşekler, çekildiler aradan.

			“Taral”ları lûtfeylemiş Yaradan.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Taral”ların römorkları köşeli.

			Bohçası yok, hanım sağda, neşeli.

			Çile bitmiş, nasır gitmiş, hoş eli.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

“Köy Yeri”nden, “Köy”e baktım, kırkında.

			Yıllar geçmiş, olmamışız farkında.

			Kokladığım gülü solmuş, “Park”ında.

			Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

			“Dallı Mustafa”yım, sözüm dallandı.

			Dala daldım, ak gözlerim allandı.

			Adresi yok, adreslere yollandı.

Bağlarım, bağlarım, “Dağ Pınarlar”ım.

			Kana, kana içtim; bağ pınarlarım.

(SARICAKAYA - 04.01.2004)        

			

(Not: tırnak içinde olan bölümler, yer ve mevkî isimleridir)     

   MUSTAFA SUNA (DALLI MUSTAFA-ORTA SAKARYA  VADİSİ HALK ŞAİRİ)', '“Mezarlık”ta kayardık çim kayağı 			Geç kalınca yerdik evde dayağı. 			Yollar eder çamur, eli, ayağı. 			Bağlarım, bağlarım, “Dağ Pınarlar”ı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":192,"source_url":"https://www.antoloji.com/alpagut-a-guzelleme-alpagut-a-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak', 'yasamak-leyla-isik-vc0at', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkuyla büyümek mi yaşamak 

korkunun içinde. 

hapsedip özgürlüğü gözbebeklerinde 

susturup yureğinin sesini 

sızısını duyup iliklerinde. 

yaşamak buysa eğer 

korkuyu büyütmekse, 

aydınlık fikirlere 

zincirler vurup en ağırından 

küfletmekse, 

duyulmaz çığlıklar atmaksa 

duyamadığımız 

görünmez karşı koyuşlar 

ve o, 

korkunç suskunluklarsa, 

o zaman yaşadım deme. 

yaşamak olamaz 

amaçsız  soluk alıp vermeler. 

yaşamak, 

               duyumsamaktır, 

                   üretmektir 

        yaşamak yenilenmektir 

yaşamak 

Oz-gür-lük-tür düşüncelerde...', 'Korkuyla büyümek mi yaşamak  korkunun içinde.  hapsedip özgürlüğü gözbebeklerinde  susturup yureğinin sesini  sızısını duyup iliklerinde.  y...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasamak-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatır, Kınalı Ellerin Ellerin Beni', 'aglatir-kinali-ellerin-ellerin-beni-mustafa-suna-02nla', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşümde görmüşüm, zülfün çözerler.

	Kız, kızân toplanmış, çeyzin yazarlar.

	Sürmeli gözlere, sürme çizerler.

	İniler, çağırır, illerin beni.

	Âh, köye vardım, varmaz olaydım.

	Yar, kara haberin almaz olaydım.

	Şu pınar başına gelmez olaydım.

	Şakırken yakıyor, dillerin beni.

	Karadır kaşların, kemana benzer.

	Deli etti beni, yamâna benzer.

	İçimde dağ olmuş, gümâna benzer.

	Aklımı zây etti, güllerin beni.

	Dallı Mustafa’yım gurbet elinde.

	Bir güzel sevmişim, halkın dilinde.

	Kurban bayramına, köye gelende.

	Ağlatır, kınalı ellerin beni.

MUSTAFA SUNA (DALLI MUSTAFA-ORTA SAKARYA  VADİSİ HALK ŞAİRİ) 

                  (ERZURUM? ? ?)', 'Düşümde görmüşüm, zülfün çözerler. 	Kız, kızân toplanmış, çeyzin yazarlar. 	Sürmeli gözlere, sürme çizerler. 	İniler, çağırır, illerin beni....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglatir-kinali-ellerin-ellerin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümitsizliğin Sonsuzluğuna', 'umitsizligin-sonsuzluguna-cemal-anbar-5gi7t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Volkan olup çağlasam mı k ibilmem.

Gazel olup düşsem mi gönül bağına? 

Kara toprak gibi içime mi çeksem ölümü? 

Kara yaslar mı bağlasam bilmem.

Bulutlar gibi gürlesem mi bilmem.

Kime anlatsam bu ahvalimi? 

Dost bulunur mu dinleyen bu halimi? 

Ben nerelere gitsem bilmem.

(12,01,2005 Samsun)', 'Volkan olup çağlasam mı k ibilmem. Gazel olup düşsem mi gönül bağına?  Kara toprak gibi içime mi çeksem ölümü?  Kara yaslar mı bağlasam bilm...', ARRAY['Türk Edebiyatı','Şiir','Cemal Anbar']::text[], 8.5, '{"poet":"Cemal Anbar","poet_slug":"cemal-anbar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umitsizligin-sonsuzluguna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan çağrısı', 'vatan-cagrisi-sair-ahrazi-cd55d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı tüm kalbinle dinle,sev yine, 

Hellen ol,germen veyâ bir İngiliz; 

Târihin göz nûru kim,rüyâsı ne? 

Biz ki târihten ziyâde milletiz. 

Hak bilen yurduyla bin defâ güzel, 

Bin defâ şendir bu tekbîrin sesi. 

Servetin kalsın da bir selâmla gel, 

Son nefes vaktiyle görse de seni. 

-

-

-

-

* * *', 'Aşkı tüm kalbinle dinle,sev yine,  Hellen ol,germen veyâ bir İngiliz;  Târihin göz nûru kim,rüyâsı ne?  Biz ki târihten ziyâde milletiz.  Ha...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vatan-cagrisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bürmeli', 'burmeli-mustafa-suna-7rmg6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürür, yürür, selvi boylum, aslına.

Yolda gördüm, gider sulak faslına.

Kendinde yok, bâri versin nesline.

Vefâ nedir, bilmez gözün sürmeli.

Yazam dedim, faslı bahar, yaz iken.

Budur hâlim, yirmiden de az iken.

Vefâsız ben, elde gördüm güz iken.

Eski yaprak zamanı mı, dürmeli? 

Elden ele dolaşan bir gül gibi.

Benzin solmuş, hasta mısın zül gibi? 

Durdu dilim, söyleyemem bül gibi.

Âdem oğlu arar durur, bürmeli.

MUSTAFA SUNA (DALLI MUSTAFA-ORTA SAKARYA  VADİSİ HALK ŞAİRİ)', 'Yürür, yürür, selvi boylum, aslına. Yolda gördüm, gider sulak faslına. Kendinde yok, bâri versin nesline. Vefâ nedir, bilmez gözün sürmeli. ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/burmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşm i Siyâh', 'cesm-i-siy-h-mustafa-suna-ez4lv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çeşm-i Siyâh, çeşm-i siyâh, yakma! Dur! 

Gönül ister, dîl-i sohbet, ne gezer.

Âb-ı hayât olmuşsun sen, akma! Dur! 

Akşam olur, paslı yürek hem bezer.

Giriş oldu, “Bâğ-ı İrem” sahnına.

Görem ne hâl, var mı elde, al kına? 

Dizim bağım, çözül dur da talkına.

Çeşm-i Siyâh, ince, ince yaş süzer.

Canım içi, diri gömdüm toprağa

Sefer ilen, nice, nice ırağa.

Tercümânım şu küçücük varağa.

Kalem ucu “Âdemoğlu” ol! Çizer.

MUSTAFA SUNA (DALLI MUSTAFA-ORTA SAKARYA  VADİSİ HALK ŞAİRİ)', 'Çeşm-i Siyâh, çeşm-i siyâh, yakma! Dur!  Gönül ister, dîl-i sohbet, ne gezer. Âb-ı hayât olmuşsun sen, akma! Dur!  Akşam olur, paslı yürek h...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cesm-i-siyah-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldür Beni Soldur Beni! Demedim...', 'oldur-beni-soldur-beni-demedim-mustafa-suna-rm0mw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '.

		

Demedim ben, “öldür beni”, demedim.

Gül idim ben, “soldur beni”, demedim.

İçin, için yanarsın sen, ôd güllü.

Cân için, âh, “güldür beni! ” demedim.

Ben, benim, Mâh; beni, benden ayırma! 

Yolda gördüm, gül cemâlin, kayırma! 

Birkaç günlük rüyâ imiş, seyirme! 

“Seyrin ile doldur beni “, demedim.

Ardım sıra, bakma gözüm! Yakarsın.

Yakarsın da, cânım içre akarsın.

Iraktan mı hasretini takarsın? 

“Tut elimden, kaldır beni! ” Demedim.

DALLI MUSTAFA', '. 		 Demedim ben, “öldür beni”, demedim. Gül idim ben, “soldur beni”, demedim. İçin, için yanarsın sen, ôd güllü. Cân için, âh, “güldür beni...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oldur-beni-soldur-beni-demedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fındığın Dilinden', 'findigin-dilinden-mustafa-suna-oek1e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dolaştım Ordu’nun Fatsa Elini; 

	Fındığı dalında sararıp, solmuş..

	Ünye’nin duvaklı, telli gelini,

	“Kıtaldı” diyorlar;  evvelce bolmuş..

	Fındık dalda, toplayanı az imiş.

	Yüzler gülmez; ne acılı yaz imiş..

	Oğlan yaslı, kızın işi naz imiş...

	Söz keseli bilinmez kaç yıl olmuş...

	Düşmeyince yere fındık yaprağı; 

	Kim neylesin evde höllük toprağı...

	Höllük eler, anaların uğrağı,

	İzleri silinmiş, geçilmez yolmuş..

	Fındığı kökünden kökleyen eller..! 

	Tuttuğu toprağı savurdu yeller,

	Sürüdü, denize götürdü seller..

	İntizâr dileği Rahmân’ı bulmuş...

	

	Fındık ah etti; duymadı beyler:

	“Ocağım dağıtma! Yıl, yılı eyler..

	Duymazsan ahımı; gör Mevlâm neyler”

	Hıçkırık genizde, gözleri dolmuş..! ! 

	Fındığın dilinden anladı kalem..

	Dallı Mustafa’yla bölüştü elem..

	Yolların gözletme, halvete gelem..

	Arz edin dostlara; halimiz n’olmuş...

 (SARICAKAYA -23.09.2004)     

DALLI MUSTAFA', 'Dolaştım Ordu’nun Fatsa Elini;  	Fındığı dalında sararıp, solmuş.. 	Ünye’nin duvaklı, telli gelini, 	“Kıtaldı” diyorlar;  evvelce bolmuş.. 	...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/findigin-dilinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet Kuşu', 'gurbet-kusu-mustafa-suna-n0m1r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canım felek, sana nettim, neyledim.

Attın gurbet ele, pârelerimi. (Anonim)        

Kahreyledin, beni sılamdan ettin.(Anonim)        

Yâr ola, bağlaya yârelerimi. (Anonim)        

Gurbet Kuşu oldum, gezdim, dolaştım.

Kızıl Dağ’dan, Erzurum’a ulaştım.

Âh, âh, edip, yüreğimle dalaştım.

Yâre söylen, çözsün zârelerimi.

Yedi yıldır, diyâr, diyâr gezerim.

Mustafa’yım, bâzı, bâzı yazarım.

Gözüm yaşı, İnce, İnce süzerim.

Yâre söylen, görsün kârelerimi..', 'Canım felek, sana nettim, neyledim. Attın gurbet ele, pârelerimi. (Anonim)         Kahreyledin, beni sılamdan ettin.(Anonim)         Yâr ola...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-kusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O=Ben', 'o-ben-deniz-onderoglu-e98av', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne varsa istediğin

Hepsini verdim

Kalbimi, sevgimi

Duygularımın tek sahibiydin

Ben ben değildim artık

Bende benden çok

Sen vardın...', 'Ne varsa istediğin Hepsini verdim Kalbimi, sevgimi Duygularımın tek sahibiydin Ben ben değildim artık Bende benden çok Sen vardın......', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar', 'kar-deniz-onderoglu-imjge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar yağıyor dışarıda

İçime yağdı yavaşça

Doldurdu, dondurdu kalbimi

Ne kadar sıcaklık lazım bilmem

İçimdeki buzları eritmeye', 'Kar yağıyor dışarıda İçime yağdı yavaşça Doldurdu, dondurdu kalbimi Ne kadar sıcaklık lazım bilmem İçimdeki buzları eritmeye...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kar-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbette Hayalim; Yaktı Da, Geçti', 'gurbette-hayalim-yakti-da-gecti-mustafa-suna-qyi0h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elâ gözlerini, sevdiğim dilber.

Gurbette hayâlim, yaktı da geçti.

Ayrılık sancısı, gönül yarası,

Derindên, derine, aktı da geçti.

Yazmadın güzelim, kalemin mi yok? 

Göz yaşı dökecek elemin mi yok? 

Kurbân olduğuma dilemin mi yok? 

İntizâr dileğim, taktı da geçti.

Nisân, mayıs, bahar ayı, gel olur.

Bakar gözüm, nemnâk olur, sel olur.

Bâd-ı sabâ, sîne çarpar, yel olur.

Hasret ateşini çaktı da geçti.

Kadir Mevlâm, sen Abdal’ın görün mü? 

Nazar eylen, hem dileğim bürün mü? 

Gönlüm kırık, huzûrundan sürün mü? 

Gönül, “Gül- Cemâl”e, baktı da geçti.

DALLI MUSTAFA

   

     

            

		

	              Erzurum', 'Elâ gözlerini, sevdiğim dilber. Gurbette hayâlim, yaktı da geçti. Ayrılık sancısı, gönül yarası, Derindên, derine, aktı da geçti. Yazmadın g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gurbette-hayalim-yakti-da-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-deniz-onderoglu-ke12a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayat; 

Planlarımızı bozmak için

Tanrının yaptığı bir plandı

Hayat; 

Kararlarımızı yargılar

Ve bizi mahkum eder

Savunma hakkı

Tanımaz bize', 'Hayat;  Planlarımızı bozmak için Tanrının yaptığı bir plandı Hayat;  Kararlarımızı yargılar Ve bizi mahkum eder Savunma hakkı Tanımaz bize...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Övdüm Hayalimden...', 'guzel-ovdum-hayalimden-mustafa-suna-hf1d8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kömür gözlü nârin dilber,

Dönme öyle Güne karşı! 

Gün karartır beyaz teni,

Göz kararır tene karşı.

			Kaşı kalem; kirpik siyâh; 

			Gönlüm deldi; çektirdi âh! 

			Uyku tutmaz; olur sabâh; 

			Kan kaynamış, kana karşı..

Şalvarını ağı yerde..

Yaktı beni; düştüm derde..

Gözlerime indi perde; 

Can kaynamış; cana karşı..

			Gören yaşın on beş sanır.

			Yıllar yılı, her kes tanır,

			Aşıkları nâmın anır; 

			An kaynamış; ana karşı..

Yazı yazdım; acı bitti; 

Kalemimin ucu bitti! ! 

Yol gözleyen Bacı bitti; 

Ağıt söyler tan´a karşı...

			Güzel övdüm hayâlimden; 

			Gönlüm geçmez; helâlimden...

			“Dallı Mustafa” hâlimden; 

			“Memnûnum” der; Sana karşı..

 (SARICAKAYA 09-06-2004)    DALLI MUSTAFA', 'Kömür gözlü nârin dilber, Dönme öyle Güne karşı!  Gün karartır beyaz teni, Göz kararır tene karşı. 			Kaşı kalem; kirpik siyâh;  			Gönlüm d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guzel-ovdum-hayalimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-deniz-onderoglu-dpqsf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşadık, yaşamak denirse

Kısacık ömrümüze

Büyük ayrılıklar sığdırdık

Her ayrılık değilmidir zaten

Bir diğerinin başlangıcı

Başlangıcı olmayan

Hayatlar yaşadık', 'Yaşadık, yaşamak denirse Kısacık ömrümüze Büyük ayrılıklar sığdırdık Her ayrılık değilmidir zaten Bir diğerinin başlangıcı Başlangıcı olmaya...', ARRAY['Türk Edebiyatı','Şiir','Deniz Önderoğlu']::text[], 8.5, '{"poet":"Deniz Önderoğlu","poet_slug":"deniz-onderoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasam-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazala Ağıt', 'hazala-agit-mustafa-suna-ha0b2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dam başında saksağan lo... Vur beline kazmayi...

Köy kızları takayi lo...   burunlara hızmayi...

Dam başında gezerim lo... Fındık, fıstık ezerim.

Güzellerin içinde lo... Hazalımı sezerim.

Dam başında kumrular lo...  Hazalımı vurdular.

Gençliğine doyamadan,   Hazalıma kıydılar.

Dam başında kara toprak, Hazal şimdi çok ırak.

Kara toprak üzerinde,  gelin canlar oturak.

DALLI MUSTAFA', 'Dam başında saksağan lo... Vur beline kazmayi... Köy kızları takayi lo...   burunlara hızmayi... Dam başında gezerim lo... Fındık, fıstık ez...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hazala-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüma Kuşu', 'huma-kusu-mustafa-suna-xqk1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüma Kuşu, Hüma Kuşu; 

	Yükseklerden sesin geldi.

	Sesine ses vere durdum; 

	Nefese, nefesin geldi..

	Küçük iken doymuşum ben,

	Kulağıma koymuşum ben,

	Emmâremi soymuşum ben,

	Sırlarım veresin geldi..

	Dostlar meclisine vardım,

	Avaz istediler verdim,

	İsminin sırrına erdim; 

	Kalemime esin geldi..

	İstediler “Hüma Kuşu.”

	Dinleyenin akar yaşı.

	Yumuşatır en sert taşı; 

	Gözesi; herkesin geldi.

	Asıldım uzun havayı; 

	Ağlattı Güneşi, Ayı.

	Ol Muhammet Mustafa’yı; 

	Gözlerde göresin geldi...

	

	Uslanmaz gönül uslanır; 

	Sesin telinden beslenir; 

	Hem yaslanır; hem yaslanır..! 

	Vuslatı, ertesin geldi..

	Dallı Mustafa; Söylerim:

	Gideni, yoldan eylerim..

	Yarân istemiş; neylerim..

	“Hüma Kuşu” kesin geldi! ..

                (28.06.2004-    SARICAKAYA    )

DALLI MUSTAFA', 'Hüma Kuşu, Hüma Kuşu;  	Yükseklerden sesin geldi. 	Sesine ses vere durdum;  	Nefese, nefesin geldi.. 	Küçük iken doymuşum ben, 	Kulağıma koy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/huma-kusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Kıyısnda Oturur', 'gecenin-kiyisnda-oturur-kamil-aydemir-z0m2k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'haksızlık etme kendine

bahar oldun bu şairin sevgisine

kaç yürek böylesi sevgi büyütür

içimdeki çocuğun elinden tut

içindeki çocuğa götür

yanaklarındaki yaşları kurutur

sevdam yalnızlığını da öğütür

kar gibi beyaz ve soğuk

yokluğun yağarken içime

dokunamam yüzü ölüme dönük yüreğime

beni sevmesende

hiç olmasa sevilmedim deme

nice kadın var

sevilmeden bir ömür tüketen

hak etmediği halde onca yıl verilir

bazen yanlış insan(lar)    da sevilir

keşke bu kadar kirlenmeseydi insanlar

şimdi parayla vuruluyor aşklar da

savaşlarda en çok çocuklar yanar

sözcükler de kırılır heceler kanar

şehriler de yorulur

saçaklarında kuş yuvası evelerde unutulur

unutulur kalbimin çiçeği

yürekde iz bırakmayan anılar da unutulur

sanmaki her yol insanı mutluluğa götürür

ayak altında çırpınıyor onur

insan korkuları(nı)     yendikçe

karanlıkları(nı)     aydınlattıkça

acılardan kurtulur

sana sevda türküleri söylerim

gecenin kıyısına oturur', 'haksızlık etme kendine bahar oldun bu şairin sevgisine kaç yürek böylesi sevgi büyütür içimdeki çocuğun elinden tut içindeki çocuğa götür ya...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gecenin-kiyisnda-oturur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Yıllar Yüreğime Dert Oldu..', 'eski-yillar-yuregime-dert-oldu-mustafa-suna-y03cg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elleri koynunda kınalı kuzum.

Acep seni sorsam, haber var mola! 

Gelir, gider, yâd ellere yanarım.

Şu gördüğüm sıra dağlar, yâr mola! 

On beş yaşta, deremedim gülümü.

On yedide, çok sevmiştim ölümü.

Yirmi birde, koç yiğitler ölü mü? 

Bizim eller artık bize dar mola! 

Gül yüzünde gamze açmış, gül gibi.

Dönmez gözüm, kor gönlüme, zül gibi.

Hayâlimde sis misâli, tül gibi.

Yüce dağlar, sisin ardı kar mola! 

Eski yıllar yüreğime dert oldu.

Kara sevdam derdimden de sert oldu.

Yıllar yılı, gözleyenim dört oldu.

Gidemiyom, beşincisi zâr mola! 

Âdem oğlu koymuşum ben, adımı.

Mustafa’yım, garîp bilir, yâdımı.

Aşk şerbeti, bî- hôş olur, tadımı.

Tatmasan da, yolun sonu kâr mola! DALLI MUSTAFA', 'Elleri koynunda kınalı kuzum. Acep seni sorsam, haber var mola!  Gelir, gider, yâd ellere yanarım. Şu gördüğüm sıra dağlar, yâr mola!  On be...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eski-yillar-yuregime-dert-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömerime', 'omerime-mahir-celik-zs7cz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanina su koysak zehir olur kursagimizda

alipta basini gitmek istersin bu ayazda 

ayak yalin dostluk yalin 

parmaklar neysede ya dostluk usurse', 'Yanina su koysak zehir olur kursagimizda alipta basini gitmek istersin bu ayazda  ayak yalin dostluk yalin  parmaklar neysede ya dostluk usu...', ARRAY['Türk Edebiyatı','Şiir','Mahir Celik']::text[], 8.5, '{"poet":"Mahir Celik","poet_slug":"mahir-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/omerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leylâ''ya Bak Görürsün Sen Mevlayı..', 'leyl-ya-bak-gorursun-sen-mevlayi-mustafa-suna-oppm8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Leylâ’ya bak! Görürsün sen, Mevlâ’yı.

Mevlâ güzel, güzel etmiş Leylâ’yı.

Güzel uğrun, nice türlü belâyı,

Çekersin de, kale göğsün kurur mu? 

Halkı sevdim. Sevdim de Hâkk’ı sevdim.

Pâkı arar göz idim, “Pâk”ı sevdim.

Yâne, yâne gezerken câkı sevdim.

Seversin de, seven gönül durur mu? 

Gönül gitmek ister, hâlin göreyim.

Câk, câk olmuş bağrı, önün sereyim.

Cânım ister isen, cânım vereyim.

Verirsin de, vuran yürek, vurur mu? 

Benî âdem, niçin söyler durursun.

Kastın Mevlâ ise, elbet bulursun.

Ham imişsin, Mevlâ ile olursun.

Olursun da, işin sonu sürûr mu? 

DALLI MUSTAFA', 'Leylâ’ya bak! Görürsün sen, Mevlâ’yı. Mevlâ güzel, güzel etmiş Leylâ’yı. Güzel uğrun, nice türlü belâyı, Çekersin de, kale göğsün kurur mu? ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/leyla-ya-bak-gorursun-sen-mevlayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nâre Düştü', 'n-re-dustu-mustafa-suna-ipuyd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nâre düştü, nâre düştü.

	Yüreğime yâre düştü.

	Bilemedim, yâr kandedir? 

	Dilim sustu, dâre düştü.

			Nâr içinde, nûr´u gören,

			Hâr içinde, Hûr´u gören,

			Pâk “Beyt-i Ma´mûr “u gören,

			Gönül göze kâre düştü.

	“Hakk”, kapısın çalmayınca,

	“Gül” kokusun almayınca,

	Gönül sıla, bulmayınca,

	Hicâb duydu, âre düştü.

			“Nasûh Tevbe”, etsin diye,

			Gurbet cevri, bitsin diye,

			Bu ayrılık, yetsin diye,

			Gönül, intizâre düştü.

	“Dallı Mustafa”yım, hâlım; 

	Kalem yazdı, dilsiz, lâlım.

	Tutunmaya yoktur dâlım.

	Gönül yaşım, pâre düştü.

             (SARICAKAYA    -16.02.2004)

DALLI MUSTAFA', 'Nâre düştü, nâre düştü. 	Yüreğime yâre düştü. 	Bilemedim, yâr kandedir?  	Dilim sustu, dâre düştü. 			Nâr içinde, nûr´u gören, 			Hâr içinde...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Suna']::text[], 8.5, '{"poet":"Mustafa Suna","poet_slug":"mustafa-suna","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nare-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlılarız Biz', 'yaslilariz-biz-ahmet-mansuroglu-tpjve', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizde sizler gibi doğduk büyüdük

Önce emekledik sonra yürüdük

Yıllar gençliğimizi götürdü şimdi çürüdük

Acıma değil, sevgi bekliyoruz...

Kimimiz hakimdik, kimimiz savcı

Dostlarımız vardı, hepsi kardeş bacı

Şimdi unutulmuş olmak çok acı

Bizi unutmayın diyenlerdeniz biz...

Dostlarımız bizi aramaz oldu

Tükendi bir ömür, rengimiz soldu

Hava karardı, vakit akşam oldu

Bir tatlı söze hasretiz biz...

Gün oldu cephelerde savaştık

Allah Allah diyerek dağları aştık

Şimdi unutulduğumuza şaştık

Masallardaki, bir varmış bir yokmuşuz biz...

Bir çoğumuzun oğlu, kızı var

Yaşladık şimdi kim arar kim sorar

Nafile üzülmek, ağlamak sabaha kadar

Gözlerimiz yollarda bekliyoruz biz...

Çocuktuk, gençtik yaşlandık

Bizi arayıp sorarsınız sandık

Terk edilmişliğin ateşine yandık

Bizi unutmayın diyenlerdeniz biz...

Antkya-Hatay', 'Bizde sizler gibi doğduk büyüdük Önce emekledik sonra yürüdük Yıllar gençliğimizi götürdü şimdi çürüdük Acıma değil, sevgi bekliyoruz... Kim...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Mansuroğlu']::text[], 8.5, '{"poet":"Ahmet Mansuroğlu","poet_slug":"ahmet-mansuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yaslilariz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün zamanı', 'huzun-zamani-mustafa-sozlu-z3auj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüzün zamanı! Büyülenen gözler,

Onun veda güzelliği

		Hoşuma gider.

Seviyorum solgun zenginliğini 

				Tabiatın

Kıpkırmızı ve altın renginde 

		Giyinmiş ormanın.

	                                            A.S.Puşkin

(Rusça) Mustafa SÖZLÜ', 'Hüzün zamanı! Büyülenen gözler, Onun veda güzelliği 		Hoşuma gider. Seviyorum solgun zenginliğini  				Tabiatın Kıpkırmızı ve altın renginde...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/huzun-zamani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım acıyor', 'canim-aciyor-mustafa-sozlu-pm4q8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım acıyor,

Ancak sözde hüzün yok.

Acı söz var

Ki o yürekten söylenmiştir.

Yok samimi gözyaşlarından,

Utanacak bir şey.

Gözlerinden düşen,

Soğuk gözyaşlarını buz kessin.

Elmasın bile uzunca beklemesi gerek,

Olmak için kalp gibi böyle sert.

                                                                              L.Ozerof

(Rusça) Mustafa SÖZLÜ', 'Canım acıyor, Ancak sözde hüzün yok. Acı söz var Ki o yürekten söylenmiştir. Yok samimi gözyaşlarından, Utanacak bir şey. Gözlerinden düşen,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/canim-aciyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusurlu', 'kusurlu-hakan-ak-n1s1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şimdi sen...

yine karışmaklısındır

kusurluyumdur bende

yine olamamaklıyımdır

her bir şeyi 

her bir şeylerimi

her şeylerin hepsini de...

biliyorum anlamaklıklısızdır

sev beni...

sevebilmeklisiz

tut beni...

bırakılmamaksızlı

yada boş ver 

hani herbirşeylerli

anla,anla,anla...

düşünememeksizli.', 'şimdi sen... yine karışmaklısındır kusurluyumdur bende yine olamamaklıyımdır her bir şeyi  her bir şeylerimi her şeylerin hepsini de... bili...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ak']::text[], 8.5, '{"poet":"Hakan Ak","poet_slug":"hakan-ak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kusurlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk olamaz', 'ask-olamaz-mustafa-sozlu-6iw9l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk olamaz 

		Mutluluk olmadan

 Olabilir

                       Acı içinde

		Zorlukla

		Sorumsuz

		Ve akılsız.

Olabilir

		Ölümcül tehlikeli

Ama mutluluk olmadan

Aşk olamaz

O öldürse bile

Bunu anlamayan

Mutlu aşka değmez.

                                                               B.Zahoder

(Rusça) Mustafa SÖZLÜ', 'Aşk olamaz  		Mutluluk olmadan  Olabilir                        Acı içinde 		Zorlukla 		Sorumsuz 		Ve akılsız. Olabilir 		Ölümcül tehlikeli ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-olamaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aziz Rusya sevgili vatanım', 'aziz-rusya-sevgili-vatanim-mustafa-sozlu-7y7mi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Özgürlüğünün özlemini seviyorum senin

Aziz Rusya sevgili vatanım

Kaderinden Hüzünlü kararların

Korkmuyorum ve utanmıyorum

Bütün yolların benim için aziz senin 

Varsın,akılsız bir yol tehdit etsin 

İster karanlıkla, ister soğuk mezarla

Ben dönmek istemiyorum senden

Yalvarmıyorum ruhuna kötülüğün.

Dua eder gibi ezberden,

Tekrarlayıp dururum dört kelimeyi

Bu güzellik,bu hüzün

			S.Yesenin

(Rusça) Mustafa SÖZLÜ', 'Özgürlüğünün özlemini seviyorum senin Aziz Rusya sevgili vatanım Kaderinden Hüzünlü kararların Korkmuyorum ve utanmıyorum Bütün yolların ben...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aziz-rusya-sevgili-vatanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece/Gündüz', 'gece-gunduz-adulera-ayza-ikxci', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece sustu 

Kızılcık şerbeti içti

Kan kustu

Gece şuçlu 

Aşk şarabından içti

Kendinden geçti

Gece korktu

Gündüz aynada 

Kendini buldu

Gece gebe

Sabah tüm bilinemezlere

Gece cesur

Aydınlıga mecbur

Gece sırdaş

Herkese yoldaş

Gece sefil

Günbegün rezil

Gece hayat 

Öglen oldu hala bayat

Gece seksi

Günboyu eksi

Gece ve gündüzden korkuyorum

Aşkım seni her zaman seviyorum.', 'Gece sustu  Kızılcık şerbeti içti Kan kustu Gece şuçlu  Aşk şarabından içti Kendinden geçti Gece korktu Gündüz aynada  Kendini buldu Gece ge...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gece-gunduz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gürcistan tepeleri', 'gurcistan-tepeleri-mustafa-sozlu-b9wmb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gürcistan tepelerinde gece karanlığı var.

Aragva önümde çağlar.

Bana her şey hüzünlü ve kolay

Benim hüznüm ortada

Seninle dolu benim hüznüm.

Harika anları hatırlıyorum

Benim gözlerimin önündesin

Bir hayal gibi gelip geçici

Saf güzelliğin kahramanı gibi

Ümitsiz, karanlıklarında hüznün

Gürültülü telaşından uzak koşturmaların

Bir ses çınladı yumuşak, kulağımda uzun süre

Ve harika güzelliğin önünde gözümün.

			A.S.Puşkin

(Rusça) Mustafa SÖZLÜ', 'Gürcistan tepelerinde gece karanlığı var. Aragva önümde çağlar. Bana her şey hüzünlü ve kolay Benim hüznüm ortada Seninle dolu benim hüznüm....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gurcistan-tepeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Siz', 'sen-ve-siz-mustafa-sozlu-0n3ux', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçten bir ‘senle’, kuru bir ‘sizi’

O değiştirdi sürçerek dili.

Ve bütün mutlu hayalleri 

Seven kalbimde uyandırdı.

Önünde dururken düşünceli

Kuvvetim yok 

kaçıracak kadar  gözlerimi

Ve dışımdan söylüyorum; 

-Sevimlisiniz ne kadar çok

Ve içimden düşünüyorum

-Seni seviyorum ne kadar çok.

                                                               A.S.Puşkin

(Rusça) Mustafa SÖZLÜ', 'İçten bir ‘senle’, kuru bir ‘sizi’ O değiştirdi sürçerek dili. Ve bütün mutlu hayalleri  Seven kalbimde uyandırdı. Önünde dururken düşünceli...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Sözlü']::text[], 8.5, '{"poet":"Mustafa Sözlü","poet_slug":"mustafa-sozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-ve-siz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Visali Gönlüme', 'gel-visali-gonlume-ali-riza-unal-bhoti', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geel! sevgilim gel! Yeter ki gelen sen olasın

İster gündüz gün ile ister yıldızlar ile gecede

İster bin heves ister nefes ile bir hecede

Bin ömre bedel o buseni nihan et bin peçede

Gel! Ey nigârı cânânım! yeter ki sen gel

O sende ki ben ile o tendeki can ile 

İster başında yazman al olsun gel dilindeki bal ile

Gel visali gönlüme, bir katren birdir umman ile', 'Geel! sevgilim gel! Yeter ki gelen sen olasın İster gündüz gün ile ister yıldızlar ile gecede İster bin heves ister nefes ile bir hecede Bin...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-visali-gonlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine gelsen', 'yine-gelsen-i-shak-ozlu-eta0r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ayda geçti,yılda geçti,

Yavru kuşlar kanatlanıp uçtu.

Bu ayrılık bizemi düştü,

Yine gelsen,yine gülsen.

Karlar eridi,yollar açtı,

Göçmen kuşlar dönüşe geçti.

Arife bitti,bayram geldi,

Yine gelsen,bayrama gelsen.

Zalım gurbeti muradmı seçtin,

Çare bulunmaz derdemi düştün.

Kavuşmak hayal,yüzün görsem,

Yine gelsen,yine görsem.

Geçmiyor yıllar selamına hasret.

Yanar yürek cemaline hasret.

Geliversen bitse bu hasret,

Yine gelsen,bize gelsen.', 'Ayda geçti,yılda geçti, Yavru kuşlar kanatlanıp uçtu. Bu ayrılık bizemi düştü, Yine gelsen,yine gülsen. Karlar eridi,yollar açtı, Göçmen kuş...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-gelsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm (2)', 'gonlum-2-abdullah-atay-r4doe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'deli divane gönlüm 

yarsız virane gönlüm 

yar bende ben olunca 

bil ki şahane gönlüm... 

has bahçede gül gönlüm 

sevmesini bil gönlüm 

hicranım vuslat oldu 

sen de artık gül gönlüm... 

damarlarda kan gönlüm 

bedenlere can gönlüm 

hep gülden güle uçtun 

bir dilbere kon gönlüm... 

baharımda yel gönlüm 

akıp coşan sel gönlüm 

her çiçekten bal aldın 

yeter artık gel gönlüm... 

yalnızlıkta çöl gönlüm 

feryat figan dil gönklüm 

bitti zalim ayrılık 

gözyaşını sil gönlüm... 

sular gibi gür gönlüm 

kuşlar gibi hür gönlüm 

insanlığın yolunda 

özü sözü bir gönlüm...', 'deli divane gönlüm  yarsız virane gönlüm  yar bende ben olunca  bil ki şahane gönlüm...  has bahçede gül gönlüm  sevmesini bil gönlüm  hicra...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonlum-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsun...', 'seviyorsun-sibel-uygun-d3p8h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dudakların konuşamadı...

Ama! ..

Yüreğin ‘seni seviyorum’ diyor...

Sen sustukça; 

İçindeki nehirler, çıldırmışcasına bana doğru akıyor.

Donuk bakışların,derinlere manasız tavırlar sunsa da,

Gizliden bana koşuyor gözlerin...

Bak, ellerin üşüyor yokluğumda...

	

Neden inat ediyorsun? ..

Bu mesafeler neden? ..

Manasız kaçışlar...

Neden? ..

Hadi! .. 

Uzaklaş! ..

Sen, alabildiğine uzaklaş! ..

Sendeki sen, ben olmuş farkına bile varamamışsın...', 'Dudakların konuşamadı... Ama! .. Yüreğin ‘seni seviyorum’ diyor... Sen sustukça;  İçindeki nehirler, çıldırmışcasına bana doğru akıyor. Donu...', ARRAY['Türk Edebiyatı','Şiir','Sibel Uygun']::text[], 8.5, '{"poet":"Sibel Uygun","poet_slug":"sibel-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çilekeş', 'cilekes-yavuz-agir-bug1i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yar beni beni

.Can beni beni

Feleğin çemberi,

Döndürür durur beni

Gülüm susuz kurudu

Gözüme duman bürüdü.

Oyalı mendilim çürüdü.

Çile üstüne üstüne.

Yar beni beni

.Can beni beni

Feleğin çemberi,

Döndürür durur beni

Felek gözün kör olsun

Acımadın perişan halime.

Sarılıp doyamadım

Yarin ince beline...

.

Yar beni beni

Can beni beni

Feleğin çemberi,

Döndürür durur beni....', 'Yar beni beni .Can beni beni Feleğin çemberi, Döndürür durur beni Gülüm susuz kurudu Gözüme duman bürüdü. Oyalı mendilim çürüdü. Çile üstüne...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cilekes-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah''ın Belası', 'allah-in-belasi-i-zzet-selcuk-cumaoglu-5w770', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ALLAH’IN BELASI

Hiçbir şey yakmadı canımı böyle,

Seninle yıkıldı tüm hayallerim.

Sana olan sevdam suç oldu diye,

Yazıldı boynuma Allah’ın belâsı.

Yıktığın umutlar benim dünyamdı,

Yaşardım onlarla var olur diye.

Ömrümü tüketti o pis nefretin,

Sokuldu koynuma Allah’ın belâsı.

Kururken sevdanın pembe çiçeği,

Büründü siyaha aşk gelinciği.

Eskiyen yüzümün kırışıklığı

Yansıdı aynama Allah’ın belâsı.', 'ALLAH’IN BELASI Hiçbir şey yakmadı canımı böyle, Seninle yıkıldı tüm hayallerim. Sana olan sevdam suç oldu diye, Yazıldı boynuma Allah’ın be...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/allah-in-belasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamıyorum', 'anlatamiyorum-i-zzet-selcuk-cumaoglu-fq180', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ANLATAMIYORUM

Hergün

Belki ararsın diye

Bu köhnemiş odamı bekliyorum,

Istırabım büyüdükçe büyüyor

Kanıyor yüreğim

Derdimi anlatamıyorum.

Hergün

Yorgun gözlerle yolunu gözlüyorum

Binbir hayaller peşimde,

Bir telaş içerisinde çırpınıyor yüreğim,

Geçmişi deşeleyip

Yüreğimi kanatıyorum.

Ne sesin geliyor uzaktan

Ne sen dönüyorsun

Ne kadar da zalimsin

Beni yıpratmaktan usanmıyorsun.

Çalan bir telefona

Ya da kapı ziline 

Gelen sensen diye umutla koşuyorum

Hüsranla tükenirken umutlarım

Yüreğim kanıyor

Kimseye anlatamıyorum.', 'ANLATAMIYORUM Hergün Belki ararsın diye Bu köhnemiş odamı bekliyorum, Istırabım büyüdükçe büyüyor Kanıyor yüreğim Derdimi anlatamıyorum. Her...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/anlatamiyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece', 'dun-gece-ali-fikri-karadeniz-tv50o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece rüyamda ne arıyordun? 

Beyazlar içinde gelinliğinle? 

Önce dolaştın gelincikler arasında

Sonra boy attın buğday tarlasında

Bahar mıydın; baharımda renklenen? 

Yağmur muydun, bereket bahçelerinde? 

Rüzgar mıydın, kaybettiğini arayan? 

Ne rüyada, ne tarlada, ne de başka yerdeyim

Şunu bil ki

Ben… Ben hala bıraktığın yerdeyim

Sahi; 

Dün gece rüyamda ne arıyordu? 

Beyazlar içinde gelinliğinle? ? ? 

                                                     03/02/2005', 'Dün gece rüyamda ne arıyordun?  Beyazlar içinde gelinliğinle?  Önce dolaştın gelincikler arasında Sonra boy attın buğday tarlasında Bahar mı...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dun-gece-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Durmaz', 'hayat-durmaz-i-zzet-selcuk-cumaoglu-fezf0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HAYAT DURMAZ

Yıllar bir nehir gibi akıp giderken

Sanki dere yatağı ömür tüneli.

Aşınır yaşam boyu hergün bir parça

Sette çeksen önüne durduramazsın.

Ne sular akıp gider, dur durak bilmez,

O akışın durmaya yoktur zamanı.

Salkım söğüt eğilmiş öperken suyu

Sen daldırsan testini dolduramazsın.

Her gidene iyi bak nehrin içinden

Bir daha göremezsin, giden dönmüyor.

Bir zamanlar neydiler, şimdi nerdeler

Kapılmışlar girdaba döndüremezsin.', 'HAYAT DURMAZ Yıllar bir nehir gibi akıp giderken Sanki dere yatağı ömür tüneli. Aşınır yaşam boyu hergün bir parça Sette çeksen önüne durdur...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-durmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğim', 'sessizligim-ali-fikri-karadeniz-dbx8w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün batar, kuşlar tüner

Bir ben kalırım karanlığımda

Yalnızlığımla baş başa bir ben…

Hüzünler şarkı olur dilimde

Dua’lar çınar gibi yükselir de

Özlemler yaprak yaprak düşer gönlüme

Yine de avutamam kalbimi

Yaşarım sonbaharın sessizliğini

Rüzgarı beklerim penceremin önünde

Elimde “üzerine yazdığım”

Çeyizimde sakladığım gül yapraklarım

Salarım usulca yer yüzüne

Alıp Sana getirsinler diye…

Hayallerim canlanır dalga dalga

Büyür de Tusunamim olursun

Sen sahte denizlerde yüzerken

Ben… Ben Sesizliğimde BOĞULURUM…

                                                   04/02/2005', 'Gün batar, kuşlar tüner Bir ben kalırım karanlığımda Yalnızlığımla baş başa bir ben… Hüzünler şarkı olur dilimde Dua’lar çınar gibi yükselir...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessizligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızları Saymak', 'yildizlari-saymak-i-zzet-selcuk-cumaoglu-b3thq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YILDIZLARI  SAYMAK

Sen her mevsim açan gonca gül idin

Gönlümdeki esip duran yel idin

Sevda dolu yüreğimde göl idin

Tufan oldu akıp gittin sel oldun

Aylar yıllar seni sevdim bir tanem

Senden başka daha güzel görmedim

Ömrüm geçti muradıma ermedim

Bitti aşkın yüreğimde çöl oldun.

Sayamadım yıldızları yıllardır

Birer birer kayıp gitti önümden

Koyamadım hiç birini yerine,

Sen de yoksun, kayıp gittin el oldun.', 'YILDIZLARI  SAYMAK Sen her mevsim açan gonca gül idin Gönlümdeki esip duran yel idin Sevda dolu yüreğimde göl idin Tufan oldu akıp gittin se...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yildizlari-saymak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık Hali', 'i-nsanlik-hali-ali-riza-unal-85ldz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne ararsan taşrada değil kendinde ara

Alemi cihan sende, kâbedir gönül...

Kimi aşık, düşer sevdaya  çöl dolaşır

Varlığın sebebi leylidir gönül

Kimi taş olur, gönlü bir garip şaşı

Koy önüne arpayı, yulafı sakindir başı

Kimi külhan, kılıç kalkan dağ aşırır

Kavgadır kısmeti geçimi, yemeği aşı

Hırsı bürümüş varlığa, makama beylidir gönül

Kimi sevmez her lokmayı gerilir kaşı

Ah eder zora miskinim düzde şaşırır

Bilenim biner ilim düdülüne arşı aşırır

Bizim hoca sineğin kıçında yağ ile uğraşır

Kimi alır eline kalemi üfürür mangalda küle

Ne kelepçe ne zincir yok ki vurula kemiksiz dile

Neden türküler, şarkılar söylenir dikenli güle

Bilen var mı acep soruldu mu bülbüle

Ey Rıza bilesin bu sözler bir cilveyi Rabbani

Sonu gelmez sözün, gitme küfüre bırak laf dizmeyi 

Ol Hakkani bil yetmiş milleti siyah beyaz ile

El eyle dişi erkek insana, hayvana birde bağ ile bağbana

Sev gönülden hepsini hak ile sen güle güle', 'Ne ararsan taşrada değil kendinde ara Alemi cihan sende, kâbedir gönül... Kimi aşık, düşer sevdaya  çöl dolaşır Varlığın sebebi leylidir gön...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/insanlik-hali-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar ve karakış', 'bahar-ve-karakis-muhammed-kirkinci-cbv21', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece gözlerine iner mehtab,

Sabah yüzündede doğar güneş.

Teninde yol alır usul usul.

Şarkılar sana yazılır hep

Çiçekler sende açar.

Kırlar seninle yeşerir seninle güler herşey

  SEN NEŞE,

     SEN HEVES,

        SEN BAHAR

Kara bulutlar çöker gözlerime,

Seni düşündükçe bırakır damlalarını,

Kara toprağa.

Ağıtlar bana yazılır hep.

Yapraklar banimle solar

Gökyüzü benimle ağlar.

Benimle yağar karlar.

   BEN HÜZÜN.

      BEN ACI.

         BEN KARAKIŞIN ÖBÜR ADI.', 'Gece gözlerine iner mehtab, Sabah yüzündede doğar güneş. Teninde yol alır usul usul. Şarkılar sana yazılır hep Çiçekler sende açar. Kırlar s...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Kırkıncı']::text[], 8.5, '{"poet":"Muhammed Kırkıncı","poet_slug":"muhammed-kirkinci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahar-ve-karakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamaz Sevenler', 'unutamaz-sevenler-i-zzet-selcuk-cumaoglu-f1ney', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılıklar uzarken yanar durur yüreğim,

Hasret yakar içimi, ömür biter bu yolda,

Sana olan sevgimi gözyaşlarım ıslatır

Sulandıkça gürleşir büyür gider bu sevda.

Bir ayrılık sürerse bu kadar uzun yıllar,

Umutlar tükenirken sevgiler hüsran olur,

Hatıralar silinmez, unutur sevilenler,

Yaşanmış o günleri unutamaz sevenler.', 'Ayrılıklar uzarken yanar durur yüreğim, Hasret yakar içimi, ömür biter bu yolda, Sana olan sevgimi gözyaşlarım ıslatır Sulandıkça gürleşir b...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unutamaz-sevenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Güle Güle', 'git-gule-gule-ali-fikri-karadeniz-10hwl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim kara bulutlar gibi

Ağlarsam göz yaşımı hisseder misin? 

Dua’lar ayyukta güneş misali

“Dön” desem, geriye döner misin? 

Odamın her köşesi Sana alışmış

Korkarsın diye mumlar yakıyorum

Sevgimi dolduruyorum kadehlere

Sonra bir yudumda Seni içiyorum; 

Şerefe…

Senin için beslediğim menekşe

Bir başka açıyor gönlümde

Bir başka çiçekleniyor rengârenk

“Sula gözlerim” diyorum; sula

Sen açıyorsun; ben ağlıyorum…

Hayallerim doluyor kahrolası kalbime

Hani nasıl desem? 

Nasıl inlesem? 

Hani kristal bardak gibi

Vuruyorsun yerlere… 

Git güle güle… Git güle güle…

Silahın ucunda son mermim gibisin

Önce bir dağı

Sonra bir çınarı

Yok yok bir dünyayı

Hayır bir “SEVDAYI”

İlk önce devirdin yerlere

Sonra çiğnedin ihanetinle

Git güle güle… Git güle güle…

Rabbimden Dileğimdin Sen benim

Şimdi yüreğim parçalanıyor

Ciğerim yanıyor

Bir nilüfer çiçeği ağlıyor be

Ağlıyor…

Susturamadığım isyanlar var yüreğimde

Gelincik çiçeklerini yoluyorum

Çöl olacak gönlümde

Her gün bir yenisi bitiyor

Lanet olsun; gözlerim kan ağlıyor…

Seni böyle delice severken

Bu kadar ölümü özlememiştim

Bir gün hatırlarsan doğum günümde

Ölümümü gönder kırmızı kurdeleyle

Git güle güle… git güle güle…

Git… Bütün mutluluklar Senin olsun

Rabbim yolunu nurlarla doldursun

Ben isyan ederken kaderime

Birtanem; 

Her şey gönlünce olsun…! 

                                           05/02/2005', 'Gözlerim kara bulutlar gibi Ağlarsam göz yaşımı hisseder misin?  Dua’lar ayyukta güneş misali “Dön” desem, geriye döner misin?  Odamın her k...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/git-gule-gule-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya', 'dunya-i-zzet-selcuk-cumaoglu-99mli', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir eski dost gördüm selam vermedi,

Karıncayı gördü de beni görmedi,

Buyur ettim gönlüme ama girmedi,

İnsanlığın kalmamış, batasın dünya.

Alnıma yazılmış böylesi kader,

Yaşadım üstünde binlerce keder,

Verdiğim sevgiler olmuşsa heder

Hüznünü üstüme atasın dünya.

Bir elin göktedir bir elin yerde,

Şifa yok düşersen aşk denen derde,

Şems için dönerken halimi gör de

Sevgime sevgini katasın dünya.', 'Bir eski dost gördüm selam vermedi, Karıncayı gördü de beni görmedi, Buyur ettim gönlüme ama girmedi, İnsanlığın kalmamış, batasın dünya. Al...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunya-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Donuyorum', 'donuyorum-ali-fikri-karadeniz-c23tr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gece ne kadar soğuk

Kutupta bir gül gibiyim

Ağıtlar yazıyorum ardından

Kocaman bir dağ yapıyor

Ve yakıp ısınmaya çalışıyorum…

Dua’lar yükseliyor alev alev

Kan kusturan yüreğimden

Ve ben hala

Hala yokluğunda DONUYORUM…! 

                                                              30/01/2005', 'Bu gece ne kadar soğuk Kutupta bir gül gibiyim Ağıtlar yazıyorum ardından Kocaman bir dağ yapıyor Ve yakıp ısınmaya çalışıyorum… Dua’lar yük...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/donuyorum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin', 'benim-i-cin-i-zzet-selcuk-cumaoglu-lsqcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BENİM İÇİN

Benim için bu gece  bir şarkı söyle

Nağmelerinde biraz  hüzün bulunsun

Gözlerine hakim ol akmasın yaşlar

Bakışına hasreti kat benim için.

Kuruver masayı sanki ben varım

Kadehler tükensin dudaklarında

Şaraplar saçılsın şöyle yerlere

Dünyanın anasını sat benim için

Nasıl özlediğimi bilmeyeceksin

Boş yere bekliyorum gelmeyeceksin

Bırak kalsın okuma ne anlamı var

Şiirlerimi çöpe at benim için.', 'BENİM İÇİN Benim için bu gece  bir şarkı söyle Nağmelerinde biraz  hüzün bulunsun Gözlerine hakim ol akmasın yaşlar Bakışına hasreti kat ben...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/benim-icin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasil vazgecerim senden ben?', 'nasil-vazgecerim-senden-ben-kardelen-ceyda-s19qa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen siirlerimin ilham kaynagi

geceleri canima can yoldasinsin

sen anlatmak isteyipte anlatamadigim

kelimelerle ifade edemedigimsin

varligimda sen varsin

yoklugumda,bitmisligimde

ezikligimde yine sen.

gülerken sanki yanimdasin

gözümden akan yaslarda

yine sen...

simdi; 

nasil vazgecerim senden ben....', 'sen siirlerimin ilham kaynagi geceleri canima can yoldasinsin sen anlatmak isteyipte anlatamadigim kelimelerle ifade edemedigimsin varligimd...', ARRAY['Türk Edebiyatı','Şiir','Kardelen Ceyda']::text[], 8.5, '{"poet":"Kardelen Ceyda","poet_slug":"kardelen-ceyda","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nasil-vazgecerim-senden-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakladım Gözlerime', 'sakladim-gozlerime-i-zzet-selcuk-cumaoglu-yu6yt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SAKLADIM GÖZLERİME

Bir acı sitem gibi gözlerimde saklısın 

Dinlemedim sözünü ne söylesen haklısın

Sevme beni demiştin şimdi hâlâ duyarım 

Çiçek gibi dalında solar durur bu yürek.

Hatıralar canlanır rüya olur gözümde

Seninle geçen günler akar gider önümden

Hayalin bir kor gibi dolarken düşlerime

Gözlerime yaş dolar yanar durur bu yürek.

Unutmak mümkün değil aklımdan çıkmıyorsun

Ne çare ki dönüp de bir kere bakmıyorsun

Acı bir sitem oldun saklandın gözlerime

Düşündükçe geçmişi kanar durur bu yürek', 'SAKLADIM GÖZLERİME Bir acı sitem gibi gözlerimde saklısın  Dinlemedim sözünü ne söylesen haklısın Sevme beni demiştin şimdi hâlâ duyarım  Çi...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sakladim-gozlerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-i-zzet-selcuk-cumaoglu-h7ea8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENİ ÖZLÜYORUM

Bir tabak meze, bir kadeh rakı

Dudaklarımda sen, 

Seni içiyorum.

Gökyüzünde matem, matemde gözyaşı

Gözyaşımda sen, 

Seni ağlıyorum.

Kıpır kıpır gönlüm, gönlümde bir arzu

Arzularımda sen, 

Seni istiyorum.

Kalbimde bir ateş, ateşimde sevda,

Sevdalarımda sen,

Seni seviyorum.

Aramızda ayrılık, ayrılıkta hasret,

Hasretimde sen,

Seni özlüyorum.', 'SENİ ÖZLÜYORUM Bir tabak meze, bir kadeh rakı Dudaklarımda sen,  Seni içiyorum. Gökyüzünde matem, matemde gözyaşı Gözyaşımda sen,  Seni ağlı...', ARRAY['Türk Edebiyatı','Şiir','İzzet Selçuk Cumaoğlu']::text[], 8.5, '{"poet":"İzzet Selçuk Cumaoğlu","poet_slug":"i-zzet-selcuk-cumaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-ozluyorum-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramızda Yarım Kalan Bir şey var', 'aramizda-yarim-kalan-bir-sey-var-ali-fikri-karadeniz-isu7r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çiçeklerin kokularını almışlar

Tek kanatlı kırlangıç uçmaya çalışıyor

Mavi dünyamı karaya boyamışlar

Aramızda yarım kalan bir şey var…! 

Kardelen çiçeğinin asiliği alınmış

Isırgan otu yüreğimi yakıyor

Cezayir menekşemi zindanlara salmışlar

Aramızda yarım kalan bir şey var…! 

Bülbül Gül’ünü arar, Gül sevdasını

Piyanonun notaları kaybolmuş

Kemanımın tellerini koparmışlar

Aramızda yarım kalan bir şey var…! 

Bulutlar yağmurunu kaybetmiş

Gökte ay; yarım dolunay

Yıldızlar düştü düşecek başucumda

Güneşimin ışıklarını almışlar

Aramızda yarım kalan bir şey var…! 

Dağlarımın ağaçları yok, çimeni yok, taşı yok

Ceylanımı tam kalbinden vurmuşlar

Ve gökkuşağımın renklerini çalmışlar

Aramızda yarım kalan bir şey var…! 

Hayallerim şimdi boş bir dünyada

Gözlerimde yaşanmışın izi var

Acılarım yüreğimi dağlarken

Aramızda yarım kalan bir şey var…! 

Aramızda ayrılığın izi var

Aramızda sevgimizin tadı var

Aramızda helalliğin yeri var

Aramızda yarım kalan bir şey var……….! ! !', 'Çiçeklerin kokularını almışlar Tek kanatlı kırlangıç uçmaya çalışıyor Mavi dünyamı karaya boyamışlar Aramızda yarım kalan bir şey var…!  Kar...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/aramizda-yarim-kalan-bir-sey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmeni', 'donmeni-leyla-isik-o0mib', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayalin köpükler gibi sallanır dalgalarda

 Yaşamıyor,sanki o anılar uykuya dalmış

 Akşamın kırıntıları kalmış ıssız kumsalda

 Sevgiden geri kalan ne varsa martılar almış

 Sensizlik beyaz bir gemi şimdi derin sularda

 Kapılmış gider, yok ne dümeni ne de yelkeni

 Yalnızlık demir atmış bekler o ıssız koylarda

 Özlerim,yosun tutmuş kayalıklarda dönmeni', 'Hayalin köpükler gibi sallanır dalgalarda  Yaşamıyor,sanki o anılar uykuya dalmış  Akşamın kırıntıları kalmış ıssız kumsalda  Sevgiden geri ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/donmeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canalanbeli', 'canalanbeli-i-shak-ozlu-us7x3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolum zorlu köyüm ırak,

Kamyoncu gardaş sagda bırak.

Burdan gerisini yürürüm artık,

Ne kaldıki şunun şurasında.

Kar yıgılmış yol seçilmez,

Canalanbeli kolay geçilmez.

Dayan dizlerim durmak olmaz,

Durupta yari bekletmek olmaz.

Uyuştu elim ayagım üşümez,

Kesildi derman dizlerim yürümez.

Uyku geldi sardı bedeni,

Gözüm görmez gelen gideni.

Kurtla çakal sıralı ulur,

Akşamın karanlıgı aydınlıgı bürür.

Hayalmi gerçekmi sevdigim gelir,

Sıcak nefesi bedenime yürür.

Kurtmu geldi,sevdigim mi yetti,

Donmuş bedenimi kar''mı yuttu.

Uluyan kurtların neden sustu,

Dagılsın dumanın görevin bitti.', 'Yolum zorlu köyüm ırak, Kamyoncu gardaş sagda bırak. Burdan gerisini yürürüm artık, Ne kaldıki şunun şurasında. Kar yıgılmış yol seçilmez, C...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/canalanbeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Mendilde', 'beyaz-mendilde-leyla-isik-86x6j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlığın sessizliğinde yıkanırken yalnızlık

 Yüksek kıraç tepede, iki seven insan yok artık.

 Mutlu olmak özlemi var, seven kalplerimizde

 Silinmedi  sıcak  bakışlar hala gözlerimizde

Geçmişi düşünürken, mutlu oluyorum bir anlık

 Yarım kalmış  sevgiyle, yaşam sona erecek yazık! 

 Aşk, mutluluk dolu günler kaldı artık  geride

 Anılar gizli şimdi, saklanan bir Beyaz Mendilde.', 'Karanlığın sessizliğinde yıkanırken yalnızlık  Yüksek kıraç tepede, iki seven insan yok artık.  Mutlu olmak özlemi var, seven kalplerimizde ...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyaz-mendilde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylanın Çimenleri', 'yaylanin-cimenleri-yavuz-agir-gfy0d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaylanın çimenleri,

Buram buram kokar durur.

Renk renk açar çiçekleri,

Sevgi ile coşar durur.

O yaylanın suları var

Şarıl şarıl akar durur

Şirin şirin dereleri,

Sevgi ile coşar durur.', 'Yaylanın çimenleri, Buram buram kokar durur. Renk renk açar çiçekleri, Sevgi ile coşar durur. O yaylanın suları var Şarıl şarıl akar durur Ş...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yaylanin-cimenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Rüyamda', 'dun-gece-ruyamda-ali-fikri-karadeniz-cvww4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sesizliğim

Gün batar, kuşlar tüner

Bir ben kalırım karanlığımda

Yalnızlığımla baş başa bir ben…

Hüzünler şarkı olur dilimde

Dua’lar çınar gibi yükselir de

Özlemler yaprak yaprak düşer gönlüme

Yine de avutamam kalbimi

Yaşarım sonbaharın sessizliğini

Rüzgarı beklerim penceremin önünde

Elimde “üzerine yazdığım”

Çeyizimde sakladığım gül yapraklarım

Salarım usulca yer yüzüne

Alıp Sana getirsinler diye…

Hayallerim canlanır dalga dalga

Büyür de Tusunamim olursun

Sen sahte denizlerde yüzerken

Ben… Ben Sesizliğimde BOĞULURUM…

                                                   04/02/2005

Ali Fikri Karadeniz', 'Sesizliğim Gün batar, kuşlar tüner Bir ben kalırım karanlığımda Yalnızlığımla baş başa bir ben… Hüzünler şarkı olur dilimde Dua’lar çınar gi...', ARRAY['Türk Edebiyatı','Şiir','Ali Fikri Karadeniz']::text[], 8.5, '{"poet":"Ali Fikri Karadeniz","poet_slug":"ali-fikri-karadeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dun-gece-ruyamda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Beni...', 'ara-beni-leyla-isik-7pfl5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik içime çökünce

 deli eder beni düşünceler

 beklerim

 gelmez günlerdir senden

 ne bir mektup...ne bir haber...

 özlerim seni.

 elimde değil! ...

 kalbim hep seni ister

 sana olan sevgimi anlatmaya yetmez sözcükler.

 akşam olup,basınca karanlık

 konuğum olur yalnızlık

 anınca seni

 sarar beni ürpertiler ılık ılık

 gözlerimde yaş

 kalbimde hıçkırık oldu ayrılık

 bekliyorum...

 bıkmadan,usanmadan

 hadi ara beni artık.......', 'Sensizlik içime çökünce  deli eder beni düşünceler  beklerim  gelmez günlerdir senden  ne bir mektup...ne bir haber...  özlerim seni.  elimd...', ARRAY['Türk Edebiyatı','Şiir','Leyla Işık']::text[], 8.5, '{"poet":"Leyla Işık","poet_slug":"leyla-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ara-beni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yitik zaman hikayeleri – VIII', 'yitik-zaman-hikayeleri-viii-turgut-baki-5cme7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uzaktan gelen bir neyin 

tiz titrek sesi süzülürken havada

ne i-düğü belirsiz bir gecenin peydahladığı 

korku tohumları serpiliverdi sokağa

tüm şehir 

derin bir uykuda

havada ay tutulması alametleri

kendi mahremiyetinin tapınağında diz bir çökmüş adam

büyük mumlar gibi dizilmiş düşüncelerinin ışığında

ruhunda büyük yırtıklar açan 

onu dikmeyi de bilmelidir 

diye yazıyordu billur kağıtlara 

kelimeler bir biri ardı sıra 

bir yılan gibi kıvrılarak aktılar gölgesine ışığın

ve ağzı salyalı şer köpekleri gibi dizildiler karşısına

kendinden emin 

ama acı bir tebessümle gülümsedi adam

bir çift kristal damla 

gözlerinden yol buldu yüreğine

kesif bir yasemin kokusu kapladı odayı

ve altın ışıktan 

tül kanatlı bir melek

savurdu şeytanın erlerini semaya

şimdi 

ruhunu yamama vaktidir ey adam 

haydi durma

yama

ya ma... ya ma', 'uzaktan gelen bir neyin  tiz titrek sesi süzülürken havada ne i-düğü belirsiz bir gecenin peydahladığı  korku tohumları serpiliverdi sokağa ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yitik-zaman-hikayeleri-viii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara Nida! ...', 'daglara-nida-nihat-malkoc-ck271', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Yürek Dostu Kaleli’ye Nazire…) 

Karanlığı boğan nurlu dağlar hey! 

İçimdeki sırrı bilebilmezsin

Hakk’a yakın,mahcup,arlı dağlar hey! 

Ölmek istesen de ölebilmezsin

Geçen yolculara bağrını açsan

Doğan güne inat,aydınlık saçsan

Aşkına karşılık ağular içsen

Yine ağyara dost kalabilmezsin

Yukardayım diye kasılıp durma

Geleceğe dair hayaller kurma

Sonradan başını taşlara vurma

İsrafil’e engel olabilmezsin

İnsanlıktan kaçıp sığındım sana

Kararsızım,bilmem gitsem ne yana

Nara yandı yürek,köz düştü cana

Şol bîmara şifa salabilmezsin

Köroğlu’ya bağrını açan dağlar

Yüreğinden Resûller geçen dağlar

Hakka dönüp batıldan kaçan dağlar

Cihandan ukbaya göçebilmezsin', '(Yürek Dostu Kaleli’ye Nazire…)  Karanlığı boğan nurlu dağlar hey!  İçimdeki sırrı bilebilmezsin Hakk’a yakın,mahcup,arlı dağlar hey!  Ölmek...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daglara-nida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuru Bir Çınar Ağacı', 'kuru-bir-cinar-agaci-faruk-tekin-y67bq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni dostluğum,

Bir çınar ağacıylaydı.

Zamansız kurutmuştu kendini.

Belli öfkeliydi,küskündü

Önündeki ve ardındaki yaşama.

Yüreğimin kırıklığı,

Bedenime vurmuştu inceden.

Hafifçe titremeyle:

“Ayrıldık” dedim.

Göz pınarlarıma direnerek.

Koca çınar sarsıldı.

Ne kadar gizlemek istese de; 

Kuru dalları ele verdi kendisini.

Gövdesinin sol tarafındaki,

Kan sızıntısını eliyle saklayarak,

“Boş ver “ diyebildi.

Kısa suskunluğunun ardından:

Kimin diktiğini bilsem de,

Neden dikildiğimi bilmiyorum buraya.

Tam da yeşermişken,

Neden çekip gittiklerini de.

Şu diğer çınarlar,

Hem çok yakınımda hem çok uzağımdalar.

Sadece korkunç bir fırtınada 

Bana doğru uzanırlar.

Bu yüzden,işte bu yüzden

Gel git sevdalardan kurudum.

Şimdi gelmiyorum ve gitmiyorum,

Tüm zamanlarda kendimle kalıyorum.

Korkmuyorum; 

En deli rüzgarlar kollarımı kırsa da,

Tek başıma direniyor,direniyorum.

Coşmuştu koca çınar! 

Dallarıyla, göz pınarlarıma dokunmak istedi.

Utandı ve vazgeçti.', 'Yeni dostluğum, Bir çınar ağacıylaydı. Zamansız kurutmuştu kendini. Belli öfkeliydi,küskündü Önündeki ve ardındaki yaşama. Yüreğimin kırıklı...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tekin']::text[], 8.5, '{"poet":"Faruk Tekin","poet_slug":"faruk-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kuru-bir-cinar-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgunum...', 'yorgunum-zulfikar-yapar-kaleli-7tgfx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasret vurgunuyum, gerilmiş ağım

Dert beni azıya aldı, yorgunum.

Her gün yavaş yavaş kayar ayağım

Vakit ikindiyi buldu, yorgunum.

Mücadele ettim kalpsizler ile

Kalleşlik ettiler dostlarım bile

Neyleyim güneşi, ne deyim güle? 

Zamansız sarardı, soldu, yorgunum.

Yaş zevale geldi, göçtüm gurbete

Gör şu halimi de düşme hayrete

Hasretlik yerleşti kemiğe, ete

Bülbülüm biçare oldu, yorgunum.

Dert etmem diyordum kederi, yası

Bozuldu düzeni, yıkık yuvası

Kaleli’nin ıssız kaldı sılası

Yüreğim gam ile doldu, yorgunum.', 'Hasret vurgunuyum, gerilmiş ağım Dert beni azıya aldı, yorgunum. Her gün yavaş yavaş kayar ayağım Vakit ikindiyi buldu, yorgunum. Mücadele e...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yorgunum-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limandan ayrılınca', 'limandan-ayrilinca-i-shak-ozlu-zwz1m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bindigin gemi limandan ayrılınca,

Yüregimden bir parça koptu.

Ayrılık rüzgarı bedenimde savrulunca,

Yarıldı toprak benligimi yuttu.

Gözlerim bastıgın son merdivende,

Ellerim havada asılı kaldı.

Ufukta kaybolup giderken gemin,

Göz yaşlarına dönüştü sevgim.

Martılar saldım peşin sıra,

Seni sevdigimi söylesinler diye.

Attıgın simit parçasını getirdiler,

Senden bir hatıra diye.

Kıyıya vuran dalganın sesinde,

Senden bir nefes duydum.

Yüzüme çarpan dalganın zerresinde,

Bir damla göz yaşı buldum.', 'Bindigin gemi limandan ayrılınca, Yüregimden bir parça koptu. Ayrılık rüzgarı bedenimde savrulunca, Yarıldı toprak benligimi yuttu. Gözlerim...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/limandan-ayrilinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A n n e …(Vuslat Türküsü)', 'a-n-n-e-vuslat-turkusu-zulfikar-yapar-kaleli-9m0go', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni sana seni bana götüren

Yollar bir bir kıra yaslanmış, anne. 

Umutları yavaş yavaş bitiren

Bir karanlık sır’a yaslanmış, anne.

Seninle başladı, göründü ömür

Avare dolaştı, süründü ömür

Sensiz sessizliğe büründü ömür

Bir bilinmez vara yaslanmış, anne. 

Kar düştü saçıma, dağlarım sisli

Anadolu yorgun, toprağı yaslı

Gönül kapısının kilidi paslı

Akşamları zora yaslanmış, anne.

Gözsüzdü cihana bakmazdı gönül

Engindi, yükseğe çıkmazdı gönül

Su gibi her yana akmazdı gönül

Bir vefasız yâra yaslanmış, anne. 

Arar bulamayız bir sevdalı baş

Oğlumuz, kızımız,eşimiz bomboş

Gönlümüzde keder, gözümüzde yaş

Baharımız kara yaslanmış, anne.

Dağımıza umulmadık hal düştü

Gözümüze beklenmedik yol düştü

An oldu ki kanat düştü, kol düştü

Yavrucuğun dara yaslanmış, anne.', 'Beni sana seni bana götüren Yollar bir bir kıra yaslanmış, anne.  Umutları yavaş yavaş bitiren Bir karanlık sır’a yaslanmış, anne. Seninle b...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/a-n-n-e-vuslat-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim', 'gozlerim-mehmet-fatih-l6cms', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ''''Sedum Harabesi'''' gözlerinde gözlerim

Çöllerde bıraktığın izlerinde gözlerim

Ne sen varsın ufukta; ne müjdeli sesin var

Kulağımda son kalan sözlerinde gözlerim

.........

.........

ve ben seni özlerim...', 'Bir ''''Sedum Harabesi'''' gözlerinde gözlerim Çöllerde bıraktığın izlerinde gözlerim Ne sen varsın ufukta; ne müjdeli sesin var Kulağımda son k...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih']::text[], 8.5, '{"poet":"Mehmet Fatih","poet_slug":"mehmet-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gozlerim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Hepiniz Öleceksiniz', 'bir-gun-hepiniz-oleceksiniz-ahmet-aksoy-9km21', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ey gençliğim geçiyorsun umarsız

bir sürü dost gülümseyişi arasında

zaman biriktiriyor 

her şey gibi acıları da

bugün tatlı bulduğum ne varsa

hepsi yanıyor için için

sıcak her yanda 

oysa küllenecek yaşlılıkda

ve ben de dışında kalacağım 

o gün yaşayan yarının 

tekme atacak bir dinletide

havari bir genç kıçıma

diyecek çekil be moruk

ben okuyacağım 

kimse sevmiyor senin şirini

o gün hepiniz ölmüş olacaksınız

terk edeceksiniz beni cennet için

bense derin yalnızlığımla baş başa verip

konuşacağım eski günleri

sonra elbet devrilecek gözlerim

yaşlı ve buruk şarloda', 'ey gençliğim geçiyorsun umarsız bir sürü dost gülümseyişi arasında zaman biriktiriyor  her şey gibi acıları da bugün tatlı bulduğum ne varsa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-hepiniz-oleceksiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın kalemi - III', 'sevdanin-kalemi-iii-turgut-baki-r2eqj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ey kalem

nedir bu meçhul utanç

hıçkırık 

ve iç sıkıntısı

söyle

nedendir

korkunç gecelerin 

üstüne çöreklenen

dehşeti 

ve yıkıntısı

söyle

neden

sebepsiz akar 

safra gibi 

karanlıklarda

göz yaşların

ve söyle

neden

her daim

sıkılıdır yumrukların

ve etine batar tırnakların

söyle kalem

susma 

söyle', 'ey kalem nedir bu meçhul utanç hıçkırık  ve iç sıkıntısı söyle nedendir korkunç gecelerin  üstüne çöreklenen dehşeti  ve yıkıntısı söyle ned...', ARRAY['Türk Edebiyatı','Şiir','Turgut Baki']::text[], 8.5, '{"poet":"Turgut Baki","poet_slug":"turgut-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevdanin-kalemi-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel zamanı durdur bana', 'gel-zamani-durdur-bana-i-brahim-duskun-9a3zq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gel zamanı durdur bana

bu öyküyü bir de sen anlat bana

ben hala burada 

gittiğin yerdeyim

saniye,dakika,saat

gece,gündüz

gün,hafta,ay

nice yıllar

gel zamanı durdur bana

bu öyküyü bir de sen anlat bana

ben hala burada

gittiğin yerdeyim

gidenler neydi

öyküler benim miydi

düş müydü,gerçek miydi

gelenler umutlara sevimsizdi

iyisine nice yaşamlar ertelendi

özlemler büyüdü

bir ömürdü gitti

beklenen hala gelmedi

gel zamanı durdur bana

bu öyküyü bir de sen anlat bana

ben hala burada 

gittiğin yerdeyim

düşler mi zor

gerçekler mi

gel zamanı durdur bana

bu öyküyü bir de sen anlat bana

umutlar mı zor

yaşananlar mı.', 'gel zamanı durdur bana bu öyküyü bir de sen anlat bana ben hala burada  gittiğin yerdeyim saniye,dakika,saat gece,gündüz gün,hafta,ay nice y...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Düşkün']::text[], 8.5, '{"poet":"İbrahim Düşkün","poet_slug":"i-brahim-duskun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gel-zamani-durdur-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Gün', 'beklenen-gun-meral-vurgun-d1uir', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bekle sevda yürekli dağ çınarım

varsın damgasını kara vursun zaman

sabrında taşlar eriten tarih şahlanadursun

ilk cemresi düşecek baharın

sevdayı dölleyecek ilk ışıklarıyla güneş

kan pıhtısına dönecek salkım salkım kızıllık 

bir kardelen baş kaldırıp buzlar altından

selamlayacak özgürlüğünü halayın, zeybeğin, horonun

hele bir terlesin umudun alnı

yırtılsın sabrın çeperleri

emek meyveye durduğunda göreceksin

tanrılar terketmiş olacak yeryüzünü

boğulup atılırken çakal sesleri dipsiz kuyulara

bir başka gülümseyecek gökyüzü

bütün türküleri anadillere çevrilecek alınterinin

şarkısını kuşlar söyleyecek o görkemli şafağın

bütün çocukları dinleyecek dünyanın

o gün söylenmiş olacak son sözümüz

yırtıp kabuklarını yüreklerde sevgi

çiçeğe duracak kızılcık dalları

kimseler beklemezken seni benden başka

bir anda bitivereceksin yanıbaşımda

omuzuma düşecek başın

son kez haykıracağım

hoş geldin ey sevda yürekli yar! 

hoş geldin ey gökyüzümün mavisi...

ve gömüp yüzümü sol yanına

uzun uzun susacağım

sonra aşıp geldiğimiz zamanların dalından 

sararıp ince bir yaprak düşecek

ipeksi rengini alıp benden göğe serpecek

çimlenip yeşerecek üzerimi örten bir avuç toprak

göcebe kuşlar havalanacak orta yerinden yüreğimin

geriye sadece ağrısı kalacak sevmelerimin

ve ben belki de ilk kez o gün

o kadar mutlu olacağım...', 'bekle sevda yürekli dağ çınarım varsın damgasını kara vursun zaman sabrında taşlar eriten tarih şahlanadursun ilk cemresi düşecek baharın se...', ARRAY['Türk Edebiyatı','Şiir','Meral Vurgun']::text[], 8.5, '{"poet":"Meral Vurgun","poet_slug":"meral-vurgun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/beklenen-gun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var Git İşine', 'var-git-i-sine-ahmet-kurt-t43p7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyanın tasası bana mı kalmış,

Artık istemem ki var git işine.

Kendi benliğine korkular salmış,

Artık istemem ki var git işine.

Duygular delirmiş, istekse çılgın,

Metanet kalmamış, delice hırçın,

Yıllarca harcanmış tükenmiş harcın

Artık istemem ki var git işine.

Zaman sona yakın, ömürse geçmiş,

Kim bilir kaç çeşme suyundan içmiş,

Zamana ihanet en büyük suçmuş,

Artık istemem ki var git işine.', 'Dünyanın tasası bana mı kalmış, Artık istemem ki var git işine. Kendi benliğine korkular salmış, Artık istemem ki var git işine. Duygular de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/var-git-isine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arapgire Dönersin', 'arapgire-donersin-hasim-koc-ynvzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Arapgire Dönersin

Çık gel yarim yanima

Gidelim göl dağına

Araya dağlar girdi

Taş bas yarim bağrina

Aman aman güzelsin

Nerelerde gezersin

Her nereye gidersen 

Arapgire dönersin

Yanma gurbet narina

Gel salina salina

Derdinden verem oldum

Gel bak benim halime

nakarat

Arapgir çarşı başı

Yanar bağrımın başı

Her derde care varmiş

Yok ayrilik ilaci

saygi sevgi dostluk

Hasimkoc', 'Arapgire Dönersin Çık gel yarim yanima Gidelim göl dağına Araya dağlar girdi Taş bas yarim bağrina Aman aman güzelsin Nerelerde gezersin Her...', ARRAY['Türk Edebiyatı','Şiir','Haşim Koç']::text[], 8.5, '{"poet":"Haşim Koç","poet_slug":"hasim-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/arapgire-donersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükeniş', 'tukenis-gulizar-turgut-186tf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zifiri karanlık hayallerde

Umut 

Feneri yakmanın zamanı gelmedi mi sence

Aç gözlerini bak

Işık

Bir sigara ucundaki alev kadar yetersiz bu gidişte

Şimdi yıldızların altında

Malum şarkıyı söylüyorum tek düze

Nöbeti devralmak için 

Keşke 

Sevebilseydim....

Sarhoş olsaydım hem de küfelik

Sevişseydim tüm şehvetimle deli dolu

Koşsaydım koşsaydım sana doğru

Nefes nefese kalana dek

Keşke 

Keşke 

Artık sabahı bilmeyen suskun gecelerde pusudayım

Avını sabırla beklemenin kararlılığında

Aslında korkuyorum biliyor musun

Ama elimden hiçbir şey gelmiyor 

Sarıp sarmalıyor gün geçtikçe

Sanırım beni esir alıyor

Teslim oluyorum

Tükendim...

Tükendim

İşte...', 'Zifiri karanlık hayallerde Umut  Feneri yakmanın zamanı gelmedi mi sence Aç gözlerini bak Işık Bir sigara ucundaki alev kadar yetersiz bu gi...', ARRAY['Türk Edebiyatı','Şiir','Gülizar Turgut']::text[], 8.5, '{"poet":"Gülizar Turgut","poet_slug":"gulizar-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tukenis-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış anladın', 'yanlis-anladin-i-shak-ozlu-d298i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlış anladın uzaklaşıp gittin,

Yaşanmış bunca yılı silip gittin.

Güvenme gördügüne göz yanıltır,

Koca yıldızlar minik görünür.

Dogrusu nedir diye sormadın,

Kapıyı açıp içeri girmedin,

İnanma dokunduguna doku yanıltır,

Soguktan ılığa dogru sıcak gelir. 

Sanki bitirmeye yeminli geldin,

Yaşanacak yılları çizip gittin,

İnanma cümlelere cümle yanıltır,

Namaza durma,içkiliyken denir.

Ayrılık kolaydır barışık zor,

Acele etme sonunu gör.

Güven kendine yüregine sor,

Yürek yanıltmaz,yürek bilir.', 'Yanlış anladın uzaklaşıp gittin, Yaşanmış bunca yılı silip gittin. Güvenme gördügüne göz yanıltır, Koca yıldızlar minik görünür. Dogrusu ned...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yanlis-anladin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak Yasak', 'aglamak-yasak-tolga-sarican-w84f4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin çarpmalı ilk olarak gözüme 

Gülümsetmeli beni tavırların

Bakışlarımı fark etmelisin sonra

Sevinçliysen birde o gün,

Neşe saçıyorsan etrafa,

Güneşle bir olup; 

Doyamamalıyım seyretmeye

Saçlarından başlamalıyım sevmeye

Sarı kıvrımlarında kalmalı aklım

Pembe dudakların uyutmamalı beni 

Bu uykusuz gecelerin birinde, 

Hayallere dalmalıyım; 

Öpmeliyim dudaklarını nazikçe

Sonra aniden kalkıp kan ter içinde 

Lambayı yakmalıyım sakince

Aynada halimi görünce 

Karar vermeliyim güçlü olmaya

Ağlamayı bırakmalıyım

Ve yarın seninle konuşmalıyım.', 'Gözlerin çarpmalı ilk olarak gözüme  Gülümsetmeli beni tavırların Bakışlarımı fark etmelisin sonra Sevinçliysen birde o gün, Neşe saçıyorsan...', ARRAY['Türk Edebiyatı','Şiir','Tolga Sarıcan']::text[], 8.5, '{"poet":"Tolga Sarıcan","poet_slug":"tolga-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aglamak-yasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-tolga-sarican-dza9u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Korkuyorum artık gözlerinden

Bakarken bana, gülmezler diye

Korkuyorum ellerinden 

Hiç tutamadım, tutamam diye

Yüzün çok masum ama

Korkuyorum yinede

Başkasına da güler diye

Korkutuyor beni güzelliğin

Daha benim olamadan

Alırlar benden diye

Ve en önemlisi 

Korkuyorum kendimden 

Aşkımı söyleyemeden

Belki ölürüm diye.', 'Korkuyorum artık gözlerinden Bakarken bana, gülmezler diye Korkuyorum ellerinden  Hiç tutamadım, tutamam diye Yüzün çok masum ama Korkuyorum...', ARRAY['Türk Edebiyatı','Şiir','Tolga Sarıcan']::text[], 8.5, '{"poet":"Tolga Sarıcan","poet_slug":"tolga-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/korku-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şairin Gerçeği', 'bir-sairin-gercegi-tolga-sarican-grplg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir yazarım bazı bazı

Duygulanırım ansızın

Alırım kalem kağıdı

Dalarım kelimeler arasına 

Kaybolurum bazende

Ne, nerede olduğumu bilirim

Ne de nasıl çıkacağımı

Yeryüzüne

Dolaşırım kelimeler arasında

Yoklarım hepsini tek tek

Seçerim içlerinden en güzelini

Ondan sonra zaten gelir gerisi

Bazen güzel olmaz şiirlerim

Koyarım bir köşeye bir müddet bekletirim

Sonra onu güzelce düzeltip

Beğensin diye millete dinletirim

Düşünmem öyle ne yazayım diye

Ya kendisi gelir, ya kalbime söyletirim

Vermem güzelini kimselere

Onları yalnız sevdiğime gönderirim.', 'Şiir yazarım bazı bazı Duygulanırım ansızın Alırım kalem kağıdı Dalarım kelimeler arasına  Kaybolurum bazende Ne, nerede olduğumu bilirim Ne...', ARRAY['Türk Edebiyatı','Şiir','Tolga Sarıcan']::text[], 8.5, '{"poet":"Tolga Sarıcan","poet_slug":"tolga-sarican","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-sairin-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-hakan-kilic-6w8zp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaldımı bir beyaz örtüden eser

Güneş de eriyen kar tanesi dir 

Ayrılık hasreti ömürden keser 

Şiirler o sessizliğin  sesidir 

Ey güneş ne olur artık çıksana 

Bir kar gibi erit özlemlerimi 

Sıladan doğru ah gelip yıksana 

Yarabbim açtım sana ellerimi 

Gurbette çektiğim acı hasretim 

Dileğim acıdan gayri huzurdur

Parçası olduğum ah o kasvetin

Ayrılık günlerde hep bir kusurdur 

Affına sığınır kusur bedenim

Bir leke aldıysam diye ismime 

Gurbette günahım özür nedenim 

Niyetim temizce dönmek cismine

Aklımda düşünce, ruh dan elekler

Gönlümden süzülür gözüm önüne

Benide alın ah alın  melekler

Gidem bite özlem ahret yönüne

Hakanım gurbettir bana bu dünya 

Çölde suya hasret kalmış bir gülüm 

Bitsin kabuslarım bitsin şu rüya

Kavuştur Mevlama kavuştur ölüm', 'Kaldımı bir beyaz örtüden eser Güneş de eriyen kar tanesi dir  Ayrılık hasreti ömürden keser  Şiirler o sessizliğin  sesidir  Ey güneş ne ol...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kılıç']::text[], 8.5, '{"poet":"Hakan Kılıç","poet_slug":"hakan-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gurbet-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşlukta', 'boslukta-erdogan-sarigul-m5otd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tinimiz mi (boşlukta)

yoksa 

bir anda 

tenimiz mi öldü 

dirim tohumlarının 

hiçliğe döküldüğü 

en isterik gündü 

eril göklerin 

toprağın anaç rahmini 

yıldız yıldız 

döllediği an 

tanrının 

gözyaşlarıydı kuşkusuz 

sonsuz 

isalara gebe 

bakire 

meryemin 

utangaç göğüslerinden 

tutkun 

acemi 

dudaklarımıza akan 

sonlu 

sonsuz 

gizemli 

yorumsuz 

serüvenimiz sonra 

bir devinim 

bir devinimsizlik 

bir canhıraş feryat 

bir ölümcül 

sessizlik 

beyin 

kalp 

kan 

kemik 

kim 

kimin bu 

kimliksiz kimlik 

gizemlerimizde 

istemsizce dolaşan 

dirimsel enerjimizse can 

nasıl ayrılacak 

ölü olanla 

ölü 

olmayan 

tinimiz mi (boşlukta)

yoksa 

bir anda 

tenimiz mi öldü', 'tinimiz mi (boşlukta) yoksa  bir anda  tenimiz mi öldü  dirim tohumlarının  hiçliğe döküldüğü  en isterik gündü  eril göklerin  toprağın ana...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Sarıgül']::text[], 8.5, '{"poet":"Erdoğan Sarıgül","poet_slug":"erdogan-sarigul","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/boslukta-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünü Üzerime Ört Anne', 'gokyuzunu-uzerime-ort-anne-vedat-koparan-qamoj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Mevsim üşütmekte annem havalar serin iş yerinde kaloriferler gecenin ilerleyen saatlerinde artık ısıtmaz içerisi buz kesmekte ve ben sabahın gün aydınlığının sökününde üşümekteyim sigaramda bitti senin özleminle seni düşündüm yine gittim geçmişe içimi yakan hasretine uzakları yakın kılmak vardı olmadı bir can annem olmadı üşüyorum yokluğunla) 

—Hayallerimi her baktığımda

Yitik ayaklarımda aradım

Ben gövdesi üzerinde kesik bir baştım-

Bu ayaklar benim değil mi? 

Sana uzadıkça gelemeyen

Söyle bana anne

Bu ayaklar benim değil mi? 

Neden biri hep sıcak

Neden biri hep soğuk /üşür

Nerede kaybettim

Hissetmiyorum

Söyle anne

Hep gelmelerim

Gelemem ki

Ayaklarım yok olmuş

Hangi savaşın galibiydim de yenildim

Sana hep gelmek istedim gelemedim

Sen yaşayamadığım

En büyük aşkımsın

Hiç söylemedim

Bilmedin ki annem

Hangi acı seni kardı da

Taşlık üzeri beni doğurdun

Ayrı acılardan mı geçtikte

Buluşamadık seninle

Hangi kaya hangi yosuna yuva olur da

Hangi yosun sarar hangi kayayı anne

Ah anne ah

Bu ayaklar benim değil

Bu ben miyim söyle

Kaç acı bizi doğururda yoğurur

Ayaklarım üşüyor

Ört anne

Olmayan ayaklarımı ört…

Bırak deniz çağıldasın

Söylesin dalgalar mavileri

Üşüyorum atlas bir yorgan diye

Gökyüzünü üzerime ört anne.

Bitmedi…

Vedat Koparan 05.11.2004 (06.18)', '(Mevsim üşütmekte annem havalar serin iş yerinde kaloriferler gecenin ilerleyen saatlerinde artık ısıtmaz içerisi buz kesmekte ve ben sabahı...', ARRAY['Türk Edebiyatı','Şiir','Vedat Koparan']::text[], 8.5, '{"poet":"Vedat Koparan","poet_slug":"vedat-koparan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gokyuzunu-uzerime-ort-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar kastında', 'yar-kastinda-halil-i-brahim-ozdemir-m58ph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cehennemin benzeri, mağmanın üstündeyim,

Kurtların kılığında, kuzununun postundayım,

Mahrum etme ne olur sensiz güzelliklerden,

Ölsem yar kastındayım, kalsam yar dostundayım...', 'Cehennemin benzeri, mağmanın üstündeyim, Kurtların kılığında, kuzununun postundayım, Mahrum etme ne olur sensiz güzelliklerden, Ölsem yar ka...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yar-kastinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçmasam', 'kacmasam-burhan-kucuk-0b8ju', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaçmasam

Ne zaman seni düşünsem

Önünde dururum

Tetiği çekilen tabancanın

Ah.. gözlerin

Kurşunu hiç sektirmeyen

Gözlerini ben seçmedim

Ki..vuracaktı kaçmasam

Burhan KÜÇÜK

Kdz.Ereğli-05.02.2005', 'Kaçmasam Ne zaman seni düşünsem Önünde dururum Tetiği çekilen tabancanın Ah.. gözlerin Kurşunu hiç sektirmeyen Gözlerini ben seçmedim Ki..vu...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kacmasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasip', 'hasip-halil-i-brahim-ozdemir-vsiqo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kız, bir çift söze gelin,

Oğlan, bir kurşuna damat...

Torun onca  insan arasında

Gidecek başka yer bulamaz,

Balkon demirlerinde inat...

Çağırıyorsun gel gel diye,

Ha dedi mi de gelmiyor işte

Cocukça duygular...

Senin yok mu? 

İşin gücün vardır...

Eve ekmek kahvaltılık filan...

Ocağın üstünde 

Çaydanlık fokur fokur...

Sonra

Sözün var 

Cezmi ile kelleciden sonra 

Çay içmeye gideceksin

Tatilin son, 

Mesainin  başlangıçı olmasa

İş kolay o zaman...

Bugün aybaşı  değil mi? 

Borcun alacağın var...

Manav bakkal seni bekliyor..

Nasiplenecek onlar da...

Ama kime niyet, kime kısmet

Çocukça duygularla

Alıp götürüyorlar 

Senden nasiplenecekler dururken

Nasip oluyorsun 

Be hey Hasip...', 'Kız, bir çift söze gelin, Oğlan, bir kurşuna damat... Torun onca  insan arasında Gidecek başka yer bulamaz, Balkon demirlerinde inat... Çağı...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Özdemir']::text[], 8.5, '{"poet":"Halil İbrahim Özdemir","poet_slug":"halil-i-brahim-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hasip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Şiir Bitmiştir', 'artik-siir-bitmistir-zekeriyya-bican-01yj1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söz vermişim,

Ömrüm oldukça arar sorarım seni.

Kalemimde şiirlerle, 

Emrine vermişim bu ellerimi...

Eğer bir gün gelir de, 

Artık duymazsan şiirlerimi; 

Rüzgârda kalmıştır kafesim,

Can kafesten uçmuştur...

Biliyorsun sevgimle aydınlattım hep, 

Yüreğimde olduğun yeri.

Bir çıra eyledim, 

Uğruna verdim ümitlerimi...

Eğer bir an bile karanlıkta kalırsan, 

Bil ki çıram sönmüştür.

Bir gün haber gelmezse benden, 

O zaman ümidi kes gelecekten...

Bilirsin asla şiirsiz bırakmazdım seni..

Ancak kalemler terk etmiştir ellerimi..

Düşmüştür bir hazan yaprağı dalından, 

Artık şiir bitmiştir...

O vakit bilesin ki bu vefasız dünyadan, 

Bir garip şair daha göçüp gitmiştir...', 'Söz vermişim, Ömrüm oldukça arar sorarım seni. Kalemimde şiirlerle,  Emrine vermişim bu ellerimi... Eğer bir gün gelir de,  Artık duymazsan ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/artik-siir-bitmistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Söylemediniz', 'neden-soylemediniz-zekeriyya-bican-ba0zn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani bir zamanlar ilk gençlik çağında, neydi halimiz,

Nerede o vuslata ermiş gibi şen ışıldayan gözlerimiz...

Hangi zamanda yitirildi, dimağlarda iz bırakan dilleriniz,

Şimdi bu sükût neden ey sevgili, hani şarkılı sözleriniz? ...

Başımda değişen mevsimi görmedi mi o vefalı gözleriniz,

Dağ başına kar yağmış meğer, neden söylemediniz? ...', 'Hani bir zamanlar ilk gençlik çağında, neydi halimiz, Nerede o vuslata ermiş gibi şen ışıldayan gözlerimiz... Hangi zamanda yitirildi, dimağ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/neden-soylemediniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemle Ağlayanlar', 'ozlemle-aglayanlar-zekeriyya-bican-cihoa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şeyin en iyisini yapmayı isterdim, neticeyi bilerek, 

Nice baharlar eskittim, sensiz yıllarca, ama istemeyerek.

Yapabildiğim en iyi şey ki,

Şimdi sadece ağlayabiliyorum, hiç çaba göstermeyerek.

Öyle bir zamana ermiş ki saatim,

İflas mı ediyor ne, güvendiğim o zihinsel takatim...

Hiç unutamadığım anılar terk ediyor dimağımı birer birer,

Artık kelimeler arzumla gelip yerleşmiyor cümlelerime,

Oyalıyor beni, gelip dilime takılıp kalıyor tek bir kelime...

Şimdi hasretinin esiri olmuş aklım, zihnimin zindanlarında,

Öyle rahat ağlatıyor ki beni, esir irademin zayıf anlarında...

Yenilgiyi hiç hazmedemezdi, o gururlu içsel benliğim,

Korkuyorum zamanla uçup kaybolacak bu içtenliğim.

Aman Allâh’ım kaybolmasın yeter,

Sevdiklerime tek armağanım, o içten sevecenliğim..

Artık başım ağrısa bile, söylemiyorum sevdiklerime,

Hiçbir talebim yok artık, karşılıksız bir ömür verdiklerime.

Dünyanın yükünü taşıyan omuzlarımda eskidi gitti zamanlar,

Şimdi nerdedir bilmem ki, yokluğumda özlemle ağlayanlar...', 'Her şeyin en iyisini yapmayı isterdim, neticeyi bilerek,  Nice baharlar eskittim, sensiz yıllarca, ama istemeyerek. Yapabildiğim en iyi şey ...', ARRAY['Türk Edebiyatı','Şiir','Zekeriyya Bican']::text[], 8.5, '{"poet":"Zekeriyya Bican","poet_slug":"zekeriyya-bican","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozlemle-aglayanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Direniş', 'direnis-ali-gencay-uive0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ellerimle sundum şehre yalnızlığı

Yüreğime indirdiğim acı

İndi gözlerimin akına kan,kıp kırmızı

İşte dediler,işte hain

Kaçtım,tabanlarımda ölüm

Burnu hız malılar,tırnakları uzunlar

Düştü peşime katilim arsızlar

Her nefesimde paralandı hayat

Ele vermezdi beni hiçbir şey

Tek ispiyoncum,terim acı çemen kokar

Papatyalar dermiş insanlar

Yolmak için saçlarını sıraya koyulmuşlar

Titriyor genç kız,korkusunda aşk var

Yılanmış elleriyle saçlarını okşar nine

Korkma her yürek bir gün aşka kıyar

Perçemime gizlediğim gözlerim

Dudağımda tarantula ısırığı

Yağmur yağsa diyorum içimden

Islansa toprak,ıslanmaz en kirli yerlerim

Öpemem ölürsün,dudaklarımda zehirin var

Geceleri neonlar sarar caddeleri

Şehir görülmemiş bir uykuda

Rüzgar şehvetle okşuyor beton duvarları

Ateş çiçeği düşmüş yarık arasına

Baş kaldırıyor bir tek o,rüzgara

Adamlar tutmuşlar tahta atın bacaklarını

Ölü taşıyorlar ölüm diyarına

Gözlerde birkaç damla yaş

Oysa giden kurumuş yağmurlar altında

Duruyor adımlarım

Kilitleniyorum yine köşe başında

Ayalarım güneşe dönüyor

Dilimde elif be den kalma birkaç dua

Korkuyorum toprak çok soğuksa

İğrendiriyor şehrin kükürt kokan havası

Bacalar tiryaki kesilmiş sömürüyorlar efkarı

Yaşamak zor zanaat efendim

Yaşıyorum anahtarı kaybedilmiş yalnızlığı', 'Ellerimle sundum şehre yalnızlığı Yüreğime indirdiğim acı İndi gözlerimin akına kan,kıp kırmızı İşte dediler,işte hain Kaçtım,tabanlarımda ö...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/direnis-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimdeki Tek Kurşun', 'yuregimdeki-tek-kursun-umut-ulbegi-uis1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş

sana aşkımı haykırırken yok

yağmur hiç dinmedi sen gideli

sen varsın

sensiz bir dünya yok

Her veda

bulutlu gecede kayan yıldız

puslu gözlerle izlenen adımlarda

kaybetmenin ezici korkusundayız

vedalar çoğaldıkça

denizler anlamsız

yollar anlamsız

şehirler anlamsız

vedalar sonumuz da olsa

kaybetmek yok

yeniden başlamalıyız

Hayallerimiz

çocuğun gözlerindeki ışık

evimizde

yatağımızda 

tenimizde

iki günlük mutluluk

aylara bedel

derinlerde

hayallerimiz de birbirine aşık

Sen 

her sabah ilk sigaram

her gece uykuya göz kırpışımsın

Sen gözlerimi kapadığımda 

aklıma ilk gelen

ve son gidensin

Dudağımda adın

yatağımda kokun

sen 

yüreğimdeki tek kurşunsun

Sen varsan

sensiz bir dünya yok

sen yoksan 

güneş de yansın

o tek kurşun 

canımı alsın.', 'Güneş sana aşkımı haykırırken yok yağmur hiç dinmedi sen gideli sen varsın sensiz bir dünya yok Her veda bulutlu gecede kayan yıldız puslu g...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/yuregimdeki-tek-kursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok mu Zor', 'cok-mu-zor-engin-namli-qtr1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç defa söyledim kendin ol diye

Duyduğun her sözü çektin sineye

Kılı kırk yardın hep aşktan sevgiye

Çok mu zor geliyor beni anlamak

Nedeni nedir ki bunca cefanın 

Hüznü incitiyor her bir defanın

Derdinde mi yoksa gönlün sefanın

Çok mu zor geliyor beni anlamak 

Aklına gelirse aradığın var

Ayırdığın zaman bu kadar mı dar

Ne güle ne bana bir gün baktın yar

Çok mu zor geliyor beni anlamak

Bana biraz daha sabret mi dersin

Ya bir bahtiyar ya deli edersin

Bedelini ya ben ya sen ödersin

Çok mu zor geliyor beni anlamak

ENGİN NAMLI  05.02.2005  14:15', 'Kaç defa söyledim kendin ol diye Duyduğun her sözü çektin sineye Kılı kırk yardın hep aşktan sevgiye Çok mu zor geliyor beni anlamak Nedeni ...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cok-mu-zor-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanırdım ki', 'sanirdim-ki-banu-aka-1ypju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanırdım ki 

Senden sonrası olmayacaktı

Hiçbir ateş yakmayacaktı yüreğimi

Senin yaktığın gibi

Hiç istemeyecektim senden sonra

Başka kolları

Başka dudakları 

Başkası için çarpmayacaktı kalbim

Heyecanla, tutkuyla 

Sanırdım ki 

Seni unutmam mümkün değil

Hep seni sevecektim

Ömrüm oldukça 

Öyle olmadı işte

Zaman geçiverdi üzerinden

Duygularımın

Eskidiler önce

Azaldılar sonra

Birden 

Başka duygular büyüdü içimde

Onun gözleri için

Anladım ki

Zamanla 

Herşeyi unutmak mümkün

Ormanları söküp köklerinden

Yenilerini yeşertmek mümkün

Senden başkasını sevebilmek mümkün', 'Sanırdım ki  Senden sonrası olmayacaktı Hiçbir ateş yakmayacaktı yüreğimi Senin yaktığın gibi Hiç istemeyecektim senden sonra Başka kolları ...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sanirdim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Kız', 'kucuk-kiz-banu-aka-sr6j9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçük kızın

Üzüldü baba

Hem de çok

Küçük kızın 

Ağladı baba

Hem de çok

Küçük kızın 

Büyüdü baba

Hem de çok 

Başımı dizlerine koyayım

Saçlarımı okşa 

İyi şeylerden bahset

İnandır beni

Herşeyin güzel olduğuna 

Beni

Yeniden 

Küçült baba', 'Küçük kızın Üzüldü baba Hem de çok Küçük kızın  Ağladı baba Hem de çok Küçük kızın  Büyüdü baba Hem de çok  Başımı dizlerine koyayım Saçları...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kucuk-kiz-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen....', 'sen-aysun-erat-0i0vh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gelirdin ya! ...

Birdenbire, usulca,

Çayır çimen bahar geldi deyip, yeşillenirdi.

Papatyalar dolardı arsızca kırlara.

Sonra…

Sen giderdin ya! ...

Aniden, umarsızca.

Ağaçlar üşürdü birden, yapraklarını dökerdi.

Bense…

Zamansız mevsimlerde,

Bir bahar şarkıları söyler,

Bir hüzün dolardım.

Sonra…

Birgün anladım ki…

Sen,

Bir mevsim kargaşacısısın….

02/2005', 'Sen gelirdin ya! ... Birdenbire, usulca, Çayır çimen bahar geldi deyip, yeşillenirdi. Papatyalar dolardı arsızca kırlara. Sonra… Sen giderdi...', ARRAY['Türk Edebiyatı','Şiir','Aysun Erat']::text[], 8.5, '{"poet":"Aysun Erat","poet_slug":"aysun-erat","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-509-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gördün mü Gözlerimde', 'seni-gordun-mu-gozlerimde-derin-oger-f780m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kıvılcımları yıldızlara eş

aydan parlak güneşten sıcak

buğulu büyülü ve ürpertili

bozkır sessizliği su aklığında

seni gördün mü gözlerimde

gördün mü seni güller içinde

aşk aşk kokan dağ dağ koşan

üryan ve çıplak 

deli tayların sonsuz coşkusu içinde

seni gördün mü gözlerimde

nağmelere bulanmış

göz alabildiğince sevda 

bebeğinden vurgun,sever inat inat

pınarı ki rüzgarının selinde 

seni seni gördün mü gözlerimde.................', 'kıvılcımları yıldızlara eş aydan parlak güneşten sıcak buğulu büyülü ve ürpertili bozkır sessizliği su aklığında seni gördün mü gözlerimde g...', ARRAY['Türk Edebiyatı','Şiir','Derin Öger']::text[], 8.5, '{"poet":"Derin Öger","poet_slug":"derin-oger","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-gordun-mu-gozlerimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Sevdası', 'gece-sevdasi-banu-aka-aug45', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O kopkoyu gecelerin

Bal rengi aydınlığında

Buldum seni

Gülümsüyordun gözlerinle

Nice acılar

Nice gözyaşları

Taşımıştım

Oysa ben 

Kendi gözlerimle 

Aynaya bakmaya korkardım

Ben seni

O kopkoyu gecelerin

Bal rengi aydınlığında buldum 

Gülümsüyordun gözlerinle

Aynaya baktım

Seni düşündüm

Gülümsedim

Yüreğimde izi olmadan

Gece sevdasının', 'O kopkoyu gecelerin Bal rengi aydınlığında Buldum seni Gülümsüyordun gözlerinle Nice acılar Nice gözyaşları Taşımıştım Oysa ben  Kendi gözle...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gece-sevdasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Yaşı Gaziantepli bestekar-şair Erol Güngör şiiri', 'gonul-yasi-gaziantepli-bestekar-sair-erol-gungor-siiri-erol-gungor-1emzu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül yaşı yirmi, gözler âşıksa

                         Takvim yaşı üç kat, olsa ne çıkar

                         Hayatın anlamı, sevmek sevilmek

                         Mutluluk göz yaşı, her yaşta akar..

                         Yeter ki sevilen, sevmeyi bilsin

                         Saat bile durur, mutlu zamanda

                         Dövünmek, övünmek, kenarda dursun

                         Hayat boyu aşktır, ömre kumanda..

                         Geçse de ilk bahar, yazda mutlu ol

                         Unutma sonbahar, ikinci bahar

                         Kışlar gizem dolu, aşk demli çaydır

                         Sevilip sevene, kış bile bahar..

                                        (3.2.2005)', 'Gönül yaşı yirmi, gözler âşıksa                          Takvim yaşı üç kat, olsa ne çıkar                          Hayatın anlamı, sevmek s...', ARRAY['Türk Edebiyatı','Şiir','Erol Güngör']::text[], 8.5, '{"poet":"Erol Güngör","poet_slug":"erol-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonul-yasi-gaziantepli-bestekar-sair-erol-gungor-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsimler Gibi', 'mevsimler-gibi-banu-aka-vf4ux', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğin sonbahar senin

Yapraksız bir ağaç

Bu mevsimde bile

Yemyeşil durduğunu

Sandığın

O ulaşılmaza sevdalı

Benden beter ümitsiz

Ellerin kış senin

Isıtamaz ellerimi

Kendi buzlarını çözmeden

Bembeyaz uzun bir kış gecesisin

Karanlığı olmayan

Gözlerin bahar senin

Kuşlar gibi gülümseyen

Gözlerinde bir bahar dalı

Gözlerinde bir kelebek 

Uçup konsa 

Gözlerime

Ellerime 

Yüreğime 

Sonra da hep yaz olsa 

Beraber erisek 

Sıcak kumlarda 

Güneş ışığı gibi', 'Yüreğin sonbahar senin Yapraksız bir ağaç Bu mevsimde bile Yemyeşil durduğunu Sandığın O ulaşılmaza sevdalı Benden beter ümitsiz Ellerin kış...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mevsimler-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Gelme', 'geri-gelme-banu-aka-q8x3i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni böyle görmek istemiyorum

Bir elinde gözyaşları

Diğerinde hüzün

Dudaklarının kenarında

Alışılmadık çizgiler

Sesin çatallı

Ümitsizliğin acısı gözbebeklerinde

Omuzların böylesine çökmemeli

Söyleyecek birşeyler kalmış olmalı

Susmamalısın

Seni böyle görmek istemiyorum

Gözlerimde

Giderken gözlerindeki

Bakışın kararlı ifadesi kalsın

Yüreğinin sevgisizliği

Gözyaşlarımı silmeyişin 

Arkanı dönüp gidişin

Kalsın aklımda

Kalsın ki

Sana yeniden kanmayayım

Aynı hatayı

Bir kere daha yapmayayım 

Bana dönme 

Geri gelme

Bir kez daha benim olma 

İstemiyorum', 'Seni böyle görmek istemiyorum Bir elinde gözyaşları Diğerinde hüzün Dudaklarının kenarında Alışılmadık çizgiler Sesin çatallı Ümitsizliğin a...', ARRAY['Türk Edebiyatı','Şiir','Banu Aka']::text[], 8.5, '{"poet":"Banu Aka","poet_slug":"banu-aka","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/geri-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-adnan-mehmet-tufekci-xzn0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara bembeyaz dost.,

ayazıda bilirsin,

hani şu kutuptan olan.

güleç yüzlü,

deniz gözlü can.,

ne soğuk,

ne de canan

   en zoru sensizlik be dost.

gittin gideli,

çok şey yaşadı bu insan.

aşık olmak istiyorum derdim de,

kızardın.

zorla güzellik olmazmış,

aşkta olmuyor,

aşıkta insan.

elimde bir ayakkabı

    Sindrella aradım.

kim kaybetmiş ki,

ben bulayım.

ayak uyar,

taç uymaz.,

anladım ki masalmış tüm bunlar.

hak edene,

hak ettiğini vermek gerek.,

köylü kızı 

      köyünde kalmalı ha dost.

tasa çok

   anlatmakla bitmez.

gamı kederi de nasipleniriz,

kiminden az,

kiminden çok.

parasızlıkla da dost olduk,

bende güzel günler az,

çok ise sende gönder biraz.

o kent de soğuktur,

senin sıcaklığın yetmez,

ben gerek,

biz gerek.

günler akıp gidiyor,

birşeyler alıp,

birşeyler getiriyor.

seni de getirecek bir gün,

ay misali,

güneş misali.

her şey fani.,

Yunus''un dediği gibi,

malda yalan,

   mülkte yalan.

bâki olan sevgi,

bizde de çoktur,

ben dağıyorum,

almasını bilen ise az.

mala mülke

   arsız olurda insan,

sevgiye olmaz.

vatan borcu,

namus borcu demiş atalar.

borcumuz borç ama

onda da var imtiyaz.

sonumuz nereye varacak dost.

dürüstlük,

doğruluk hak getire.

teknoloji ile makineleşti insan.

eskiden sevgi sunulurdu

     gittiğimiz yerlerde.,

şimdi ise; 

     Brezilya dizisi,

     yeni vizyon film.

vefasızım bu ara,

kendime bile vefasız,

uğra dediğin yerlere uğrayamadım,

kusura bakma dost.

idealler var ilerde,

onlarla meşgulüm,

uzanacağım ama

   bir de çelme takanlar olmasa.

mehter takımı gibi,

iki ileri, bir geri.

onlar Viyana önünden döndüler,

ben dönmem,

biz dönmeyiz ha dost.

sevgimi yolluyorum,

Ankara kadar beyaz.

özlemlerim,

iyi dileklerimle 

    misafir et biraz.', 'Ankara bembeyaz dost., ayazıda bilirsin, hani şu kutuptan olan. güleç yüzlü, deniz gözlü can., ne soğuk, ne de canan    en zoru sensizlik be...', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/dost-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fena mı Olur', 'fena-mi-olur-murat-demir-njgfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdalı yüreğim dönmeden çöle

Boynumu bükmeden poyraza, yele

Mademki olmuşum sana kul köle

Ellerimden tutsan fena mı olur

Çilemin üstüne çile ekmeden

Sağımı solumu yıkıp dökmeden

Daha fazla bu can hasret çekmeden

Yanımda bulunsan fena mı olur

Ömrümün gazeli dökmeden beni

Başka biri gelip görmeden seni

Sezip içimdeki şu dertlerimi

Ufaktan paylaşsan fena mı olur

Kıyamet mi kopar bir ben gülende

Seni ölümüne sayıp sevende

Üç günlük dünyanın üç gününde de

Beraber yaşasak fena mı olur!', 'Sevdalı yüreğim dönmeden çöle Boynumu bükmeden poyraza, yele Mademki olmuşum sana kul köle Ellerimden tutsan fena mı olur Çilemin üstüne çil...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fena-mi-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Dönümü', 'gun-donumu-adnan-mehmet-tufekci-1pesm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güneş veda etti,

ayçiçeğinin boynu bükük,

kuşlar son resitalinde.

dünya renk değiştiriyor,

her nesne siyaha yolculukta.

dalgalar hırçın,

iskele yalnız.

sona sefer sayıyor 

umuda giden taka.

hava da soğuyor,

keşke,

    yanımda olsan,

    sana sarılsam.', 'güneş veda etti, ayçiçeğinin boynu bükük, kuşlar son resitalinde. dünya renk değiştiriyor, her nesne siyaha yolculukta. dalgalar hırçın, isk...', ARRAY['Türk Edebiyatı','Şiir','Adnan Mehmet Tüfekci']::text[], 8.5, '{"poet":"Adnan Mehmet Tüfekci","poet_slug":"adnan-mehmet-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gun-donumu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesi Vardır ki', 'oylesi-vardir-ki-bayram-tunca-zbhs1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öylesi vardır ki, sevgiyle ısıtır evini

Her gün dört gözle bekler sevdiğini

Hayal edip/aramışımdır böyle birini

Ne olur, biliyorsanız söyleyin yerini

05.02.2005-02:05', 'Öylesi vardır ki, sevgiyle ısıtır evini Her gün dört gözle bekler sevdiğini Hayal edip/aramışımdır böyle birini Ne olur, biliyorsanız söyley...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oylesi-vardir-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhatabım Değilsin', 'muhatabim-degilsin-mustafa-dilki-46pnv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını telafuza dilim varmıyor artık 

Bitti artık aşkımız muhatabım değilsin

Şu gönül defterimin senli sayfası yırtık

Yüreğimi sızlatan ıstırabım değilsin

Caydım senin sevginden ve de aşkından caydım

Şahsıma sarf edilmiş ben ne yalanlar duydum

Aydım artık güzelim artık gerçekten aydım

Şu başımı döndüren o şarabım değilsin

Belli ki kalbindeki hırçın fırtına dinmiş

Nazarımda ay yüzün solgun güllere dönmüş

Gözlerinde sevdanın o pırıltısı sönmüş

Ve yıldız ve yakamoz ve mehtabım değilsin

Sözlerin bıçak gibi kalbimi bine böldü

Oysa senle bahardım sensiz hayatım çöldü

Bana şiir yazdıran ilham perisi öldü

Ve şarkım ve şiirim ve kitabım değilsin

Göresi gözüm de yok tutulduğum gözleri

Yüreğimde kanayan iltihabım değilsin

Ölenedek unutmam o kırıcı sözleri

Muhatabım değilsin muhatabım değilsin', 'Adını telafuza dilim varmıyor artık  Bitti artık aşkımız muhatabım değilsin Şu gönül defterimin senli sayfası yırtık Yüreğimi sızlatan ıstır...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/muhatabim-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemşire', 'hemsire-mustafa-dilki-spg7g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak doktor bırak derman değilsin 

Benim tek ilacım çarem hemşire

Bırakta kalbime kendi eğilsin

Bak nasıl kanıyor yarem hemşire

Senin için kalbi yaslı dediler 

Kapandı muhabbet faslı dediler 

Sana efsanevi Aslı dediler 

Benim bir adım da Kerem hemşire 

İlk önce gözlerin girdi düşüme 

Sonra kan karıştı her gözyaşıma

Öyle bir bela ki geldi başıma 

Ne bir kanser ne de verem hemşire 

Bir sevda ki karaların karası

Birsevda ki yüreklerin yarası

Benim aşkım hayat ölüm arası

Son bir kez yüzünü görem hemşire', 'Bırak doktor bırak derman değilsin  Benim tek ilacım çarem hemşire Bırakta kalbime kendi eğilsin Bak nasıl kanıyor yarem hemşire Senin için ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hemsire-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Böyleyim İşte', 'ben-boyleyim-i-ste-huseyin-erdogan-vzbny', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ben ömrümce

hiç öğrenemedim sevmesini

ya delicesine sevdim birini

ya da hiç tutmadım ellerini

zaten bu güne değin beni de

çılgınca sevdiklerim terk etti

bundan sonra da seversem eğer

taparcasına seveceğim yine de

beni bırakıp gideceğini bilsem de

ne yapayım ben böyleyim işte 

artık değişemem ki mahşerde bile

                                 07.02.2005', 'ben ömrümce hiç öğrenemedim sevmesini ya delicesine sevdim birini ya da hiç tutmadım ellerini zaten bu güne değin beni de çılgınca sevdikler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-boyleyim-iste-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Sabahı', 'bayram-sabahi-mustafa-dilki-3mp2a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş tepelerden sancıyla doğar

Asker ocağında bayram sabahı

İçimi bin türlü acıya boğar

Asker ocağında bayram sabahı

Ne varsa kesilir neşeden hazdan

Şeker şerbet geçmez olur boğazdan

Dökülür gözümden yaşlar birazdan

Asker ocağında bayram sabahı

Tanıdık dost sesi kulaklarımda 

Ayrılık bestesi dudaklarımda 

Hayalim memleket sokaklarında 

Asker ocağında bayram sabahı

Yavukludan gelen sır selamına 

Bir kokulu mektup bir selamına 

Kaç şarjör boşalır yar selamına 

Asker ocağında bayram sabahı

Yanında istersin sırdaşlarını

Ananı, babanı gardaşlarını 

Aşk olsun tutana gözyaşlarını 

Asker ocağında bayram sabahı', 'Güneş tepelerden sancıyla doğar Asker ocağında bayram sabahı İçimi bin türlü acıya boğar Asker ocağında bayram sabahı Ne varsa kesilir neşed...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bayram-sabahi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana bir masal anlat', 'bana-bir-masal-anlat-emine-yilmaz-qdq1o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimsenin aldatmadığı

İçimizin dışımızın bir olduğu

Hayal etmekten korkmadığımız

Ağlamaktan utanmadığımız

İçinde çocukluğumun olduğu

Ümit biriktirdiğimiz günlerden

Çamurdan evler yapıp

İçini sevgiyle  yerleştirdiğimiz günlerden

Hayatın basit ama anlamlı

Küçük fakat değerli olduğu günlerden

Yıldızları tek  tek  sayıp

Işığında dans edebildiğimiz 

Karanlığından ürküp,

Sabaha gözyaşı dizmediğimiz gecelerden olsun

Varsın yalan olsun ne çıkar

Yeter ki yüreğimi avutsun.', 'Kimsenin aldatmadığı İçimizin dışımızın bir olduğu Hayal etmekten korkmadığımız Ağlamaktan utanmadığımız İçinde çocukluğumun olduğu Ümit bir...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-bir-masal-anlat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
