INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben yalan değilim hayatınızda', 'ben-yalan-degilim-hayatinizda-emine-yilmaz-q5olz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi anne dedi gögsüne yasla

Kimi abla dedi derdimi anla

Biri evlat dedi dogurdum seni

Kimse ben olarak görmedi beni

Dert dinledim sır sakladım

Herkese ayrı yoldaştım

Kıyamadım, kovamadım

Bir yalandım ve yalan kaldım

Kimse bilmesede kalbim var benim

Her gece gizlice ağlar gözlerim

Bir tatlı söz için neler veririm

Sevdiğim kadar sevilmek isterim

Kırılırım anlatamam

İçim yanar paylaşamam

Dert oldunuz yüregimde

Yine de sizsiz yapamam

Bırakın ben bende beni bulayım 

Sıfatlarınızdan uzak kalayım

Her şeyden evveli ben bir insanım

Size ait gibi görmeyin beni

Önce insan sonra benim sonrada kadın

Beni bir yalan gibi hayatınıza karıştırmayın

Belki hepinizin haklı beklentileri var benden

Analık, evlatlık, ablalık eşlik,

Fakat arasırada olsa bana sadece ben oldugum için bakın

Ve benimde kendime ait bir kimliğim oldugunu unutmayın', 'Kimi anne dedi gögsüne yasla Kimi abla dedi derdimi anla Biri evlat dedi dogurdum seni Kimse ben olarak görmedi beni Dert dinledim sır sakla...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-yalan-degilim-hayatinizda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Sarısı', 'hazan-sarisi-mustafa-dilki-2g0im', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimim sonbahar yaprak dökümü

Gün be gün artıyor gönül ağrısı

Omzuma yüklendim keder yükümü

Şimdi bütün renkler hazan sarısı

Kirpiklerim ıslak gözüm yaş gibi

Yüreğim yaralı bağrım taş gibi

Bütün sevdiklerim göçmen kuş gibi

Şimdi bütün renkler hazan sarısı

Ne denizim deniz ne göğüm mavi

O allı, yeşilli, dallarım hani

Zaman yüreğimi vurmuş bir cani

Şimdi bütün renkler hazan sarısı 

Bir buruk şarapla bir şişe meyle

Dolaş bir hüzzamda tamburla neyle

Gökkuşağı bana merhamet eyle 

Şimdi bütün renkler hazan sarısı', 'Mevsimim sonbahar yaprak dökümü Gün be gün artıyor gönül ağrısı Omzuma yüklendim keder yükümü Şimdi bütün renkler hazan sarısı Kirpiklerim ı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hazan-sarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben yalan değilim hayatınızda-1', 'ben-yalan-degilim-hayatinizda-1-emine-yilmaz-lfsgr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi anne dedi gögsüne yasla

Kimi abla dedi derdimi anla

Biri evlat dedi dogurdum seni

Kimse ben olarak görmedi beni

Dert dinledim sır sakladım

Herkese ayrı yoldaştım

Kıyamadım, kovamadım

Bir yalandım ve yalan kaldım

Kimse bilmesede kalbim var benim

Her gece gizlice ağlar gözlerim

Bir tatlı söz için neler veririm

Sevdiğim kadar sevilmek isterim

Kırılırım anlatamam

İçim yanar paylaşamam

Dert oldunuz yüregimde

Yine de sizsiz yapamam

Bırakın ben bende beni bulayım 

Sıfatlarınızdan uzak kalayım

Her şeyden evveli ben bir insanım

Size ait gibi görmeyin beni

Önce insan sonra benim sonrada kadın

Beni bir yalan gibi hayatınıza karıştırmayın

Belki hepinizin haklı beklentileri var benden

Analık, evlatlık, ablalık eşlik,

Fakat arasırada olsa bana sadece ben oldugum için bakın

Ve benimde kendime ait bir kimliğim oldugunu unutmayın', 'Kimi anne dedi gögsüne yasla Kimi abla dedi derdimi anla Biri evlat dedi dogurdum seni Kimse ben olarak görmedi beni Dert dinledim sır sakla...', ARRAY['Türk Edebiyatı','Şiir','Emine Yilmaz']::text[], 8.5, '{"poet":"Emine Yilmaz","poet_slug":"emine-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ben-yalan-degilim-hayatinizda-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemedi Kaltak', 'yemedi-kaltak-mustafa-dilki-yguco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok peşinden koştum çokça yoruldum

Ya merhamet dedim yemedi kaltak

Kirpiğinden darbe yedim vuruldum

Bu cinayet dedim yemedi kaltak

Çok uyanık birileri öğretmiş 

Çok çapkına kan kusturmuş diretmiş

Hem sevin sevilin diye emretmiş

Bak din-ayet dedim yemedi kaltak

Üstünde ne varsa çıkarıp attı

Sorgusuz sualsiz yanıma yattı

Ben ne umuyordum o ne anlattı

Bu ihanet dedim yemedi kaltak

Doldum taştım yıktım geçtim bendimi

Tutamadım yeminimi andımı

Gider isen öldürürüm kendimi 

Bilki şayet dedim yemedi kaltak

Fırtınaydı yelkenleri indirdim

Gidiyordu merdivenden döndürdüm

Allem ettim kallem ettim kandırdım 

En nihayet dedim yemedi kaltak', 'Çok peşinden koştum çokça yoruldum Ya merhamet dedim yemedi kaltak Kirpiğinden darbe yedim vuruldum Bu cinayet dedim yemedi kaltak Çok uyanı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dilki']::text[], 8.5, '{"poet":"Mustafa Dilki","poet_slug":"mustafa-dilki","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yemedi-kaltak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
