INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği', 'kir-cicegi-yavuz-agir-iqpy7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben kırların açan gülüyem

Elden ele dolaşırım.

Rüyaların bitmez süsüyem

Dilden dile dolaşırım...

Demet demet koparırlar

Aşıklara aparırlar.

Vazolara süs yaparlar

Ben kırların çiçeğiyem...

Koşun,koşun gelin bana

Lale sümbül,nergiz alın

Tüm dostlara haber salın

Ben kırların çiçeğiyem....', 'Ben kırların açan gülüyem Elden ele dolaşırım. Rüyaların bitmez süsüyem Dilden dile dolaşırım... Demet demet koparırlar Aşıklara aparırlar. ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kir-cicegi-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Yolun Yolcuları', 'ayni-yolun-yolculari-serkan-kukrer-d4kds', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Aydoğan''a-

Bugün                                                              

Haziran dokuz

Saat yirmidört otuz

Saat yirmidörtotuz

Her gün hasret,

Her gün suskunuz.

Çıkarıp göğüs kafesimizden sevgiyi

İnsanlara uzatıyoruz.

Neyimiz vardı ki, neyimiz olacak? 

Yokluktan geldik, yokluğa gidiyoruz.

                                                                09.06.1998', '-Aydoğan''a- Bugün                                                               Haziran dokuz Saat yirmidört otuz Saat yirmidörtotuz Her gün...', ARRAY['Türk Edebiyatı','Şiir','Serkan Kükrer']::text[], 8.5, '{"poet":"Serkan Kükrer","poet_slug":"serkan-kukrer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayni-yolun-yolculari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Saklayamıyorum', 'ben-saklayamiyorum-yasin-ozcan-tgqqx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben saklayamıyorum 

İşte

Gözyaşlarımdan başka bir şeyi

Şu dünyada bir tek

Gülüşlerim yalan

Acım büyük te olsa

Gururumdur beni ayakta tutan

Baksana o siyah gözlerin bile

Yalnız yalnız

Bana haram

Ben yalnız kalacak adamım

Satmayı bilmediğim için

Bu kentte

Ben kırılacak adamım

Güvendiğim için herkese

Ben aç kalacak adamım

Haram bilmediğim için 

Yeryüzünde

Ve ben

Cehennemlik adamım

Taparcasına bağlandığım için

Gözlerine.......', 'Ben saklayamıyorum  İşte Gözyaşlarımdan başka bir şeyi Şu dünyada bir tek Gülüşlerim yalan Acım büyük te olsa Gururumdur beni ayakta tutan B...', ARRAY['Türk Edebiyatı','Şiir','Yasin Özcan']::text[], 8.5, '{"poet":"Yasin Özcan","poet_slug":"yasin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-saklayamiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Dogusuna Küsmüs Mevsimler', 'kar-dogusuna-kusmus-mevsimler-ozenc-yasar-o70nf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hüzünle kar düşüyor gözlerime

Yürüdüğüm sokaklarda adres arıyor

Kapımı çalan hasret

Yüreğinin yandığını söyler acılar

Ellerimi gizliyorum tetik çeken akşamlarda

Kar değince sevgi erir küsmüş mevsimlerde

Okşar doğuşunu yaprak güneşin

Ayrılıklar geceden düşer yollara

Seninle camın önündeyim kayıpları oynuyorum

Uzak bir ülkenin

Doğuşuna küsmüş mevsimlerde

İzliyorum karın oynayışında

Şiirime düş düşer nazarında erir inadına gölgem

Hep birlikte var olduğumuzu sanırdım

Kar topu oynayan siper kirpiklerinde

Bakamadık kar yağışına özlemsiz

beni arıyor ağlamalarda eylemciler

Düşer sürgün gecelerim Sokaklara

On iki yılsız damarlarımda solan

Bir çınarın gölgesi gibi

Esintiyle uyanır uykum uyandığımda

Bir tek sen varsın umut benimle

hasret yerine yağmurla gündüzlerim

Kar doğuşuna küsmüş mevsimlerde

Uyandır gökyüzünü kızgın toprak

Sevdalı göğsümde silsin acıları

Süzülsün baharın koynunda gecem

Yılların çekildiği hayata

Sana uzanan elimin içinde değilsin

Sen dışarıdasın mevsimsiz

21. 2. 01.    Berlin.', 'Hüzünle kar düşüyor gözlerime Yürüdüğüm sokaklarda adres arıyor Kapımı çalan hasret Yüreğinin yandığını söyler acılar Ellerimi gizliyorum te...', ARRAY['Türk Edebiyatı','Şiir','Özenç Yaşar']::text[], 8.5, '{"poet":"Özenç Yaşar","poet_slug":"ozenc-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kar-dogusuna-kusmus-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-hatice-bediroglu-w41x5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O çok sevdiğin denizi

Martıların... 

Çığlıklarıyla beraber 

Sana göndermek istedim 

Gözlerini kapa şimdi 

Ve denizin sesini dinle

Kokusunu içine çek

Duyduğun koku ikimizin 

Mis gibi aşk kokusu 

Deniz sensin 

Gözlerini kapa şimdi 

Martıların seslerini dinle

Karınlarını doyurmak için 

Nasıl da kavga ediyorlar

Balıkçı da 

Balık tutma sevdasıyla 

Ağlarını atmaya hazırlanıyor 

O da ekmek derdinde 

Yeni umutlara gebe

Güzel bir gün başlıyor

Balıkçı denize sevdalı

Bense sana bir tanem 

Ne balıkçı 

Denizsiz yaşayabilir

Ne de ben sensiz

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005

www.haticebediroglu.net', 'O çok sevdiğin denizi Martıların...  Çığlıklarıyla beraber  Sana göndermek istedim  Gözlerini kapa şimdi  Ve denizin sesini dinle Kokusunu i...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bu-sabah-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solmayacak Güneşimsin', 'solmayacak-gunesimsin-alaettin-isik-2b8gc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerede bir türkü duysam, yanık yanık

İçinde senden bir şeyler buluyorum..

Kafamı kaldırsam göklere baksam,

Hep seni, hep seni görüyorum..

Zor olmasın, resmin  karşımda olsun,

Yine ben sendeyim, yüreğinin içinde.

Ve sen ne dersen de, yangınlar benimle,

Sonunda kalan külleri ise seninle..

Kader bu, denmez fazla bi şey,

Yürek bu yaşandıkça bilenir,

Kelimeler yetmez, boğazım kurur da,

Resmin her an gözümde şekillenir..', 'Nerede bir türkü duysam, yanık yanık İçinde senden bir şeyler buluyorum.. Kafamı kaldırsam göklere baksam, Hep seni, hep seni görüyorum.. Zo...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/solmayacak-gunesimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şehir Var', 'bir-sehir-var-yasin-ozcan-dzc29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir şehir var uzakta

Hayallerimi

En temiz yalanlarımı

Göz yaşlarımı gizlediğim

Bir şehir var uzakta

Yalnız seni sevdiğim günlerim

En yürekten açan güllerim var

Yalnız sana doğar güneşim

Yıldızlar sana parlar

Birde sen benim için

Bu koca şehre tek varisim

Şarkılarını yazdığım şehrin

Sokaklarına kan akıttığım gözlerimden....

Bir şehir var uzakta

Ufkunda asılı GELİNLİĞİN...', 'Bir şehir var uzakta Hayallerimi En temiz yalanlarımı Göz yaşlarımı gizlediğim Bir şehir var uzakta Yalnız seni sevdiğim günlerim En yürekte...', ARRAY['Türk Edebiyatı','Şiir','Yasin Özcan']::text[], 8.5, '{"poet":"Yasin Özcan","poet_slug":"yasin-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-sehir-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Limanlar Uzaklarda Büyütür Beni', 'limanlar-uzaklarda-buyutur-beni-ozenc-yasar-ahuiy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağlara sipersiz baktığımda

Günler yitik bir kent olur kayıp limanlarda

Kurşun şarap renginde vurulmuştu yıldızsız gecelerde

Yorgun geçerdi gemiciler deniz feneriyle

ağlardık su sesinde onlara bakınca gözlerimiz

Çoğalırdık göllere dökülürcesine

Uyurdu çığlık sessizse yaşam

Limanlar uzaklarda seni büyütür ülkem

Deniz mavisi bulutlar

uyandırın ölümleri 

rüzgar aralasin 

o çok gülüşlü yüzünü

dağlara düşen

bir göz öpüyor 

ağlayan gözyaşlarıni

uyan kardeş teninde

esmez bulut olur zaman

tutar ellerimizi çıplak duvar neminde

düş limani uzakları büyütür sürgün gözde beni

hasret eritir avuçlarımda

kül kokusu evlerin 

yürüyorum kentin kirintilarinda

hadi sende gel 

uzaklarda 

çocuklugum ol

31.10.2000. Berlin', 'Dağlara sipersiz baktığımda Günler yitik bir kent olur kayıp limanlarda Kurşun şarap renginde vurulmuştu yıldızsız gecelerde Yorgun geçerdi ...', ARRAY['Türk Edebiyatı','Şiir','Özenç Yaşar']::text[], 8.5, '{"poet":"Özenç Yaşar","poet_slug":"ozenc-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/limanlar-uzaklarda-buyutur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karışığım', 'karisigim-gozde-hatiboglu-7hap2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden kalma bir melodiyle dalar ya bazen gözlerin yalnızlığa, işte öyleyim. 

İlk aşık olduğum güne gitti yüreğim. 

Ilık rüzgar, sıcak kumsal ve dalgaların sesi geldi aklıma. 

Seni ilk tanıdığım yerde çocukluğum var benim.

Şimdi ilk gençliğimin üstüne kurdum aşka dair tüm senaryolarımı. 

Öğrendiğim her yeni acı senden kalanları anımsattı yıllarca. 

Kaybettim seni sonra. 

Kimdin sen? 

Yıllar geçti ve eskitti galiba. 

Farklı tanışıklıklar, her seferde yaşanacak ve öğrenecek bir şey var dememe neden oldu. 

Yaşadım, öğrendim! 

Acıya yakın, aşka dair birikimlerle düşe kalka yürüdüm, büyüdüm. 

Şimdi geçtiğim yollara bakıyorum da; baştan beri aynı. 

Sadece mevsimler değişmiş.

Yine tutkuluyum aslında. 

Yine yüreğim çırılçıplak duygular karşısında. 

Ve yine yaralanmaya hazır, eğer yaralayan değiyorsa. 

Hislerim aynı. 

Emin olmak adına denemeler var belki. 

Farklı olan; biraz daha korkuya yakın olmam. 

Çünkü; 

Gidenlerin ardından kalamıyorum artık, 

Uzun oluyor yeniden yapılanmak. 

Ya da giden olmak, 

Zor geliyor vicdanı bastırıp üzgünüm demeye çalışmak.

Şimdilerde ne olduğunu bilmediğim hisler var sol yanımda; 

Karışığım! 

Bir yanım isterken bir yanım karşı koymada. 

Alışkanlıkların farkındayım yalnızca. 

Doğru zamanı bekliyor çocuk yüreğim. 

Duygusal tarafımı çıkartacak bir çaba belki de. 

Beklemeye aldım; suskunum. 

Yalnızlığımı öğreniyorum galiba. 

Savaşım kendimle, aşka karşı dursun diye. 

Öyle sağlam örülmüş ki duvarlar yıllarla, 

Hakkı var suskunluğa. 

Ve güç eğer aşksa; 

Yıkılır duvarlar karşısında..

(3.ekim.2004)', 'Eskiden kalma bir melodiyle dalar ya bazen gözlerin yalnızlığa, işte öyleyim.  İlk aşık olduğum güne gitti yüreğim.  Ilık rüzgar, sıcak kums...', ARRAY['Türk Edebiyatı','Şiir','Gözde Hatiboğlu']::text[], 8.5, '{"poet":"Gözde Hatiboğlu","poet_slug":"gozde-hatiboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/karisigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlı Akşamlar', 'karli-aksamlar-volkan-yoruc-5jped', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutuluverir ayım güneşim sevdamla

Gölge eyler rüyalarıma

Yıldızlarımı bulutlar sarmalar gibi

Sevdamı göremez olurum bu karlı akşamlarda

Doğan güneşe hasret kalmışım

Sevdama kalır gibi

Aşk içinde yalnızlığa sarılmışım

Umutla ışıldayan ateş böcekleri gibi

Şimdi yakmışım sevda türküsü bağrıma

Mısra mısra yazmışım seni anılarıma

Artık sen unutur olmuşun beni

Sevdamı göremez olmuşum bu karlı akşamlarda', 'Tutuluverir ayım güneşim sevdamla Gölge eyler rüyalarıma Yıldızlarımı bulutlar sarmalar gibi Sevdamı göremez olurum bu karlı akşamlarda Doğa...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karli-aksamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satma Düslerini', 'satma-duslerini-ozenc-yasar-l01rf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SATMA DÜŞLERİNİ 

Düşlerinde silip atma

Güzel günlere olan inancını

Her sabah dokunsan güne

Gün güle biliyorsa hayata

büyümemiş çocukluğun

farkında

Biz kavgada seviyoruz 

Unutmadan yüreğimizi

Bunca acılara omuzlarımızda yükken

İnatla sevdim gözlerindeki bakışı

Satma düşlerini

Bir türküydü  sıcak yaz akşamlarında

Nehir kokusu akardı her vuruluşta

Uzak kentlere doğum olur 

akardı 

ölüm yabancı kaldığımda sana

senden çalıyorum kendimi her akşam

Ağlayışlarımla  sana dönemiyorum

Yalnız bıraktım sancılı özlemlerde

gülüşlerinde isyanların 

pazarlarda köle olmuş oğul

satılıyor aglamalarin gülmelerin

Devrildi yürekler atom parçası

Dalgalar dil değil döl yatağında lodos 

Sıkma düşlerini tut ellerinle

Köy meydanında vapur gezintileri 

Oturup susacaksın ışıklar altında

yol kenarına ağaçlar gölge olmuşken

satma düşlerini

sesiz duvar olan yüreklerde

17.08.01  Berlin', 'SATMA DÜŞLERİNİ  Düşlerinde silip atma Güzel günlere olan inancını Her sabah dokunsan güne Gün güle biliyorsa hayata büyümemiş çocukluğun fa...', ARRAY['Türk Edebiyatı','Şiir','Özenç Yaşar']::text[], 8.5, '{"poet":"Özenç Yaşar","poet_slug":"ozenc-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/satma-duslerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryat', 'feryat-eylem-ozdemir-sne8b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykuyamı hasret  bu gözler? 

Yoksa senli  günlere uyanışamı? 

Boşluğamı bu sözler? 

Yoksa sana yalvarışamı? 

Dön gel artık,

Dön gel bu gönlümün baharı.

Gözlerinden bir ışık ver bana,

Dünyamı aydınlat.

Ve içinden bir nefes,

Yanan kalbimi ferahlat.', 'Uykuyamı hasret  bu gözler?  Yoksa senli  günlere uyanışamı?  Boşluğamı bu sözler?  Yoksa sana yalvarışamı?  Dön gel artık, Dön gel bu gönlü...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/feryat-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstesende Yapamazsın', 'i-stesende-yapamazsin-eylem-ozdemir-ox94q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı yine, saat kimin umurumda.

İliklerime kadar hüzünlüyüm ve iliklerime kadar rüzgar.

Rüzgardan olsa gerek, yüreğim inceden inceye sızlar.

Aklım bir karış havada, orada ise kıyamet kopar.

Uzatsam ellerimi, bırakma desem, tutarmısın onları? 

Gözlerime bakarmısın yine sıcak sıcak? 

Paylaşırmısın benimle yine aynı sevdayı? 

Kalbime yazdığım seni orada saklamama izin verirmisin? 

Olmaz! İstesen de yapamazsın.

Duyguların kıyamasa, yüreğin titrese de.

Mantığına söz geçirmek imkansızdır bilirim.

Titreyen eller, deli gibi çarpan bir yürek yetmez.

Aşkta mantık aranmaz, mantık ise aşkı sevmez

Yüreğin hissetse de mantığın kabul etmez.', 'Gecenin bir yarısı yine, saat kimin umurumda. İliklerime kadar hüzünlüyüm ve iliklerime kadar rüzgar. Rüzgardan olsa gerek, yüreğim inceden ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istesende-yapamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-eylem-ozdemir-0s78p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçti güzel  günler, 

Limandan az  önce  ayrıldı gemi, 

Geride  kalanlar  hüznün  eseri,

Limanda  beklese de  yalnız  serseri,

Kimsenin  suçu değil.

Bu onun eseri', 'Geçti güzel  günler,  Limandan az  önce  ayrıldı gemi,  Geride  kalanlar  hüznün  eseri, Limanda  beklese de  yalnız  serseri, Kimsenin  suç...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/serseri-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doydum Elhamdilillah', 'doydum-elhamdilillah-i-shak-ozlu-7urr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaradanım bir kalp vermiş,

Sevgi doldurayım diye.

Yazgımada hasret yazmış,

Kavuşmak hayal,niye.

Kalbin gıdası sevgiyse,

Aç bırakmak niye,

Beslenecekse acıyla,

Doydum Elhamdilillah.', 'Yaradanım bir kalp vermiş, Sevgi doldurayım diye. Yazgımada hasret yazmış, Kavuşmak hayal,niye. Kalbin gıdası sevgiyse, Aç bırakmak niye, Be...', ARRAY['Türk Edebiyatı','Şiir','İshak Özlü']::text[], 8.5, '{"poet":"İshak Özlü","poet_slug":"i-shak-ozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/doydum-elhamdilillah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-abdullah-apak-7ycp6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni Arıyorum

Ben seni seviyorum,

Ben seni özlüyorum

Ben seni arıyorum

Bu şehrin ıssız sokaklarında.

Sokaklar ıssız,

Sokaklar sessiz

Sokaklar sensiz,

Ben seni arıyorum

Bu şehrin ıssız sokaklarında

08.02.2005 23.08 MERSİN', 'Seni Arıyorum Ben seni seviyorum, Ben seni özlüyorum Ben seni arıyorum Bu şehrin ıssız sokaklarında. Sokaklar ıssız, Sokaklar sessiz Sokakla...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Apak']::text[], 8.5, '{"poet":"Abdullah Apak","poet_slug":"abdullah-apak","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-ariyorum-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ne OLur', 'gel-ne-olur-eylem-ozdemir-6w77u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel ne olur; 

Koyma beni böyle ortalarda.

Sensiz yalnız,

Sensiz yarım,

Sensiz mutsuz ve huzursuzum bilesin

Bir el, bir ayak,

Yada yarım bir beden değil söylediğim.

Yarım bir kalp,

Yarım bir ruh demek istediğim.

Ne sevişmek ister canım,

Nede sıcak bir yatak,

Gecenin bir yarısı sana sımsıkı sarılmak', 'Gel ne olur;  Koyma beni böyle ortalarda. Sensiz yalnız, Sensiz yarım, Sensiz mutsuz ve huzursuzum bilesin Bir el, bir ayak, Yada yarım bir ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-ne-olur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Kadar', 'bu-kadar-eylem-ozdemir-8y8gg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelmeyeceksin biliyorum.

Bu kaçıncı gece; 

Bu kaçıncı sabah. 

Aylardan ne? , Hangi mevsim? 

Ne  farkeder.

Sensiz ne aylardan  Nisan, ne de mevsimlerden  bahar.

İşte hepsi bu kadar.', 'Gelmeyeceksin biliyorum. Bu kaçıncı gece;  Bu kaçıncı sabah.  Aylardan ne? , Hangi mevsim?  Ne  farkeder. Sensiz ne aylardan  Nisan, ne de m...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-kadar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Bak', 'gozlerime-bak-eylem-ozdemir-nzmyj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerini göster bana.

İçinde sevgi kırıntısı kalmayan gözlerini.

İşte o zaman inanırım sana,

Telefonda  bitti artık  demen kafi değil

Sesinin  titremesini hatlar  kötü diye savunma

Yüzüme  söyle  gerçekleri.

Ellerimi tut,  gözlerimin içine bak 

Sevmiyorum de, 

Bitsin de, 

Ayrılalım de

İşte o zaman  inanırım sana.

Ne zaman ki benle konuşurken

İçinde sevgi kuşunun çırpınışları durursa.

Esen rüzgarda  sesimi  duymazsan.

Yüzünü aydınlatan güneşte benim sıcaklığımı bulamazsan

İşte o zaman söyle bana.

Gözlerime bak, ama sakın ağlama.', 'Gözlerini göster bana. İçinde sevgi kırıntısı kalmayan gözlerini. İşte o zaman inanırım sana, Telefonda  bitti artık  demen kafi değil Sesin...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerime-bak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-volkan-i-ncel-lcu81', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çocukluğum

İşte bu çocukluğum 

Ninniyle uyuttuğum

Bir sevgi var aklımda 

Dizinde uyuduğum

Bu benim çocukluğum

Kötü gün unuttuğum

Bir oyun var hatrımda

Saklayıp koruduğum

Bir gün doğar günüme

Bir yel eser seherde

Annem olur yanımda

Saçları tüy yastığım

İşte bu çocukluğum

Ha varmış ha yokmuşum

Sonunu unuttuğum 

Mutluluk çocukluğum', 'Çocukluğum İşte bu çocukluğum  Ninniyle uyuttuğum Bir sevgi var aklımda  Dizinde uyuduğum Bu benim çocukluğum Kötü gün unuttuğum Bir oyun va...', ARRAY['Türk Edebiyatı','Şiir','Volkan İncel']::text[], 8.5, '{"poet":"Volkan İncel","poet_slug":"volkan-i-ncel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuklugum-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümü Ektim Gönlüme', 'gulumu-ektim-gonlume-eylem-ozdemir-tttc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülümü ektim gönlüme.

Bir nisan  sabahı tomurcuklandı.

Kan kırmızı bir gonca,

Zümrüt yeşili yaprakları vardı.

Gülümü ektim gönlüme.

Gölümde sen vardın, mevsim bahardı.

Sen güldün, gülüm güneş sanıp açtı.

Kelebekler güneşe kanıp, etrafında oynaştı.

Gülümü ektim gönlüme.

Sen gittin, güneş battı.

Gülüm bir bahar akşamı, ayazla kucaklaştı.', 'Gülümü ektim gönlüme. Bir nisan  sabahı tomurcuklandı. Kan kırmızı bir gonca, Zümrüt yeşili yaprakları vardı. Gülümü ektim gönlüme. Gölümde ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gulumu-ektim-gonlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Şekeri', 'elma-sekeri-eylem-ozdemir-yi6po', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş gibi girdin hayatıma,

Mutluluk verdin.

Toprak oldun, ısıttın beni.

Yağmur oldun, büyüttün.

Rüyalarıma pamuk pamuk bulut oldun.

Gecelerime yıldız  yıldız parıltı.

Ben küçük bir çocuktum,

Sen, elma şekeri oldun...', 'Güneş gibi girdin hayatıma, Mutluluk verdin. Toprak oldun, ısıttın beni. Yağmur oldun, büyüttün. Rüyalarıma pamuk pamuk bulut oldun. Geceler...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/elma-sekeri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Yalnızlık Olsun Ardakalan', 'varsin-yalnizlik-olsun-ardakalan-i-brahim-balci-revii', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘Sen iyi bir insansın’

Ne hatırlatıyor bu sözcükler sana

Emin değilsem de iyi bir insan olduğuma

Ne yalan söylüyorsun diyebilirim sana

Ne de iddia edebilirim yanlış olduğunu söylediklerinin

Biliyorsun

Ve bu yüzden de 

Daha baştan mahkumum ya kaybetmeye

Bilmez misin bunu ki,

Bilirsin ve bildiğin için söylersin zaten

Tercümesi söylediklerinin

Sen zaten kaybedenlerdensin

Acı duyarsın hep yüreğinde

Sızıdır hep sana miras kalan kalacak olan

Ben de acı vereceğim sana

Beni hep bıraktığım sızıyla hatırla

Yanağında yakamoz yaratan gamze

Göz dibindeki deniz feneri misali göz kırpan ben

Sesindeki bezginlik,bıkkınlık

Beyninde oluşmuş intihar takıntısıyla     

Bahtiyar eden beni ‘ruhum senindir’ deyişinle

Kırık hıçkırığınla aynı zamanda

Hatırlayacağım seni inan

Ve de geberinceye dek yaşayacağım o ince sızıyla

Sen git git git ki,

Haykırabileyim tüm gücümle

Ve de sessizce

Varsın,yalnızlık olsun ardakalan', '‘Sen iyi bir insansın’ Ne hatırlatıyor bu sözcükler sana Emin değilsem de iyi bir insan olduğuma Ne yalan söylüyorsun diyebilirim sana Ne de...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Balcı']::text[], 8.5, '{"poet":"İbrahim Balcı","poet_slug":"i-brahim-balci","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/varsin-yalnizlik-olsun-ardakalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Mavisinde', 'denizin-mavisinde-hatice-bediroglu-3qtkw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizin mavisinde 

Gözlerini görüyorum

Yeşil gözlerini

Derinliğinde

Sevginin sonsuzluğunu

Deniz demek

Sen demeksin

Bazen durgun

Yumuşacık sevecen 

Bazen hırçın delişmen

Karşısındakini yutmak istercesine 

Saldırgan

Ya da dalgalarının içinde 

Sevdiğini hapseden 

Bencilce 

Sadece benim olmalısın diyen

Denizin mavisinde

Gözlerini görüyorum 

Yeşil gözlerini

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005

www.haticebediroglu.net', 'Denizin mavisinde  Gözlerini görüyorum Yeşil gözlerini Derinliğinde Sevginin sonsuzluğunu Deniz demek Sen demeksin Bazen durgun Yumuşacık se...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/denizin-mavisinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-eylem-ozdemir-gxt6p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her saniye seni özledim sevgilim

Yokluğun içimdeki keskin bir bıçak  gibi

Sensiz aldığım her nefes bağrımı kanatmakta; 

Sensiz geceler tuzlu elleriyle yaralı yüreğimi okşamakta.

Ağzımdan çıkan kelimeler,

Aslında gönlümden kopanlardır.

Anlatmak zor be sevgilim,

Anlatılamayan çoğu şeyler, sadece iki kişi arasında yaşanmaktadır.

Seni çok özledim sevgilim,

Kanadı kırık bir kuşun gök yüzünü özlediği gibi

Rüzgarı tenimde hissetmek gibi seni özlemek

Sensizlik kırık bir kanat,

Kırık bir kanat ölüm demek.

Seni çok özledim sevgilim.

Sensizlik yaşanmamış bir gün,

Boşa geçen zaman,

Gereksiz yüzlerce nefes,

Ve sensizlik küçücük bir kafes.

Neşeli bir ilk bahar sabahı kopan fırtına,

Güneş sonrası karanlık,

Tatlı bir meltem sonrası dondurcu tipi.

Sensizlik mutluluk şarkıları arasında, ürpertici baykuş sesi...', 'Her saniye seni özledim sevgilim Yokluğun içimdeki keskin bir bıçak  gibi Sensiz aldığım her nefes bağrımı kanatmakta;  Sensiz geceler tuzlu...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sensizlik-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Bildiğin Gibi', 'her-sey-bildigin-gibi-eylem-ozdemir-xh32m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şey bildiğin gibi

Hiç değişmedim

Yüzüm hala aynı

Beni bıraktığında ayağımda olan pabuçları giyiyorum hala

Havalar sen gideli epey değişti.

Ne yağmur yağmur gibi yağıyor

Nede rüzgar rüzgar gibi esiyor

Hava bile hava olmaktan çıkmış.

Sanki öldürmek için öksürtüyor..', 'Her şey bildiğin gibi Hiç değişmedim Yüzüm hala aynı Beni bıraktığında ayağımda olan pabuçları giyiyorum hala Havalar sen gideli epey değişt...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-sey-bildigin-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-hatice-bediroglu-eg2z0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günümün aydınlığı 

Duygularımın coşkusu 

Heyecanlarımın 

Doruk noktası

Uykularımın 

Mahmurluğu

Hayatımın anlamı 

Sensiz... 

Seni içiyorum şu an

Bir yudum birayla beraber 

Yediğim bademin tadındasın

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005

www.haticebediroglu.net', 'Günümün aydınlığı  Duygularımın coşkusu  Heyecanlarımın  Doruk noktası Uykularımın  Mahmurluğu Hayatımın anlamı  Sensiz...  Seni içiyorum şu...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgilim-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç', 'hic-eylem-ozdemir-n97xm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hiç hatalarında boğulduğun oldu mu? 

ya sonra kahrolduğun? 

pişman olup da mahvolduğun? 

kendi elinle kazdın mı hiç mezarını? 

hiç kendine ağladın mı? 

hiç  bedenin ölüme giderken,

sen bir kenarda bakakaldın mı? 

hiç idam sehpasına kaderim diye baktın mı? 

istedin mi hiç ölmeyi,

sorunlardan kurtulmak için gömülmeyi? 

hiç Azrail’ ini aradın mı, 

ölmek için  ona yalvardın mı? 

hiç yatağından daha çok, mezarını aradın mı? 

hiç ölümüne değil, yaşadığına acıdın mı? 

hiç karanlık dehlizlerdeyken,

gelen bir parça umudu, balçıkla sıvadın mı? 

uçurumun kenarında ölümle dans ettin mi,

hiç hafifliği içinde hissettin mi? 

hiç ölüme sürüklediği halde, sevgiyi affettin mi?', 'hiç hatalarında boğulduğun oldu mu?  ya sonra kahrolduğun?  pişman olup da mahvolduğun?  kendi elinle kazdın mı hiç mezarını?  hiç kendine a...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hic-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-alim-eken-ohnit', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte çıkıp geliyorum çok uzaklardan

İki  elim iki böğrümde

Türkü söylüyorum.

Bir yaraya merhem çalar gibi,

Gülüyorum

Hasretlerimi toparlayıp

Sana geliyorum

Bir avuç cam bilye gibi 

Dizlerine dağılıveriyorum

Kedinin yün yumağıyla oynarcasına

Yürek sızımla oynuyorum

İşte çıkıp geliyorum çok uzaklardan

Yüküm dünyadan daha ağır

Geçmişte bir yerin

Bir zamanın 

Ve bir günahın

Tonlarca ağrısını taşıyorum

İşte çıkıp geliyorum çok uzaklardan

Bir ırmak gibi değil

Köpüre köpüre akan

Yolu yatağı belirsiz bir sel 

Yüreği ağzında bir serçe gibi geliyorum.

İki gözüm

Alın yazım

Yüreğimin orta yerinde bir yer,

Kabarmış alevler içinde yanmakta

Yangınlı bu canın kıvrak alevleri

Geçmiş alemlerden düşler toplamakta.

İşte çıkıp geliyorum çok uzaklardan

Ah 

Birde sen orada olsan.', 'İşte çıkıp geliyorum çok uzaklardan İki  elim iki böğrümde Türkü söylüyorum. Bir yaraya merhem çalar gibi, Gülüyorum Hasretlerimi toparlayıp...', ARRAY['Türk Edebiyatı','Şiir','Alim Eken']::text[], 8.5, '{"poet":"Alim Eken","poet_slug":"alim-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/geliyorum-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç Gözlerini Uyan Artık', 'ac-gozlerini-uyan-artik-hatice-bediroglu-esva6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aç gözlerini uyan artık! 

Bak, seni görmeye geldim 

Yanımda sevgimi getirdim

Yanımda tutkularımı getirdim 

Yanımda yaşamımı getirdim

Hepsini sana sunmak için 

Aç gözlerini uyan artık! 

Çok bekledim ben

Şu anın gelmesi için 

Gecelerce uykusuz kaldım

Düşüncelerimde hep sen

Karşılaşacağımız  anın

Hayaliyle geçti günlerim

Aç gözlerini uyan artık! 

Bundan sonra misafir gibi 

Geliş gidişler yok 

Gözyaşları sel olmayacak 

Hüzünlü ayrılıklarda

Bak! 

Valizimde yanımda

İnan sevgilim bu son

Temelli kalmaya geldim

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005

www.haticebediroglu.net', 'Aç gözlerini uyan artık!  Bak, seni görmeye geldim  Yanımda sevgimi getirdim Yanımda tutkularımı getirdim  Yanımda yaşamımı getirdim Hepsini...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ac-gozlerini-uyan-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimi Kemiriyor Bu Amansız İllet', 'i-cimi-kemiriyor-bu-amansiz-i-llet-eylem-ozdemir-9dlay', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimi kemiriyor bu amansız illet.

Lime lime parçalanıyorum sanki.

Ne umudum kaldı yarına,

Nede mücadelem var yaşamak adına.

Yavaş yavaş tüketiyor beni sensizlik.

İçin için kanıyor yara.', 'İçimi kemiriyor bu amansız illet. Lime lime parçalanıyorum sanki. Ne umudum kaldı yarına, Nede mücadelem var yaşamak adına. Yavaş yavaş tüke...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/icimi-kemiriyor-bu-amansiz-illet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğim', 'yuregim-hatice-bediroglu-9ttqa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gece uçuyorsun, 

Bir tanem. 

Yüreğim, 

Valizlerini topladı. 

Seninle beraber, 

Gitmeye hazır. 

Umarım, 

Yanına almadan gitmezsin.

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Bu gece uçuyorsun,  Bir tanem.  Yüreğim,  Valizlerini topladı.  Seninle beraber,  Gitmeye hazır.  Umarım,  Yanına almadan gitmezsin. www.hat...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yuregim-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk', 'i-lk-eylem-ozdemir-u9l78', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen benim ilk,umudumsun

 daha önce hiç ummadığım

 ayarıpta görmediğim

 hissedipte sevmediğim

 sen benim ilk,  hayalimsin

 görmemezlikten gelemediğim

 olmayacağını düşünemediğim

 uyanmaktan korktuğum

 sen benim ilk,mutluğumsun

 hayatı avuçlarından içtiğim

 dünyaya kolarınla sarıldığım

 yaşamayı gözlerinden gördüğüm

 sen benim ilk,  çiçeğimsin

 görüp te unutamadığım

 sevipte kopartamadığım

 sulamaktan bıkmadığım', 'sen benim ilk,umudumsun  daha önce hiç ummadığım  ayarıpta görmediğim  hissedipte sevmediğim  sen benim ilk,  hayalimsin  görmemezlikten gel...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilk-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Gibi', 'yagmur-gibi-alim-eken-9iqvr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yol akıver

Akıver bir yol saçlarımdan

Yağmur olup mavi gökten ak yerden

Yağıver.

Yağıver

Özlem yüklü gözelerime.

Şafak tenli saçlarıma.

Yağıver.', 'Bir yol akıver Akıver bir yol saçlarımdan Yağmur olup mavi gökten ak yerden Yağıver. Yağıver Özlem yüklü gözelerime. Şafak tenli saçlarıma. ...', ARRAY['Türk Edebiyatı','Şiir','Alim Eken']::text[], 8.5, '{"poet":"Alim Eken","poet_slug":"alim-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-ergun-terzioglu-w3eq6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öz benliğimin sonsuz türevi,

Kısır döngümsün...

Karabasanımsın yıllardır

Yalnızlık...! 

Yalnızlık; 

Varoluşta yalnızlık,

Yaşamda yalnızlık,

Ölümde yalnızlık,

Kabirde yalnızlık,

Sorgu sualde yalnızlık,

Cennette yalnızlık,

Cehennemde yalnızlık...

Cehennemin dibine kadar yolun var

Yalnızlık...!', 'Öz benliğimin sonsuz türevi, Kısır döngümsün... Karabasanımsın yıllardır Yalnızlık...!  Yalnızlık;  Varoluşta yalnızlık, Yaşamda yalnızlık, ...', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizlik-224-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sensiz Yaşamak', 'seni-sensiz-yasamak-eylem-ozdemir-eyn8p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir bu geceleri uyuyamamam

Yatağım neden bu kadar soğuk bana

Uykum neden  düşman 

Nedir bu içimdeki sıkıntı

Kafi değil mi bu ıstırap

Kafi değil mi sen varken seni sensiz yaşamak.', 'Nedir bu geceleri uyuyamamam Yatağım neden bu kadar soğuk bana Uykum neden  düşman  Nedir bu içimdeki sıkıntı Kafi değil mi bu ıstırap Kafi ...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-sensiz-yasamak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Hediye', 'bana-hediye-hatice-bediroglu-g5gcx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gece,

Seninle beraber yattım, 

Yatağımda... 

Kokularını bırakmışsın, 

Bana hediye, 

Yorganımda yastığımda. 

Öyle güzel... 

Baş döndürücü, 

Kışkırtan, 

Bir koku ki! 

Beni sana çeken, 

Canım.

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Dün gece, Seninle beraber yattım,  Yatağımda...  Kokularını bırakmışsın,  Bana hediye,  Yorganımda yastığımda.  Öyle güzel...  Baş döndürücü...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bana-hediye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardelen', 'kardelen-eylem-ozdemir-m8o1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beklediğin  cevap  bir kaç santim uzağımda

Hani uzamsan, belki de yazan ellerine değecek ellerim

Gerçi sen yazmadan da okurum ben düşüncelerini

Okumak için  gözümdeki perdeyi  azıcık aralamam yeterli

Cesaretim olsa, çoktan ezberime almıştım söyleyemediklerini.

Bembeyaz bir sayfa  açmışsındır bana

Simsiyah mürekkebiyle hazırdır kalemin, 

Kesin ve dönüşü olmayan bir karara.

Ahh birde elini titreten çocuk kalbin olmasa

Nasılda zemheri ayazı dökülür kaleminden,

Yeni tormucuklanmaya başlamış bu sevdaya..

Hani bazen,  olmayacağına bile bile olmuş gibi davranırsın ya.

İşte, sevmeyeceğini bile bile  seviyorum seni.

Tıpkı, güneşi  görmek için ayaza teslim olmuş kardelen gibi...', 'Beklediğin  cevap  bir kaç santim uzağımda Hani uzamsan, belki de yazan ellerine değecek ellerim Gerçi sen yazmadan da okurum ben düşünceler...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kardelen-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Gitme Zamanı', 'zaman-gitme-zamani-gulay-yildiz-3lf1r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'iki adım ötede son ayak izlerin 

Üstünden geçiversem

Sanacaklar ki; 

İzindeyim...

Gittiğin yere gölgeni de götür! 

Gölgende kalmaktansa 

/ Daha iyi /

Bir çukura gömülüp küreklerce 

Toprak solumak... 

Burda kalanlarla şölen 

/ Bir de /

Götüremediğin gülücüğünle 

Kadeh tokuşturmak benim derdim... 

Zaman gitme zamanı 

Sen ve sana aitlikler, 

Artık çekilebilirler...', 'iki adım ötede son ayak izlerin  Üstünden geçiversem Sanacaklar ki;  İzindeyim... Gittiğin yere gölgeni de götür!  Gölgende kalmaktansa  / D...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yıldız']::text[], 8.5, '{"poet":"Gülay Yıldız","poet_slug":"gulay-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-gitme-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir', 'kim-bilir-eylem-ozdemir-rhskv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim bilir, belki bu yazdığım son şiir,

Belki bilinir,

Belki de tahta bir masanın üstünde eskir.

Bu yazdığım son şiir,

Belki bir rüzgar bulur,

Belki de adres bilir, 

Kim bilir, belki de sana getirir.

Bana kalırsa can alır,

Büyük bir acı kalır, 

Bilirim her zaman yarıdadır.

Kim bilir, belki  bu yazdığım son şiir.

Tahta bir masanın üstünde eskir,

Belki de güveler kemirir,

Kağıt toz gibi erir.

Camdan giren rüzgar alır götürür,

Duyguları doğduğu yerde savurur, 

Kim bilir, belki o rüzgar içimi kavurur,

Kim bilir belki de beni sensizliğe savurur...', 'Kim bilir, belki bu yazdığım son şiir, Belki bilinir, Belki de tahta bir masanın üstünde eskir. Bu yazdığım son şiir, Belki bir rüzgar bulur...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kim-bilir-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-alim-eken-79tka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey yaz mevsiminin sıcaklığı

Yakmayın yüreğimi, yakamazsınız.

Çünkü bir alev parçası gibi saplandı

Onun sıcak, kor  gözleri bir yerlerime

Beni benden eden

Hesapsız, zamansız akışımdır.

Elet be kara gözlüm.

Alevler yuttu, yutacak gibi

Zaman hasrete doyurmamaya niyetli.

Kır ne olur bu karanlık zincirleri

Sonra bırak dizginleri gevşesin.

Bırak yüreklerimiz birlikte yol tepsin.', 'Ey yaz mevsiminin sıcaklığı Yakmayın yüreğimi, yakamazsınız. Çünkü bir alev parçası gibi saplandı Onun sıcak, kor  gözleri bir yerlerime Ben...', ARRAY['Türk Edebiyatı','Şiir','Alim Eken']::text[], 8.5, '{"poet":"Alim Eken","poet_slug":"alim-eken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-gozlum-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-eylem-ozdemir-26piu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne sevdalar yaşadı bu gönül,

Ve ne şiirler döküldü bu yürekten

En güzellerini seni dinlerken yazdım.

Bir başkaydın benim için,

Sevdalı bir adın ve müzik kokan bir ruhun vardı.

Ne saman seni dinlesem,

İçimdeki sevda köpürür.

Gözlerim uzaklara dalar, 

Alev alev yanardım.

Yağmur bana yağardı, ben yağmura ağlardım.', 'Ne sevdalar yaşadı bu gönül, Ve ne şiirler döküldü bu yürekten En güzellerini seni dinlerken yazdım. Bir başkaydın benim için, Sevdalı bir a...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-511-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilesin', 'bilesin-hatice-bediroglu-n6j76', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen öyle tatlısın ki! 

Beni yine gülümsettin

Gelişin ile

Kara bulutları dağıtıverdin

İçimi üşüten fırtınalar

Sıcacık...

Melteme dönüşüverdiler

Senmişsin gibi

Sarıp sarmaladılar ruhumu

Güneş açtı içimde o an

Ağaçlar çiçeğe vurdu

Ve ben seninle

Dolup taştım hiç durmadan

Sevdiğimsin, canımsın

Sevincimsin bilesin

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005

www.haticebediroglu.net', 'Sen öyle tatlısın ki!  Beni yine gülümsettin Gelişin ile Kara bulutları dağıtıverdin İçimi üşüten fırtınalar Sıcacık... Melteme dönüşüverdil...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilesin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-doner-ozeke-yye6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allahın izniyle ben geldim size 

Şiirlerimi getirdim saf dize dize 

Guruba üyeyim ne gerek söze 

Benden selam olsun grup hepinize 

Davetsiz üyeyim kalmaya geldim 

Dostların halini sormaya geldim

Hainler var ise kovmaya geldim 

Bayrağım altında ölmeye geldim 

Bayrağıma rengini şehidim vermiş

Genceçik yaşında toprağa girmiş

Vatana yan bakan hangi hainmiş

Bayrağım uğrunda ölmeye geldim 

                DÖNER TEMÜR   

                   09.02.2005

                       ANKARA', 'Allahın izniyle ben geldim size  Şiirlerimi getirdim saf dize dize  Guruba üyeyim ne gerek söze  Benden selam olsun grup hepinize  Davetsiz ...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bayragim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Geleceği Belli Olmaz Hüznün', 'nereden-gelecegi-belli-olmaz-huznun-eylem-ozdemir-wixz5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nereden geleceği belli olmaz hüznün.

En olmadık yerde çıkar karşına.

Kader öyle bir oyun  oynar ki sana.

En sevdiğin yıkar seni bir anda.

Bin kahkaha mutlu eder seni,

Sonra bir söz öldürür.

Hayat bu, sevmediğin kişi küstürür

En sevdiğin ise öldürür.', 'Nereden geleceği belli olmaz hüznün. En olmadık yerde çıkar karşına. Kader öyle bir oyun  oynar ki sana. En sevdiğin yıkar seni bir anda. Bi...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nereden-gelecegi-belli-olmaz-huznun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksin', 'gideceksin-hatice-bediroglu-szjqy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapıyı açıyorum,

Gülen yüzünle karşımdasın. 

İçimde bir heyecan fırtınası, 

Yüreğim daha bir hızlı atarken, 

Gülümsüyorum tüm sevgimle. 

Çantanı alıyorum elinden, 

İçeri süzülüveriyorsun. 

İtirazlarına fırsat vermeden, 

Kucaklıyorum seni. 

Biliyorum sen canlısın, 

Ve yanımdasın. 

Kucakladığım ve öptüğüm sensin, 

Ve yine biliyorum ki… 

Birkaç gün sonra gideceksin.

www.haticebediroglu.net

(Şiirlerimin hepsi Noter tasdiklidir)', 'Kapıyı açıyorum, Gülen yüzünle karşımdasın.  İçimde bir heyecan fırtınası,  Yüreğim daha bir hızlı atarken,  Gülümsüyorum tüm sevgimle.  Çan...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gideceksin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Sev ki', 'oyle-bir-sev-ki-eylem-ozdemir-gykr5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle bir sevgi düşün ki,

 kitaplarda yazılmamış olsun; 

öyle bir sevki, 

senin sence bir anlamı olmasın; 

 öyle bir bak ki, 

bakışlarında bütün duyguların  yolculuk ediyor olsun; 

 öyle bir inan ki,

 inançsızlar bile inanmadıklarından şüpheye düşsün; 

öyle bir sahiplen ki,

Azrail bile onun üzerinde hak sahibi olmadığını hissetsin; 

öyle bir sevgi yaşa ki,

 senin  yaşadığın yanında ne leyla ile mecnunun adı hatırlansın nede romeo ile juliet''in; 

 geriye öyle bir sevgi bırak ki,

 senden sonrakiler dönüp, erişilmez sevgiyi senden örnek alsın....', 'Öyle bir sevgi düşün ki,  kitaplarda yazılmamış olsun;  öyle bir sevki,  senin sence bir anlamı olmasın;   öyle bir bak ki,  bakışlarında bü...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oyle-bir-sev-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paslı Gece…', 'pasli-gece-zulfikar-yapar-kaleli-apndb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Gene hasret ile inler de bülbül

Melanet tükenmez görünmez emen

Gece fidanının ucundaki gül

İçimdeki sevda renkli yasemen

Artık dinmez gönlümüzü ağrısı

Bu gönle nar yağar, nur yağmaz gülüm

Nedir ıstırabın bize çağrısı

Öksüz mehtaplarda ay doğmaz gülüm

Dalgalar sessizce sahili yalar

Bir türlü uğramaz yokuşu düze

Duygular bir ıssız uykuya dalar

Paslı gece nasıl döner gündüze

Ağlamaz mı gaflet arşa varınca

Karanlık biter mi ağarmazsa tan

Sis gelip de duyguları sarınca

Şafaklar tülünü çeker ufuktan

Mazlumun rızk diye yuttuğu kazık

Ur oldu beynime yaramı deştim

Umuttur yolcuya en tatlı azık

Ben düşen yıldızla beraber düştüm

Sevda tüllerini titretir sızım

Gönlüme gül ekip çöpe attınız

Yok artık o benim kınalı kuzum

Soysuzların sürüsüne kattınız', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Gene hasret ile inler de bülbül Melanet tükenmez görünmez emen Gece fidanının ucundaki gü...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/pasli-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşçi Memur Bir Olalım', 'i-sci-memur-bir-olalim-doner-ozeke-ovaod', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelin millet bu ortamda birlik olalım 

Haklıya alkış haksızlığa dur diyelim 

Emeği sömürenlere artık zincir vuralım 

60 milyon işci ve memurunu gördünmü 

Aynı bürolarda sıra sıra onlar oturur 

Bazıları milyonları götürür at yaşırı toto loto 

On dönüm bostan yan gel yat be Osman 

60 milyon işçi ve memurunu gördünmü 

Memur bilmez siyaseti geçim düşler kötü kötü 

Maliye vermez ikramiye,mesai nede ödenti 

Çöz bulmaca salla başı bu ayda aldın maaşı 

Altmış milyon işçi ve memurunu gördünmü 

İşçi memur adaleti bürolara artık siz getirin 

Birlik olun masalarda kardeş kardeş oturun 

Bu gün git ne demekmiş artık bunu bitirin

Altmış milyon işçi ve memurunu gördünmü 

Sendikası disiplini işverenin kesin ipini 

Çalışmayıp tembel dolaşan boş vereni 

Bu gün olmaz  yarın gel vatandaş diyeni 

Altmış milyon işçi ve memurunu gördünmü 

Döner yeter bitir artık  tüketme sen özünü

Şiirinde kalır hiç bulunmaz bunun çözümü 

Yıllar yılı ben tükettim bundan böyle özümü 

Altmış milyon işçi ve memurunu gördünmü 

                    DÖNER ÖZEKE     

                        09.02.2005', 'Gelin millet bu ortamda birlik olalım  Haklıya alkış haksızlığa dur diyelim  Emeği sömürenlere artık zincir vuralım  60 milyon işci ve memur...', ARRAY['Türk Edebiyatı','Şiir','Döner Özeke']::text[], 8.5, '{"poet":"Döner Özeke","poet_slug":"doner-ozeke","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/isci-memur-bir-olalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir', 'bir-deniz-tugce-unluturk-c0wvq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kanım bileklerimden süzülüyor

Ellerime bakıyorum 

Senden çaldığım kalbin kıpkırmızı olmuş

Tıpkı bana verdiğin güller gibi

Sana olan aşkımın alevi gibi

Bedenimi saran ateşin gibi

Gözlerim kararıyor

Kendimi, kendimle birlikte seni de kaybediyorum galiba

Sonsuz bir karanlıktayım şimdi

Aklıma geliyor ilklerim, en güzel anılarım

İlk sarılışımız, ilk öpüşmemiz

Kimbilir yaşayacak daha ne çok ilklerim vardı

Ama geri dönüşüm yok, burdan çıkışım yok

Affet beni sevgilim

Güçsüzüm, korkularıma yenik düştüm

Ama bilirsin acılara dayanamadığımı

Sakın şüphe etme sana olan sevgimden

Seni deli gibi sevdim ve hala seviyorum

Düşünüyorum da gerçekten çok mutlu ettin beni

Ama artık gitme vakti geldi

Sonsuz karanlığın daha da derinlerindeyim şimdi

Hala seni düşünüyorum ve yalnızca seni istiyorum

Karanlığı beyaz bir örtü sarıyor

Elimi tutuyor birisi

Sen mi geldin? 

Hayır gelme, yaptığım bu aptalca şeye sen de dahil olma

Sen hep hayatta kal, hep gül

Her şeyin en iyisi senin olsun

Gelme, çünkü ben en iyi değilim

Ben mükemmel değilim

Ama sen öylesin...

O beyaz örtünün altında sen de varsın aslında

Senle dolu anılar ve senle dolu kocaman bir kalp

Biliyorum ben bencilim hatta aptalın tekiyim

Affet beni sevgilim bırak yalnız gideyim

Çünkü ben sana layık değilim

Sonsuz karanlıkta çürürken bedenim

Hala seninim ve hep senin olacağım', 'Kanım bileklerimden süzülüyor Ellerime bakıyorum  Senden çaldığım kalbin kıpkırmızı olmuş Tıpkı bana verdiğin güller gibi Sana olan aşkımın ...', ARRAY['Türk Edebiyatı','Şiir','Deniz Tuğçe Ünlütürk']::text[], 8.5, '{"poet":"Deniz Tuğçe Ünlütürk","poet_slug":"deniz-tugce-unluturk","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bir-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-eylem-ozdemir-gv57l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklının alamayacağı şeyler yaşayacaksın,

Mantığının kavrayamayacağı saplantıların olacak,

Kalbinin  gümbür gümbür attığını hissedeceksin

Kulaklarındaki  ateş  bedenini yakacak,

Kesik kesik nefes almaya başlayacaksın,

Ruhun bedeninin içinde   kapana kısılmışçasına haykıracak,

Çırpındıkça   daha  derinlere  batacaksın,

Ayrılık neymiş anlayacak  aşka lanetler yağdıracaksın,

Pembeler yalan, siyahlar gerçekmiş anlayıp,

Oturup sahte göz yaşlarınla, çaresizliğine ağlayacaksın.', 'Aklının alamayacağı şeyler yaşayacaksın, Mantığının kavrayamayacağı saplantıların olacak, Kalbinin  gümbür gümbür attığını hissedeceksin Kul...', ARRAY['Türk Edebiyatı','Şiir','Eylem Özdemir']::text[], 8.5, '{"poet":"Eylem Özdemir","poet_slug":"eylem-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aglayacaksin-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
